INSERT INTO `books` (`id`, `title`, `author`, `release_date`, `isbn`, `pdfUrl`, `owner`, `cover_image`, `linked_images`, `description`, `likes`, `shares`, `views`, `genre`, `downloads`, `public`) VALUES
(15, 'Conseils pour la vie quotidienne.', 'Ellen G. White', '2027-07-29', NULL, '/konektem/uploads/documents/6a6a932fa83fa.pdf', 'admin@konektem.net', 349, NULL, 'Les quatre chapitres que nous vous offrons sont la conclusion du\r\nmagnifique ouvrage Rayons de Santé. Ces lignes ont apporté une\r\naide efficace à des milliers de personnes qui désiraient faire de\r\nleur vie un succès. Elles sont présentées sous ce petit format afin\r\nde rendre plus facile la lecture et la méditation des précieux\r\nconseils qu\'elles renferment. Chaque chapitre est une véritable\r\nmine de joyaux inestimables, recelant des enseignements utiles à\r\nlire et à relire pour faire face aux réalités et aux contingences\r\nhumaines. Ils indiquent aux coeurs bien disposés le moyen d\'être\r\nen harmonie avec soi-même, avec les autres et avec Dieu.', 0, 0, 0, 'Religion', 2, 1),
(16, 'Comprendre l\'Homme en 3 Dimensions.', 'Pasteur Olivier Derain', '2026-07-29', NULL, '/konektem/uploads/documents/6a6ac3d4a17b4.pdf', 'admin@konektem.net', 350, NULL, 'Depuis la deuxième moitié du 20ème siècle, les découvertes scientifiques ont été plus bien plus\r\nabondantes que pendant les 6 millénaires qui nous ont précédés, c\'est à dire depuis la création\r\nd\'Adam et Eve. L\'homme est capable aujourd\'hui d\'aller sur la lune et d\'observer les particules\r\natomiques; nous pouvons communiquer avec un téléphone par satellite, de n\'importe quel\r\nendroit du monde, même d\'un coin désertique où l\'électricité n\'est pas branchée, nous pouvons\r\nrejoindre deux capitales de pays différents en quelques heures par avion. Mais, malgré ces\r\ndécouvertes, bien qu\'elle ait dépensé des sommes d\'argent gigantesques pour essayer de percer\r\nle mystère humain au travers de la psychologie, la science n\'a pas progressé dans la découverte\r\nintérieure de l\'homme.', 0, 0, 0, 'Religion', 3, 1),
(17, 'Père Riche Père Pauvre.', 'ROBERT T. KIYOSAKI', '0000-00-00', NULL, '/konektem/uploads/documents/6a6ac6c5ef7bd.pdf', 'admin@konektem.net', 351, NULL, 'Ayant deux pères pour me conseiller me donna l’occasion de choisir\r\nentre des points de vue opposés : ceux d’un homme riche et ceux d’un\r\nhomme pauvre.', 0, 0, 0, 'Finance', 0, 1),
(18, 'L\'histoire Du Mariage.', 'JOHN & LISA BEVERE', '2026-07-20', NULL, '/konektem/uploads/documents/6a6ac8158616d.pdf', 'admin@konektem.net', 352, NULL, 'Vous pouvez demander,\r\n“Pourquoi un autre message sur le mariage?” Ceci\r\nétait également notre propre réaction. Il y a trois raisons pour lesquelles nous\r\navons écrit ce livre.\r\nPremièrement nous avons senti DIEU nous conduire à le faire. Suivant, nos\r\nenfants et notre équipe nous l’ont demandé. Et finalement, plusieurs parmi\r\nvous l’avez aussi réclamé.\r\nNous avons senti qu’il y ', 0, 0, 0, 'Mariage', 0, 1),
(19, 'Le plan divin pour un mariage heureux.', 'Roderick C. Meredith', '2026-07-29', NULL, '/konektem/uploads/documents/6a6ac99f1ea7b.pdf', 'admin@konektem.net', 353, NULL, 'Il existe des « clés » et des principes essentiels, qui peuvent vous aider à avoir un mariage heureux!\r\nLà réussite de votre mariage dépend de votre bonne volonté à les utiliser dans votre vie personnelle.', 0, 0, 0, 'Mariage', 1, 1),
(20, 'Les hommes qui ne cédèrent pas.', 'La Bible pour enfants', '2026-07-30', NULL, '/konektem/uploads/documents/6a6acd3f4efa0.pdf', 'admin@konektem.net', 354, NULL, 'Le roi Nabucodonosor fit construire une grande statue d\'or. C\'était de l\'or de la tête aux pieds.\r\nPeut être que le roi avait oublié le rêve que Dieu lui avait envoyé et qui lui disait que son royaume doré ne durerait pas pour l\'éternité.', 0, 0, 0, 'Religion', 11, 1),
(21, 'The laws of human nature Book by Robert Greene ( PDFDrive )', 'Robert Greene', '2018-06-03', NULL, '/konektem/uploads/documents/6a704baa2eabc.pdf', 'admin@konektem.net', 355, NULL, '', 0, 0, 0, 'psychology', 1, 1),
(22, 'OceanofPDF.comThe_Son_of_Neptune_-_Rick_Riordan', 'Rick Riodan', '2011-10-24', NULL, '/konektem/uploads/documents/6a72f8224078b.pdf', 'bjorn', 358, NULL, '', 0, 0, 0, 'Fiction', 3, 1),
(23, '_OceanofPDF.com_The_Mark_of_Athena_-_Rick_Riordan', 'Rick Riodan', '2026-08-06', NULL, '/konektem/uploads/documents/6a743d84f3afc.pdf', 'DannyCrood', 367, NULL, '', 0, 0, 0, 'Fiction', 0, 0);
