INSERT INTO `events` (`id`, `title`, `description`, `eventDate`, `location`, `price`, `eventImage`, `owner`, `likes`, `shares`, `image_id`, `event_date`, `product_id`, `venue`, `address`, `max_attendees`, `public`) VALUES
(4, 'DETANT KRETYEN', 'Randevou chak vandredi nan Dèlma 75 pou w koze ak atis prefere w yo, tande istwa la vi yo, motivasyon ak pasyon yo.', '2025-12-24', 'DELMAS 75', 0, 37, 'admin@konektem.net', 3, 3, 37, '2025-12-24', 11, NULL, NULL, NULL, 1),
(7, 'STAND UP FOR LYNDA JOSEPH', 'Dans un élan de solidarité qui dépasse les murs du sanctuaire, l’Église Rendez-Vous Christ, en collaboration avec Media Levanjil, Konektem, À l’Unisson et Lophane Project, convie le public à un concert exceptionnel le 14 décembre 2025. Proposé au prix symbolique de 1 000 gourdes, cet événement vise à soutenir Lynda Joseph à travers une soirée où musique, foi et compassion s’uniront pour porter un message d’espérance.\r\nLes participants seront également invités à renforcer cet acte de générosité par des dons additionnels, afin de contribuer encore davantage à cette noble cause.', '2025-12-14', 'Rendez-Vous Christ', 2, 128, 'admin@konektem.net', 5, 0, 128, '2025-12-14', 12, NULL, NULL, NULL, 1),
(8, 'JEZI OOO - NESLIN DESTILHOMME GONAIVES', '<p>Nan vil Gonayiv, yon gwo randevou adorasyon tanmen pare pou make fen ane a. Jou k ap samdi 6 desanm 2025 lan, a 4ï¿½ nan lapremidi, nan Pak Vincent. @neslindestilhomme ap tann nou tout nan yon bouyon adorasyon, ki se Konsï¿½ ï¿½ï¿½Jezi Ohï¿½ï¿½ a. Yon Aktivite ki rasanble plizyï¿½ atis ak gwoup kretyen, tankou Rod Ume Dieujuste, @joyclerfderisier, @loutchina_music, Zï¿½n Pa Fï¿½ Moun Band ak Wency Le Slameur. Caribbean Worshippers envite piblik la, jï¿½n kou granmoun, fanmi kou zanmi, pou pa rate randevou sa a. Si w ap chï¿½che yon kote pou w rekonekte ak Bondye, renouvle lafwa w epi amize w nan prezans Bondye, Konsï¿½ ï¿½ï¿½Jezi Ohï¿½ï¿½, nan Gonayiv se kote w dwe ye a</p>', '2025-12-06', 'GONAIVES', 0, 131, 'admin@konektem.net', 0, 1, 131, '2025-12-06', 13, NULL, NULL, NULL, 1),
(9, 'SIMIANE RUACH TOUR', 'SIMIANE Ruach Tour. live performance: Jean Jean, Esther Desi, Transfomasyon Band.\r\n\r\n \r\nRéservez Vos billets maintenant sur eventbrite 👇👇\r\nhttps://www.eventbrite.com/e/1966354383895?aff=oddtdtcreator', '2025-12-07', 'NEW JERUSALEM EVANGELICAL BAPTIST CHURCH', 0, 134, 'admin@konektem.net', 1, 6, 134, '2025-12-07', 14, NULL, NULL, NULL, 1),
(10, '6e edition Caribbean Worshippers', '<div class=\"xdj266r x14z9mp xat24cr x1lziwak x1vvkbs x126k92a\">\r\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t1f/2/16/27a1.png\" alt=\"&acirc;ž&iexcl;&iuml;&cedil;\" width=\"16\" height=\"16\"></span> Ce grand rendez-vous spirituel, organis&eacute; par le psalmiste Neslin Destilhomme, connu pour mobiliser des milliers de fid&egrave;les &agrave; chacune de ses initiatives, r&eacute;unira cette ann&eacute;e des adorateurs et des leaders chr&eacute;tiens venus d&rsquo;Ha&iuml;ti, des &Eacute;tats-Unis et du Canada.<br><br></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\">Cette rencontre spirituelle vise &agrave; cr&eacute;er un espace de louange et de pri&egrave;re favorisant une connexion profonde &agrave; la pr&eacute;sence de Dieu et la croissance spirituelle des participants. La 6e &eacute;dition, organis&eacute;e autour du th&egrave;me &laquo; BENI BENI N&Egrave;T &raquo;, annonce une programmation de haut niveau, selon les pr&eacute;cisions de <span class=\"html-span xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs\"><a class=\"x1i10hfl xjbqb8w x1ejq31n x18oe1m7 x1sy0etr xstzfhl x972fbf x10w94by x1qhh985 x14e42zd x9f619 x1ypdohk xt0psk2 x3ct3a4 xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz xkrqix3 x1sur9pj x1fey0fg x1s688f\" tabindex=\"0\" role=\"link\" href=\"https://web.facebook.com/profile.php?id=100063886113458&amp;__cft__[0]=AZZ9Mi5EY7jV6JhwKdvRWBCP7k2OfAsaKoJMZcqwH5LmR8zYphbZSwYw3yXYdRNrxPxDrQt3-dSNdrUfYKjnASY-XamECrDNSh6UH7EHGW4MooM1fsHkqRyHSbZhQTEOTSKqiKClzeD8QfwO6oVpcVikCRbwuptfY6s5XI932MDEQcTLB_-wgMGaI2GEfWE885A&amp;__tn__=-]K-R\"><span class=\"xt0psk2\"><span class=\"xjp7ctv\">Neslin Destilhomme</span></span></a></span></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\">L&rsquo;&eacute;v&eacute;nement rassemblera un panel d&rsquo;adorateurs et de leaders spirituels engag&eacute;s &agrave; conduire le peuple dans un moment intense de communion et d&rsquo;&eacute;dification spirituelle.<br><br></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\">KONEKTEM s&rsquo;engage &agrave; vous informer de chaque &eacute;tape et de tous les d&eacute;tails de ce grand rendez-vous spirituel. Restez connect&eacute;s.<br><br></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t4b/2/16/1f4cc.png\" alt=\"&eth;&Yuml;&ldquo;&OElig;\" width=\"16\" height=\"16\"></span> Informations et dons</div>\r\n<div dir=\"auto\">Zelle : 954 336 9155</div>\r\n<div dir=\"auto\">PayPal : <a href=\"mailto:neslindestilhome87@gmail.com\">neslindestilhome87@gmail.com</a><br><br></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t63/2/16/270d.png\" alt=\"&acirc;&oelig;&iuml;&cedil;\" width=\"16\" height=\"16\"></span> R&eacute;daction : Vanauscheca P. Bouzy<br><br></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\"><span class=\"html-span xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs\"><a class=\"x1i10hfl xjbqb8w x1ejq31n x18oe1m7 x1sy0etr xstzfhl x972fbf x10w94by x1qhh985 x14e42zd x9f619 x1ypdohk xt0psk2 x3ct3a4 xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz xkrqix3 x1sur9pj x1fey0fg x1s688f\" tabindex=\"0\" role=\"link\" href=\"https://web.facebook.com/hashtag/konektem?__eep__=6&amp;__cft__[0]=AZZ9Mi5EY7jV6JhwKdvRWBCP7k2OfAsaKoJMZcqwH5LmR8zYphbZSwYw3yXYdRNrxPxDrQt3-dSNdrUfYKjnASY-XamECrDNSh6UH7EHGW4MooM1fsHkqRyHSbZhQTEOTSKqiKClzeD8QfwO6oVpcVikCRbwuptfY6s5XI932MDEQcTLB_-wgMGaI2GEfWE885A&amp;__tn__=*NK-R\">#konektem</a></span></div>\r\n<div dir=\"auto\"><span class=\"html-span xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs\"><a class=\"x1i10hfl xjbqb8w x1ejq31n x18oe1m7 x1sy0etr xstzfhl x972fbf x10w94by x1qhh985 x14e42zd x9f619 x1ypdohk xt0psk2 x3ct3a4 xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz xkrqix3 x1sur9pj x1fey0fg x1s688f\" tabindex=\"0\" role=\"link\" href=\"https://web.facebook.com/hashtag/toutkotenenp%C3%B2tkil%C3%A8?__eep__=6&amp;__cft__[0]=AZZ9Mi5EY7jV6JhwKdvRWBCP7k2OfAsaKoJMZcqwH5LmR8zYphbZSwYw3yXYdRNrxPxDrQt3-dSNdrUfYKjnASY-XamECrDNSh6UH7EHGW4MooM1fsHkqRyHSbZhQTEOTSKqiKClzeD8QfwO6oVpcVikCRbwuptfY6s5XI932MDEQcTLB_-wgMGaI2GEfWE885A&amp;__tn__=*NK-R\">#toutkotenenp&ograve;tkil&egrave;</a></span></div>\r\n</div>', '2026-03-14', 'Nassau, Bahamas', 0, 208, 'admin@konektem.net', 1, 1, 208, '2026-03-14', 15, NULL, NULL, NULL, 1),
(11, 'Worship Room 2e edition', '<div class=\"xdj266r x14z9mp xat24cr x1lziwak x1vvkbs x126k92a\">\r\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t1f/2/16/27a1.png\" alt=\"&acirc;ž&iexcl;&iuml;&cedil;\" width=\"16\" height=\"16\"></span> Apr&egrave;s une &eacute;dition de 2025 marqu&eacute;e par un v&eacute;ritable succ&egrave;s et une forte mobilisation du public, Worship Room s&rsquo;appr&ecirc;te &agrave; faire son grand retour avec une nouvelle &eacute;dition port&eacute;e par l&rsquo;unit&eacute;, la foi, la reconnaissance et l&rsquo;adoration. <br><br>La deuxi&egrave;me &eacute;dition se tiendra le dimanche 5 avril 2026, &agrave; l&rsquo;H&ocirc;tel Karibe, P&eacute;tion-Ville, autour du th&egrave;me biblique inspir&eacute; de Matthieu 28:6 : &laquo; Il n&rsquo;est point ici ; car Il est ressuscit&eacute;, comme Il l&rsquo;avait dit. &raquo;<br><br></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\">L&rsquo;an dernier, &agrave; l&rsquo;occasion de la f&ecirc;te de P&acirc;ques, l&rsquo;&eacute;quipe du Worship Room avait propos&eacute; un programme simple, mais pr&eacute;par&eacute; avec soin. Dans une salle soigneusement d&eacute;cor&eacute;e et comble, adorateurs, artistes, pasteurs, invit&eacute;s et fid&egrave;les avaient v&eacute;cu un moment de communion profonde, marqu&eacute; par une pr&eacute;sence divine ressentie intens&eacute;ment.<br><br></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\">Cette ann&eacute;e encore, les organisateurs annoncent une rencontre fid&egrave;le &agrave; l&rsquo;ADN de Worship Room : authentique, intense et spirituellement transformatrice. Les autres d&eacute;tails du programme seront communiqu&eacute;s ult&eacute;rieurement.<br><br></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\">KONEKTEM assurera la couverture exclusive de cet &eacute;v&eacute;nement et vous tiendra inform&eacute;s de son &eacute;volution en temps r&eacute;el. <br><br>Restez connect&eacute;s !<br><br></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t63/2/16/270d.png\" alt=\"&acirc;&oelig;&iuml;&cedil;\" width=\"16\" height=\"16\"></span> R&eacute;daction : Vanauscheca P. Bouzy<br><br></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\"><span class=\"html-span xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs\"><a class=\"x1i10hfl xjbqb8w x1ejq31n x18oe1m7 x1sy0etr xstzfhl x972fbf x10w94by x1qhh985 x14e42zd x9f619 x1ypdohk xt0psk2 x3ct3a4 xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz xkrqix3 x1sur9pj x1fey0fg x1s688f\" tabindex=\"0\" role=\"link\" href=\"https://web.facebook.com/hashtag/konektem?__eep__=6&amp;__cft__[0]=AZZm_vAePuBYZ6OOfa0sdcT27F4sBNF990pyQAt6KrcpI-WAxxFQm2eJSEC9K9BuqS4sYPGMlOiZUnuPc82yfHgFeTrhmsPu2EZm6jq8PYs9rVZei_oD83RjXuE07_nvfeyd66BSrvDwJ0BIc50t2l8xcIDTHTp8tZD5HT0JJL2ycfV24LhnRO75bkg1IFVPmlA&amp;__tn__=*NK-R\">#KONEKTEM</a></span></div>\r\n<div dir=\"auto\"><span class=\"html-span xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs\"><a class=\"x1i10hfl xjbqb8w x1ejq31n x18oe1m7 x1sy0etr xstzfhl x972fbf x10w94by x1qhh985 x14e42zd x9f619 x1ypdohk xt0psk2 x3ct3a4 xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz xkrqix3 x1sur9pj x1fey0fg x1s688f\" tabindex=\"0\" role=\"link\" href=\"https://web.facebook.com/hashtag/toutkotenenp%C3%B2tkil%C3%A8?__eep__=6&amp;__cft__[0]=AZZm_vAePuBYZ6OOfa0sdcT27F4sBNF990pyQAt6KrcpI-WAxxFQm2eJSEC9K9BuqS4sYPGMlOiZUnuPc82yfHgFeTrhmsPu2EZm6jq8PYs9rVZei_oD83RjXuE07_nvfeyd66BSrvDwJ0BIc50t2l8xcIDTHTp8tZD5HT0JJL2ycfV24LhnRO75bkg1IFVPmlA&amp;__tn__=*NK-R\">#ToutKoteNenp&ograve;tKil&egrave;</a></span></div>\r\n</div>', '2026-04-05', 'Karibe Convention Center ', 0, 210, 'admin@konektem.net', 0, 1, 210, '2026-04-05', 16, NULL, NULL, NULL, 1),
(12, 'Samedi de la Grace', '<div class=\"xdj266r x14z9mp xat24cr x1lziwak x1vvkbs x126k92a\">\r\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t1f/2/16/27a1.png\" alt=\"&acirc;ž&iexcl;&iuml;&cedil;\" width=\"16\" height=\"16\"></span>D&eacute;j&agrave; tr&egrave;s attendu, ce rendez-vous figure parmi les &eacute;v&eacute;nements majeurs du mois de f&eacute;vrier au sein de la communaut&eacute; &eacute;vang&eacute;lique ha&iuml;tienne.</div>\r\n<div dir=\"auto\">&nbsp;</div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\">Cette deuxi&egrave;me &eacute;dition entend poursuivre les m&ecirc;mes objectifs : valoriser les talents artistiques chr&eacute;tiens, encourager l&rsquo;expression culturelle positive et diffuser un message fort de paix, d&rsquo;unit&eacute; et d&rsquo;esp&eacute;rance, dans un contexte social o&ugrave; les rep&egrave;res demeurent essentiels.</div>\r\n<div dir=\"auto\">&nbsp;</div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\">Le programme vise &eacute;galement &agrave; mettre en lumi&egrave;re les talents artistiques chr&eacute;tiens, tout en promouvant un message de paix, d&rsquo;unit&eacute; et d&rsquo;esp&eacute;rance, dans un contexte social marqu&eacute; par de nombreux d&eacute;fis.</div>\r\n<div dir=\"auto\">&nbsp;</div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\">La premi&egrave;re &eacute;dition de &laquo; Samedi de la Gr&acirc;ce &raquo; avait mobilis&eacute; des centaines de milliers de participants, en pr&eacute;sentiel comme en ligne, autour de moments de louange, d&rsquo;adoration et d&rsquo;action de gr&acirc;ce, r&eacute;unissant fid&egrave;les, organisateurs et partenaires dans un m&ecirc;me &eacute;lan spirituel.</div>\r\n<div dir=\"auto\">&nbsp;</div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/tf0/2/16/1f449.png\" alt=\"&eth;&Yuml;&lsquo;&permil;\" width=\"16\" height=\"16\"></span> Plus de d&eacute;tails seront communiqu&eacute;s prochainement.</div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\">Pour le sponsoring et les partenariats :</div>\r\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/tec/2/16/1f4de.png\" alt=\"&eth;&Yuml;&ldquo;ž\" width=\"16\" height=\"16\"></span> +509 38 48 70 85 | 31 22 33 37 | 37 55 84 26</div>\r\n<div dir=\"auto\">&nbsp;</div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t63/2/16/270d.png\" alt=\"&acirc;&oelig;&iuml;&cedil;\" width=\"16\" height=\"16\"></span> R&eacute;daction : Vanauscheca P. Bouzy</div>\r\n<div dir=\"auto\">&nbsp;</div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\"><span class=\"html-span xdj266r x14z9mp xat24cr x1l