(16, 'ASTHARMONIE lève le suspense en invitant le public à la vente signature de son album « ENKONPARAB »', '<p>ASTHARMONIE l&egrave;ve le suspense en invitant le public &agrave; la vente signature de son album &laquo; ENKONPARAB &raquo;, pr&eacute;vue pour le 25 octobre 2026, &agrave; 3h PM, au Karibe Convention Center, au prix de 25 $ US.</p>\r\n<p>Apr&egrave;s plusieurs semaines d&rsquo;attente, le moment tant attendu approche. Astharmonie invite le public &agrave; venir vivre une exp&eacute;rience unique &agrave; l&rsquo;occasion de la vente signature de son premier album.</p>\r\n<p>Rendez-vous donc le 25 octobre 2026, &agrave; 3h PM, au Karibe Convention Center, pour cette grande rencontre. Ne vous contentez pas d&rsquo;en entendre parler, venez vivre ENKONPARAB !</p>', NULL, 'Karibe Convention Center ', 25, NULL, 'admin@konektem.net', 0, 0, 377, '2026-10-25', 2, NULL, NULL, NULL, 0);
INSERT INTO `events` (`id`, `title`, `description`, `eventDate`, `location`, `price`, `eventImage`, `owner`, `likes`, `shares`, `image_id`, `event_date`, `product_id`, `venue`, `address`, `max_attendees`, `public`) VALUES
(17, 'LIAJECH, CJFPH et KONEKTE M vous donnent rendez-vous à la Journée Internationale de la Jeunesse 2026, Samedi 15 août 2026 à l\'Hôtel Ritz Kinam II.', '<p>LIAJECH, CJFPH et KONEKTE M vous donnent rendez-vous &agrave; la Journ&eacute;e Internationale de la Jeunesse 2026, Samedi 15 ao&ucirc;t 2026 &agrave; l\'H&ocirc;tel Ritz Kinam II.</p>\r\n<p><br>&Agrave; l\'occasion de la Journ&eacute;e Internationale de la Jeunesse, la Ligue des Associations de Jeunesse Chr&eacute;tienne d\'Ha&iuml;ti (LIAJECH), en partenariat avec la CJFPH et le m&eacute;dia KONEKTE M, convie toute la jeunesse ha&iuml;tienne &agrave; une journ&eacute;e exceptionnelle de r&eacute;flexion, de formation et de c&eacute;l&eacute;bration autour du th&egrave;me : &laquo; La jeunesse : une g&eacute;n&eacute;ration qui s\'engage. &raquo;</p>\r\n<p>Pr&eacute;vu pour le samedi 15 ao&ucirc;t 2026, &agrave; partir de 9h AM, &agrave; l\'H&ocirc;tel Ritz Kinam II, cet &eacute;v&eacute;nement r&eacute;unira des jeunes issus de diff&eacute;rents horizons afin de promouvoir le leadership, l\'engagement citoyen et la participation active des jeunes dans le d&eacute;veloppement d\'Ha&iuml;ti.</p>\r\n<p>Les participants auront droit &agrave; un programme vari&eacute;, alliant conf&eacute;rences, &eacute;changes, comp&eacute;titions et activit&eacute;s culturelles, dans une ambiance propice &agrave; l\'apprentissage, au r&eacute;seautage et &agrave; l\'inspiration.</p>\r\n<p>Que vous soyez &eacute;tudiant, membre d\'une association, jeune professionnel ou simplement engag&eacute; pour l\'avenir de la jeunesse, cette journ&eacute;e est une occasion unique de vous former, de partager vos exp&eacute;riences et de contribuer &agrave; b&acirc;tir une g&eacute;n&eacute;ration consciente, responsable et d&eacute;termin&eacute;e &agrave; faire la diff&eacute;rence.</p>\r\n<p>Le 15 ao&ucirc;t, prenez part au mouvement. La jeunesse s\'engage, et votre place est parmi nous !</p>', NULL, 'Hotel Ritz Kinam 2', 0, NULL, 'admin@konektem.net', 0, 0, 378, '2026-08-15', 3, NULL, NULL, NULL, 0),
(18, 'Eglise Roc Solide de Tabarre vous convie à une semaine de consécration, d\'adoration et d\'enseignements bibliques à l\'occasion de la Kadosh Conférence 2026', '<p>L\' Eglise Roc Solide de Tabarre vous convie &agrave; une semaine de cons&eacute;cration, d\'adoration et d\'enseignements bibliques &agrave; l\'occasion de la Kadosh Conf&eacute;rence 2026.</p>\r\n<p>Du 9 au 16 ao&ucirc;t 2026, de 4 h &agrave; 7 h PM, venez vivre des moments intenses dans la pr&eacute;sence de Dieu &agrave; travers des pr&eacute;dications, des moments de pri&egrave;re et des instants de communion fraternelle, anim&eacute;s par plusieurs serviteurs et servantes de Dieu.</p>\r\n<p>Que vous soyez en qu&ecirc;te d\'un renouveau spirituel, d\'encouragement ou d\'une communion plus profonde avec le Seigneur, cette conf&eacute;rence est un rendez-vous &agrave; ne pas manquer.</p>\r\n<p>Rendez-vous &agrave; l\'&Eacute;glise Roc Solide de Tabarre, 1, Impasse Roc Solide, Tabarre 27. Venez nombreux et invitez vos proches &agrave; partager cette exp&eacute;rience de foi exceptionnelle.</p>\r\n<p>#kadosh<br>#konektem<br>#toutkotenenp&ograve;tkil&egrave;</p>', NULL, 'Eglise Roc Solide de Tabarre', 0, NULL, 'admin@konektem.net', 0, 0, 379, '2026-09-13', 4, NULL, NULL, NULL, 0),
(19, 'Ishama Gospel a l’honneur de convier la presse, les médias, ainsi que l’ensemble de ses partenaires et artistes collaborateurs à une conférence de presse qui se tiendra le samedi 15 août 2026 à 11h AM', '<p>Dans le cadre du lancement officiel du grand &eacute;v&eacute;nement \"911\", Ishama Gospel a l&rsquo;honneur de convier la presse, les m&eacute;dias, ainsi que l&rsquo;ensemble de ses partenaires et artistes collaborateurs &agrave; une conf&eacute;rence de presse qui se tiendra le samedi 15 ao&ucirc;t 2026 &agrave; 11h AM, au CDFTL (Centre Diplomatique Famille Tabernacle de Louange), Waney 93, Carrefour.</p>\r\n<p>Cette rencontre permettra de d&eacute;voiler les d&eacute;tails du programme pr&eacute;vu, de pr&eacute;senter les moments forts de \"911\" et de partager les grandes lignes de cette initiative.</p>\r\n<p>La pr&eacute;sence des journalistes, m&eacute;dias, partenaires et artistes collaborateurs est vivement souhait&eacute;e pour marquer ensemble le coup d&rsquo;envoi officiel de ce grand &eacute;v&eacute;nement.</p>\r\n<p>NB : Les accr&eacute;ditations pour la couverture m&eacute;diatique officielle du concert seront d&eacute;livr&eacute;es exclusivement aux journalistes et m&eacute;dias pr&eacute;sents lors de cette conf&eacute;rence de presse.</p>\r\n<p>#konektem<br>#toutkotenenp&ograve;tkil&egrave;</p>', NULL, 'Centre Diplomatique Famille Tabernacle de Louange', 0, NULL, 'admin@konektem.net', 0, 0, 380, '2026-09-15', 5, NULL, NULL, NULL, 0),
(20, 'Rolande Louis en Concert', '', NULL, 'Eglise Rendezvous christ', 1500, NULL, 'JoFlungBouzy', 0, 0, 383, '2026-08-23', 6, NULL, NULL, NULL, 1),
(21, 'L\'Église Sur Le Rocher vous invite à une semaine de célébration et d\'action de grâce à l\'occasion de son 37e anniversaire, du 23 au 30 août 2026', '<p>&nbsp;&Agrave; l\'occasion de son 37e anniversaire, L\'Eglise Sur Le Rocher Ha&iuml;ti a la joie de vous inviter &agrave; prendre part &agrave; une semaine de c&eacute;l&eacute;bration et d\'action de gr&acirc;ce, qui se d&eacute;roulera du 23 au 30 ao&ucirc;t 2026, sous le th&egrave;me &laquo; &Eacute;b&eacute;n&eacute;zer &raquo;, inspir&eacute; de 1 Samuel 7:12 : &laquo; Jusqu\'ici, l\'&Eacute;ternel nous a secourus. &raquo;</p>\r\n<p>Cette semaine sera marqu&eacute;e par des moments intenses de louange, d\'adoration, de pri&egrave;re, de pr&eacute;dication et de reconnaissance envers Dieu pour Sa fid&eacute;lit&eacute; durant ces 37 ann&eacute;es de minist&egrave;re. Le point culminant de cette c&eacute;l&eacute;bration sera la Grande C&eacute;l&eacute;bration, pr&eacute;vue le dimanche 30 ao&ucirc;t 2026, de 7h30 &agrave; 11h AM.</p>\r\n<p>Votre pr&eacute;sence sera pour nous un v&eacute;ritable honneur et une immense joie !</p>\r\n<p>#konektem<br>#toutkotenenpotkile</p>', NULL, 'Eglise sur le Rocher ', 0, NULL, 'admin@konektem.net', 0, 0, 385, '2026-08-23', 7, NULL, NULL, NULL, 0),
(22, 'WILIADEL DENERVIL : UNE DÉCENNIE DE CARRIÈRE, ET L’AVENTURE CONTINUE', '<p>WILIADEL DENERVIL : UNE D&Eacute;CENNIE DE CARRI&Egrave;RE, ET L&rsquo;AVENTURE CONTINUE.&nbsp;</p>\r\n<p>Apr&egrave;s le Canada, une r&eacute;cente &eacute;tape en France et un concert m&eacute;morable en R&eacute;publique dominicaine, Wiliadel Denervil poursuit son parcours et continue de multiplier les rendez-vous.</p>\r\n<p>Le 27 septembre 2026, c&rsquo;est au tour de Port-au-Prince de c&eacute;l&eacute;brer ses 10 ans de carri&egrave;re, lors d&rsquo;un grand rendez-vous au Palais Municipal de Delmas, pr&eacute;sent&eacute; par Lophane\'s Project.</p>\r\n<p>📍 Palais Municipal de Delmas<br>📅 27 septembre 2026</p>\r\n<p>10 ANS, UNE VOIX, UNE HISTOIRE&hellip;<br>ET L&rsquo;AVENTURE CONTINUE.</p>\r\n<p>#konektem<br>#toutkotenenp&ograve;tkil&egrave;</p>', NULL, 'Palais Municipal de Delmas', 1000, NULL, 'admin@konektem.net', 0, 0, 387, '2026-09-27', 8, NULL, NULL, NULL, 0),
(23, 'CAJEBD en pique-nique 2026 : Rendez-vous, le samedi 29 Aout 2026', '<p>Le quotidien nous laisse rarement le temps de souffler. Entre les &eacute;tudes, le travail et les pr&eacute;occupations de la vie, les occasions de se retrouver et de partager des moments authentiques deviennent de plus en plus rares. Et si vous vous accordiez une journ&eacute;e pour tout oublier ?</p>\r\n<p>CAJEBD vous donne rendez-vous le samedi 29 ao&ucirc;t 2026, &agrave; la Quisqueya Christian School (Delmas 75), pour la deuxi&egrave;me &eacute;dition de &laquo; CAJEBD en Pique-Nique &raquo;. &nbsp;Au fil de la journ&eacute;e, les participants auront l\'occasion de prendre part &agrave; une programmation vari&eacute;e, jeux et animations, musique, karaok&eacute;, conf&eacute;rence-d&eacute;bat, s&eacute;ance photo, d&eacute;gustation, d&eacute;fis et plusieurs autres activit&eacute;s.&nbsp;</p>\r\n<p>Les places sont tr&egrave;s limit&eacute;es. Afin de garantir le bon d&eacute;roulement de l\'activit&eacute;, seul un effectif restreint sera accueilli. &nbsp;R&eacute;servez votre place d&egrave;s maintenant en contactant le (+509) 39 99 3281 ou le (+509) 35 26 8581. Ne laissez pas passer cette occasion de vivre une journ&eacute;e diff&eacute;rente avec la famille CAJEBD-B&eacute;thel !</p>\r\n<p>#konektem<br>#toutkotenenp&ograve;tkil&egrave;</p>', NULL, 'Quisqueya Christian School', 0, NULL, 'admin@konektem.net', 0, 0, 388, '2026-08-29', 9, NULL, NULL, NULL, 0),
(24, 'Be united', '<p>Be united is the best way to grow and to succeed.</p>', NULL, 'Online', 2, NULL, 'admin@konektem.net', 0, 0, 391, '2026-09-03', 10, NULL, NULL, NULL, 0),
(25, 'FÈ PASYON W POU FOTOGRAFI VIN YON KONPETANS PWOFESYONÈL ', '<p>F&Egrave; PASYON W POU FOTOGRAFI VIN YON KONPETANS PWOFESYON&Egrave;L&nbsp;</p>\r\n<p>AutoFocus envite w enskri nan nouvo sesyon f&ograve;masyon li pou jwenn yon S&egrave;tifika nan Fotografi Nimerik, atrav&egrave; yon pwogram ki f&egrave;t pou akonpaye w soti nan nivo fondamantal rive nan nivo pwofesyon&egrave;l.</p>\r\n<p>Pandan f&ograve;masyon an, w ap aprann prensip esansy&egrave;l fotografi yo, teknik pou byen itilize kamera, jesyon limy&egrave;, kadraj, konpozisyon ak met&ograve;d pwofesyon&egrave;l pou pwodui imaj ki gen kalite gras ak seri pratik nou yo.</p>\r\n<p>⚠️ Staj Garanti 📸</p>\r\n<p>📅 Nouvo sesyon: 3 ak 4 okt&ograve;b 2026<br>🕚 Or&egrave;: Samdi ak dimanch, 11&egrave; AM pou 2&egrave; PM<br>💵 Fr&egrave; enskripsyon: 5 000 goud<br>📍 Adr&egrave;s: 34, Puits Blain 30, Delmas 75</p>\r\n<p>✅ Ranpli f&ograve;m sa a pou w enskri:</p>\r\n<p>https://forms.gle/nzzWexHrtbrgb9xY6</p>\r\n<p>📲 Antre nan gwoup WhatsApp la pou w resevwa plis enf&ograve;masyon:<br>https://chat.whatsapp.com/FGMG38BIZLwDWAWmPqG79N?s=cl&amp;p=i&amp;mlu=4&amp;ilr=4</p>\r\n<p>📞 Enf&ograve;masyon: +509 3122-3337<br>📧 Im&egrave;l: konekteminfo@gmail.com</p>\r\n<p>Pa rete s&egrave;lman d&egrave;y&egrave; kamera a:&nbsp;<br>aprann metrize l, kreye imaj ki pale epi prepare t&egrave;t ou pou travay tankou yon pwofesyon&egrave;l.</p>\r\n<p>#AutoFocus&nbsp;<br>#PhotographieNum&eacute;rique #FormationProfessionnelle&nbsp;<br>#Photographie&nbsp;<br>#NouvelleSession</p>\r\n<p>#konektem&nbsp;<br>#toutkotenenp&ograve;tkil&egrave;</p>', NULL, 'Adrès: 34, Puits Blain 30, Delmas 75', 5000, NULL, 'admin@konektem.net', 0, 0, 392, '2026-10-03', 24, NULL, NULL, NULL, 0),
(26, 'RENOUVEAU AP RIVE OKAP', '<p>&nbsp;RENOUVEAU AP RIVE OKAP</p>\r\n<p>Depi Renouveau soti, li deja f&egrave; yon b&egrave;l vwayaj&hellip;🌎</p>\r\n<p>Palais Municipal &mdash; Port-au-Prince&nbsp;<br>USA : Tampa &bull; Boston &bull; Fort Lauderdale<br>Canada : Montr&eacute;al &bull; Calgary<br>France</p>\r\n<p>E kounye a&hellip; se tou pa OKAP! 💃🏽🔥</p>\r\n<p>Apre tout vil sa yo, Barbara Cassamajor ap vin rankontre piblik Okap la pou yon nouvo vant-siyati alb&ograve;m &laquo; Renouveau &raquo;.</p>\r\n<p>📍 Nan Complexe Versailles, Okap<br>📅 20 septembre 2026</p>\r\n<p>Renouveau deja f&egrave; anpil chemen, men vwayaj la poko fini.✨</p>\r\n<p>Okap, &egrave;ske w pare pou w resevwa Renouveau??</p>\r\n<p>20 SEPTANM &mdash; COMPLEXE VERSAILLES.<br>RENOUVEAU RIVE LAKAY OU! 🎉</p>\r\n<p>#konektem<br>#toutkotenenp&ograve;tkil&egrave;</p>', NULL, 'Nan Complexe Versailles, Okap', 0, NULL, 'admin@konektem.net', 0, 0, 393, '2026-09-20', 25, NULL, NULL, NULL, 0),
(27, 'Venez glorifier le nom du Seigneur au concert « Le Cri des Adorateurs », le 11 octobre 2026.', '<p>Venez glorifier le nom du Seigneur au concert &laquo; Le Cri des Adorateurs &raquo;, le 11 octobre 2026.</p>\r\n<p>Le dimanche 11 octobre 2026 &agrave; 3h PM, MARKANAKY vous donne rendez-vous &agrave; l\'&Eacute;glise Communaut&eacute; du Royaume de DIEU, situ&eacute;e &agrave; Tabarre 52, Rue Caprice, pour le concert &laquo; Le Cri des Adorateurs &raquo;. Cette rencontre r&eacute;unira Cleestoven, Jennica, Angelo, St&eacute;phana, Yvens, M&eacute;lissa, Ps. Mardoch&eacute;, Fr. Derly ainsi que The Singers, autour d\'un temps de louange et d\'adoration. L\'entr&eacute;e est fix&eacute;e &agrave; 250 GHT.</p>\r\n<p>Le dimanche 11 octobre 2026 &agrave; 3h PM, MARKANAKY vous donne rendez-vous &agrave; l\'&Eacute;glise Communaut&eacute; du Royaume de DIEU, situ&eacute;e &agrave; Tabarre 52, Rue Caprice, pour le concert &laquo; Le Cri des Adorateurs &raquo;. Cette rencontre r&eacute;unira Cleestoven, Jennica, Angelo, St&eacute;phana, Yvens, M&eacute;lissa, Ps. Mardoch&eacute;, Fr. Derly ainsi que The Singers, autour d\'un temps de louange et d\'adoration. L\'entr&eacute;e est fix&eacute;e &agrave; 250 GHT.</p>', NULL, 'Eglise Communauté du Royaume de Dieu, tabarre 52, rue caprice', 25, NULL, 'admin@konektem.net', 0, 0, 399, '2026-10-11', 28, NULL, NULL, NULL, 0);
