INSERT INTO `interview` (`id`, `title`, `description`, `created_at`, `updated_at`, `image_id`, `views`, `shares`, `likes`, `personName`, `personTitle`, `interviewLength`, `interviewDate`, `video_id`, `guest_name`, `guest_title`, `duration`, `interview_date`) VALUES
(4, '“Plan Enmi an Echwe\": Une Mélodie Bénie d\'Espoir et de Foi.', 'Dans l\'étendue enrichissante de la musique évangélique haïtienne, une collaboration inspirée a pris forme, portant le nom significatif de \"Plan Enmi an Echwe\". Les talentueux artistes Jean Enock Louis et Sherline Dalberis largement reconnus dans le secteur évangélique, se sont unis pour créer une composition captivante, dédiée à inspirer et encourager les chrétiens à maintenir une foi inébranlable.\r\n\r\n\r\nÉvoluant au Canada tout en restant profondément liés à leur terre natale, Haïti, Jean Enock Louis et Sherline Dalberis, respectivement père et mère de famille, partagent leur talent et leur dévotion à travers un répertoire de musique évangélique très riche. La rencontre providentielle entre ces deux artistes a donné naissance à \"Plan Enmi an Echwe\".\r\n\r\n\r\nL\'histoire de cette collaboration exceptionnelle a pris racine et a pris vie grâce à une suggestion inspirée du maestro Samuel Joseph Pierre Paul, résidant au Canada. Témoin d\'une performance exceptionnelle de Sherline lors d\'un concert et conscient de la voix unique de Jean Enock Louis, l\'idée a germé et s\'est concrétisée.\r\n\r\n\r\nSelon les dires de Jean Enock Louis, compositeur de la chanson, son inspiration émane du Saint-Esprit, soulignant ainsi la direction divine dans la composition musicale. Sherline Dalberis, également imprégnée de la foi chrétienne, a joué un rôle essentiel en contribuant avec ses idées et ses encouragements.\r\n\r\n\"Plan Enmi an Echwe\" n\'est pas simplement une chanson, mais un hymne d\'espoir, porteur d\'un message profondément enraciné dans la foi, nous déclare Jean Enock Louis, ancien membre de la chorale Teknon Vox Mass Choir. Cette chanson évoque la protection divine face aux adversités. Sherline Dalberis, ancienne vedette du gospel Hoshama, aspire à encourager les croyants à rester confiants, conscients de la victoire divine sur le mal.\r\n\r\n\r\nMalgré les défis rencontrés par Enock et Sherline, la décision courageuse de créer un vidéoclip pour \"Plan Enmi an Echwe\" a été prise, démontrant leur engagement envers les mélomanes de la musique évangélique. L\'équipe derrière le clip vidéo a surmonté les obstacles de l\'hiver canadien avec dévouement, capturant l\'essence de la chanson. Jean Enock Louis et Sherline Dalberis privilégient la simplicité visuelle, permettant au message de la chanson de rayonner à travers chaque image. L\'énergie dégagée par les deux psalmistes dans la vidéo traduit l\'essence même du message qui compose la musique.\r\n\r\nEn dehors des projecteurs et de la scène, la production exceptionnelle de cette musique fortifiante est le fruit du travail d\'experts chevronnés. Le séquençage est réalisé avec habileté par Milot Joseph, accompagné d\'une chorale exceptionnelle composée de Sabine Lira, Marie Marthe Sima et Milot Joseph lui-même. Le studio d\'enregistrement responsable de cette création remarquable est affilié à Milot Music.\r\n\r\n\r\nLa collaboration entre Jean Enock Louis et Sherline Dalberis dans \"Plan Enmi an Echwe\" témoigne de leur engagement à créer des œuvres musicales évangéliques inspirantes et encourageantes pour les moments cruciaux.\r\n\r\n\r\nDes projets futurs sont envisagés, mais pour l\'instant, “Plan Enmi an Echwe” est disponible sur toutes les plateformes de streaming, notamment sur les chaînes YouTube de Jean Enock Louis et Sherline Dalberis.\r\n\r\n\r\nDans leur répertoire musical, Jean Enock Louis a enregistré trois (3) albums, tandis que Sherline Dalberis, avec deux (2) albums, voit chaque mélodie qu\'ils créent devenir une source d\'inspiration et de réconfort à travers le monde.\r\n\r\n\r\nKonekte M vous encourage à affermir votre foi à travers cette mélodie bénie d\'espoir et de foi.\r\n\r\nRédaction: Vanauscheca Bouzy\r\n\r\n#konektem\r\n#toutkotenenpotkile', '2025-11-29 02:13:27', '2026-04-26 12:37:37', 157, 0, 1, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(9, 'Bishop Gregory Toussaint lance la marche internationale « Souf pou Ayiti » après 110 000+ signatures.', 'Après avoir lancé une pétition qui a recueilli 110 000 signatures en moins d\'une semaine, Bishop Gregory Toussaint a lancé une marche qui a recueilli plus de 50 000 inscriptions dans ce même laps de temps.\r\n\r\nLa pétition «Souf Pou Ayiti » a atteint son objectif en l\'espace de quelques jours. Les organisateurs pensaient qu’elle prendrait 40 jours pour obtenir 100 000 signatures, mais c\'était sans compter l\'engouement suscité par cette initiative qui a eu un fort soutien en Haïti et dans la diaspora haïtienne. Résultat: jusqu\'à date, plus de 113 000 personnes ont déjà signé.\r\n\r\n\r\nPour capitaliser sur cette dynamique, Bishop Gregory Toussaint a proposé l\'organisation d\'une grande marche pour mobiliser les Haïtiens du monde entier sur la situation d\'Haïti.\r\n\r\n\r\n «En fait, indique le pasteur titulaire du Tabernacle de Gloire, j’ai reçu des directives de la part de Dieu pour une telle initiative, et plusieurs autres personnes me l’ont confirmé».\r\n\r\n\r\nCette marche, qui aura une ampleur internationale, aura plusieurs objectifs, selon Bishop Toussaint. Le premier objectif, indique-t-il, est d’inciter les citoyens ordinaires, les Amos, comme il les appelle en référence au prophète juif de la Bible, à prendre leur responsabilité dans la vie de la nation haïtienne.\r\n\r\n\r\n«Ce sont les citoyens ordinaires qui d’habitude apportent les changements, pas les élites qui, eux, préfèrent le statu quo. Le Mouvement des droits civiques aux USA a commencé par Rosa Parks, une couturière, une chrétienne», explique Gregory Toussaint.\r\n\r\n\r\n«Après l’arrestation de Parks, poursuit-il, les pasteurs américains se sont soulevés et c’est ainsi que le mouvement des droits civiques allait commencer avec l’église. Quand l’église combine la prière avec des actions, rien ne peut lui résister. L’église a été le fer de lance pour briser le système de ségrégation aux USA. \r\n Je crois que ce que l’église américaine a fait aux USA, l’église haïtienne peut le faire en Haïti».\r\n\r\n\r\nLe second objectif de la marche est de communiquer un message à la communauté internationale. «Le message est que nous sommes concernés par ce qui se passe en Haïti et que nous voulons faire partie de la solution», déclare le PDG de Radio Shekinah.\r\n\r\n\r\nIl a poursuivi en soulignant le rôle que la diaspora peut jouer notamment quand il s’agit d’exercer la pression sur la communauté internationale. «Haïti ne peut pas faire pression sur les Etats-Unis, le Canada et la France, mais la diaspora haïtienne le peut. Par exemple, aux USA, une grande partie de la diaspora haïtienne peut voter dans les élections américaines. Il y aura des élections en 2024. C’est le bon moment pour demander aux autorités américaines de mieux traiter Haïti car notre vote peut être décisif dans leurs élections».\r\n\r\n\r\n Troisièmement, la marche du 9 juillet vise à demander à identifier ceux qui financent les gangs en Haïti et à les pénaliser à travers le projet de loi S.396 du Sénat et le projet de loi HR 1684 de la Chambre des représentants, intitulé \"Haiti Criminal Collusion Transparency Act of 2023\". La marche appellera enfin au maintien du programme humanitaire de migration conditionnelle (Humanitarian Parole). \r\n\r\n\r\nRappelons que ce programme est remis en cause par plusieurs États américains qui ont intenté une action en justice contre l\'administration Biden, affirmant que le processus de migration conditionnelle est illégal.\r\n\r\n\r\nUn procès était précédemment prévu pour le 13 juin 2023 pour déterminer le sort du «Humanitarian Parole». Cependant une nouvelle date, le 24 août 2023, a été proposée pour ledit procès en attendant d\'être confirmée par une décision judiciaire.\r\n\r\n\r\n«La situation en Haïti est comparable à celle de l’Ukraine, donc si le programme est maintenu pour l’Ukraine, il ne fait aucun sens qu’il s\'arrête pour Haïti», a souligné Pasteur Toussaint.\r\n\r\n\r\nÀ ce jour, selon l\'ambassade américaine en Haïti, 39 000 Haïtiens ont été examinés et approuvés pour voyager dans le cadre du programme depuis le 5 janvier jusqu\'à la fin du mois d\'avril. \r\n\r\n\r\nLes organisateurs de la marche soutiennent que maintenir ce programme permettra de sauver des vies en offrant une voie légale et sûre aux Haïtiens cherchant refuge aux États-Unis.\r\n\r\n\r\nCette marche internationale se déroulera dans au moins plusieurs pays (Haïti, USA, Canada, République Dominicaine, Chili, France) et de nombreuses villes du monde (Miami, Orlando, Boston, New York, Atlanta, Philadelphie, New Jersey, Montréal, Paris, Santo-Domingo, Santiago) pour témoigner de l\'engagement de la communauté haïtienne mondiale à trouver une issue à la crise.\r\n\r\n\r\n«Le jour de l\'événement, qui sera un dimanche, nous allons marcher dans les rues après le service dominical avec des chaussures de sport», annonce Pasteur Toussaint.\r\n\r\n\r\n«Aux USA, poursuit-il, on marchera dans tous les États américains, principalement la Floride, New York, New Jersey, Massachusetts, où se trouve une forte population haïtienne. Pour les endroits où la population est moins importante, on leur demandera de se tenir devant un bâtiment gouvernemental. On marchera dans des villes comme Miami, Orlando, New York, Philadelphie, Paris, Montréal, Santo-Domingo, etc».\r\n\r\n\r\nEn Haïti, la marche se tiendra à Port-au-Prince, la capitale, à Grand-Goâve, Cap-Haïtien, Léogâne, Petit-Goâve, Jérémie, Les Cayes, Hinche, Jacmel, Gonaïves, Miragoâne, Mirebalais, Fort-Liberté et Saint-Marc.\r\n\r\n\r\nAussi, plus de 180 pasteurs d\'Haïti et de la diaspora se joindront à cette initiative. Parmi lesquels on peut citer: Samuel Robuste (Jacksonville), Eddy Gervais (Miami), Max Moïse Sauld (Haïti), Samuel Nicolas (New York), Phil Mercidieu (Fort Myers), Wilner Cayo (Canada), Wilner Prudent (Miami), Mullery Jean-Pierre (New York), Carlos Pierre (Miami), Malory Laurent (New York), Daniel Chery (Montréal), Caleb Barthélus (Montréal), Emmanuel Dessalines (Montréal), André Muscadin (Haïti), Delly Benson (Haïti).\r\n\r\n\r\nEn tout, 200 organisations, 350 pasteurs et 50 000 personnes se sont engagés à participer à la marche. Pour rappel, le ministère Shekinah avait lancé la pétition « Souf pou Ayiti » le 2 juin dernier, préoccupé par la nouvelle conjoncture haïtienne qui force les citoyens haïtiens à laisser leur quartier voire leur pays. Depuis juillet 2021, la situation en Haïti s\'est détériorée, marquée par une augmentation des enlèvements, des agressions, des violences sexuelles et des extorsions perpétrées par des gangs criminels, au point où les Nations unies ont comparé le niveau d\'insécurité du pays à celui d\'une zone en guerre.\r\n\r\n\r\nLa pétition « Souf pou Ayiti » avait été accueillie avec un grand enthousiasme par les Haïtiens de partout. Elle visait à aider les compatriotes en Haïti et ceux qui sont récemment entrés aux Etats-Unis par le biais du « Humanitarian Parole », soit le programme humanitaire de migration conditionnelle, lancé en janvier dernier par le président Joe Biden.\r\n\r\n\r\nLa marche se déroulera durant l\'événement «40 Jours de Jeûne» organisé par le ministère Shekinah dirigé par Bishop Gregory Toussaint.\r\n\r\nGregory Toussaint, PDG, entrepreneur, philanthrope, auteur de best-sellers et orateur haïtiano-américain, est le pasteur titulaire de Tabernacle de Gloire. Cette église, composée de 47 campus, compte 25 000 membres actifs locaux et 50 000 membres en ligne. \r\n\r\n\r\nEn tant que PDG et fondateur de Shekinah.fm, Gregory a accumulé plus de 4 millions d\'abonnés sur les médias sociaux et compte en moyenne 4 millions de vues par semaine. Ses émissions de radio touchent plus de 5 millions de foyers en Haïti. \r\n\r\n\r\nSon émission de télévision, \"Bishop G Live\", diffusée sur des réseaux en Amérique, en Europe, en Afrique et au Moyen-Orient, touche un nombre impressionnant de 500 millions de foyers dans le monde. Parlant couramment l\'anglais, le français, l\'espagnol et le créole haïtien, Gregory est diplômé en affaires (BS), en droit (LL.M) et en théologie (Th.M., D.E.A). Il est marié depuis 20 ans et a deux fils. Il réside avec sa famille à Miami, en Floride.\r\n\r\n\r\nRedaction: Jonel Juste', '2025-11-29 02:33:21', '2026-01-23 23:37:40', 162, 0, 2, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5, 'Et si le S.O.S Tour de Rosena J. Orys devenait l’une des plus grandes initiatives musicales haïtiennes de l’année ?', 'Née le 27 avril 1992 dans une famille chrétienne, Rosena Jocelin a grandi avec un rêve aussi lumineux que sa voix : devenir une chanteuse de cœur, capable de toucher les âmes, guérir les blessures et élever les esprits. Dès l’âge de 11 ans, elle foule les scènes haïtiennes à travers diverses chorales telles que Hallelujah Gospel et Jimla Gospel.\r\n\r\n\r\nMais c’est en 2016 que le public découvre une Rosena en solo, vibrante et habitée, grâce au titre marquant « Ou fè m ap viv ». Depuis lors, elle n’a cessé de gravir les échelons, mêlant foi et vécu collectif pour résonner au cœur d’un peuple haïtien blessé, souvent abandonné, mais toujours debout. En 2025, Rosena frappe un grand coup.\r\n\r\n\r\nS.O.S : une chanson, un cri, une vague d’espoir.\r\n\r\nLe 26 avril 2025, sur un beat afro entraînant, Rosena lance « S.O.S ». En moins d’une semaine, le titre envahit réseaux sociaux, rues, églises et plateformes de streaming. Deux mois plus tard, il cumule plus de 3,1 millions de vues sur YouTube, un exploit rare dans le milieu évangélique haïtien.\r\n\r\n\r\nMais ce succès fulgurant ne repose pas uniquement sur sa musicalité : S.O.S est un cri collectif, un appel spirituel et social. Alors qu’Haïti est plongée dans l’insécurité, la peur et les déplacements forcés, Rosena élève un S.O.S vers Dieu, un appel auquel le peuple répond massivement. Entre challenges, reprises, vidéos de prières, enfants et adultes, la chanson franchit toutes les barrières religieuses et sociales. Elle devient un hymne, une mélodie partagée avec émotion, mains levées ou pieds dansants.\r\n\r\n\r\nLe S.O.S Tour : un cri d’adoration pour Haïti et au-delà.\r\n\r\nLe 24 juillet 2025, dans une salle comble de l’hôtel El Rancho, Rosena J. Orys annonce officiellement le lancement du S.O.S Tour, une tournée d’adoration qui traversera Haïti et plusieurs pays étrangers. Elle est entourée de ses collaborateurs Lophane Laurent, Barbara Cassamajor, Penter Orys et Audner Martin, tous mobilisés pour porter cette grande initiative.\r\n\r\n\r\nOrganisée par l’Agence Alexandre, Lophane Project et Acordia Shipping, cette tournée vise à élever une voix musicale et spirituelle forte pour Haïti.\r\n\r\n« La musique est un cri d’alerte face aux souffrances du peuple haïtien. Ce cri, nous voulons qu’il touche tous les cœurs, croyants ou non, enfants comme adultes », déclare Rosena avec émotion.\r\n\r\n\r\nAu-delà de la musique, le S.O.S Tour se veut aussi un projet social engagé, tourné vers les enfants, les femmes et les familles vulnérables. Rosena annonce également un prochain album, qualifié de « prophétique », destiné à insuffler foi, espérance et engagement à une Haïti en quête de renouveau.\r\n\r\n\r\nUn concert inaugural vibrant au Palais Municipal de Delmas.\r\n\r\nLe dimanche 27 juillet 2025, le Palais Municipal de Delmas vibre au rythme du S.O.S Tour. Le public, venu en grand nombre, chante, danse et prie avec ferveur tout au long de la soirée. Rosena, accompagnée d’une équipe musicale solide et d’artistes invités tels que Barbara Cassamajor, Joy Clerf Derisier et Wiliadel Denervil, offre une performance riche en émotions, mêlant louanges profondes et rythmes entraînants.\r\n\r\n\r\nParmi les moments forts : la puissante interprétation de « Je bénirai l’Éternel » par Barbara Cassamajor, les chorégraphies spirituelles du groupe Adassa Dance, et un hommage touchant à Rosena par l’économiste Etzer Émile, qui lui offre un tableau en reconnaissance de son engagement. Le concert s’achève par une prestation magistrale de Rosena accompagnée d’un saxophoniste, emportant le public dans une adoration intense.\r\n\r\n\r\nUne tournée qui se vit aussi par la compassion : visite au CERMICOL.\r\n\r\nLe lundi 28 juillet, après son triomphe à Delmas, Rosena et son équipe, en collaboration avec le Flamboyant Restaurant, visitent le Centre de Rééducation Pénitentiaire des Mineurs en Conflit avec la Loi (CERMICOL). Cette action réunit plusieurs figures engagées du milieu évangélique, telles que Barbara Cassamajor, Joy Clerf Derisier, Wiliadel Denervil et David Morinvil.\r\n\r\n\r\nLe CERMICOL héberge actuellement environ 630 détenus, dont 96 mineurs, 174 femmes et jeunes filles, et 360 hommes adultes.\r\n\r\nAu programme : mini-concert, temps de prière, évangélisation et repas partagé avec les détenus.\r\n\r\n« Tout le monde mérite une part d’amour. Peu importe les erreurs commises, Dieu est toujours prêt à pardonner », déclare Rosena avec émotion.\r\n\r\n\r\nPour l’équipe, cette visite fut un moment fort, une invitation profonde à réfléchir sur la véritable signification de la liberté.\r\n\r\n\r\nCap-Haïtien a chanté sous la pluie !\r\n\r\nCe dimanche 3 août 2025, malgré la pluie, les Capois se sont rassemblés en masse au Complexe Versailles pour vivre la deuxième étape du S.O.S Tour. Barbara met le feu dès les premières notes avec Louwe Louwe, Loutchina fait lever les mouchoirs avec L ap beni w, pendant que Wiliadel et Joy embrasent la salle avec leurs titres phares.\r\n\r\n\r\nRosena J. Orys, très attendue, est accueillie avec ferveur. Son passage sur scène transforme l’atmosphère en un véritable lieu d’adoration. Chaque chanson résonne comme un cri de foi, et le public, transporté, chante, prie, adore. Un concert marqué par la pluie… mais surtout par la présence palpable de Dieu.\r\n\r\n\r\nUne musique évangélique qui dérange… mais qui libère\r\n\r\nToute onde puissante crée des remous. Lorsque le célèbre influenceur UncleKendjy publie un challenge autour de S.O.S, une vague de critiques surgit dans le milieu protestant :\r\n\r\n« Rosena pa dwe poste videyo sa yo. Pa gen limyè ak tenèb ansanm. »\r\n\r\nCe débat théologique soulève une question essentielle : jusqu’où la musique chrétienne peut-elle aller pour toucher ceux qui sont “dehors” ?\r\n\r\nRosena répond avec foi et assurance :\r\n\r\n« Se pa mwen ki chwazi mizik sa, se BONDYE ki mete l nan kè mwen. Se pou li sèvi ak li, jan li vle, lè li vle, ak moun li vle. »\r\n\r\nUn réveil en marche : une tournée pour les oubliés, les blessés, les affamés de sens\r\n\r\nLe S.O.S Tour ne s’adresse pas seulement aux chrétiens. Il parle à ceux que la société rejette, à ceux que les églises oublient, à ceux qui ne trouvent pas Dieu dans les discours, mais qui espèrent encore le sentir dans un chant, une vibration, une parole qui les comprend.\r\n\r\nAlors, doit-on voir dans S.O.S et sa tournée une révolution musicale ou une simple mode passagère ?\r\n\r\n\r\nEt si c’était le début d’un réveil spirituel, porté par une femme, une voix, un peuple en détresse ?\r\n\r\nEt si, enfin, la musique évangélique haïtienne faisait tomber ses murs, pour entrer dans les rues, les foyers… et dans les douleurs réelles du peuple ?\r\n\r\n\r\n\r\nRedaksyon:\r\n\r\nRonalson Bryan Blanfort\r\n\r\n\r\n\r\n#Sos\r\n\r\n#RosenaOrys\r\n\r\n#konektem\r\n\r\n#toutkotenenpotkilè', '2025-11-29 02:19:06', '2026-01-01 23:31:46', 158, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
