INSERT INTO `news` (`id`, `newsImg`, `newsTitle`, `newsDate`, `newsCategory`, `newsHeadline`, `fullContent`, `reads`, `likes`, `shares`, `featured_image_ids`, `image_id`, `title`, `category`, `headline`, `content`, `published_at`, `created_at`, `updated_at`, `author_id`) VALUES
(63, 326, '𝗟𝗮 𝗣𝗼𝗹𝗶𝗰𝗲 𝗡𝗮𝘁𝗶𝗼𝗻𝗮𝗹𝗲 𝗱’𝗛𝗮𝗶̈𝘁𝗶 𝗹𝗮𝗻𝗰𝗲 𝗼𝗳𝗳𝗶𝗰𝗶𝗲𝗹𝗹𝗲𝗺𝗲𝗻𝘁 𝘂𝗻𝗲 𝗰𝗮𝗺𝗽𝗮𝗴𝗻𝗲 𝗻𝗮𝘁𝗶𝗼𝗻𝗮𝗹𝗲 𝗱𝗲 𝘀𝗲𝗻𝘀𝗶𝗯𝗶𝗹𝗶𝘀𝗮𝘁𝗶𝗼𝗻 𝗽𝗼𝘂𝗿 𝗹𝗲 𝗿𝗲𝗰𝗿𝘂𝘁𝗲𝗺𝗲𝗻𝘁 𝗾𝘂𝗮𝗹𝗶𝘁𝗮𝘁𝗶𝗳 𝗱𝗲𝘀 𝗳𝗲𝗺𝗺𝗲𝘀.', '2026-05-22', 'security', 'La Police Nationale d’Haïti (PNH), en partenariat avec le Programme des Nations Unies pour le Développement (PNUD), l’Union Européenne et la firme Konekte M, a procédé au lancement officiel d’une vaste campagne de sensibilisation visant à promouvoir le recrutement qualitatif des femmes au sein de la PNH ainsi qu’à renforcer l’image institutionnelle de l’institution policière.', '<p class=\"p1\"><span class=\"s1\">La Police Nationale d&rsquo;Ha&iuml;ti (PNH), en partenariat avec le Programme des Nations Unies pour le D&eacute;veloppement (PNUD), l&rsquo;Union Europ&eacute;enne et la firme Konekte M, a proc&eacute;d&eacute; au lancement officiel d&rsquo;une vaste campagne de sensibilisation visant &agrave; promouvoir le recrutement qualitatif des femmes au sein de la PNH ainsi qu&rsquo;&agrave; renforcer l&rsquo;image institutionnelle de l&rsquo;institution polici&egrave;re.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Organis&eacute;e dans la salle de conf&eacute;rence du C3I, &agrave; la Direction G&eacute;n&eacute;rale de la PNH, cette activit&eacute; a r&eacute;uni plusieurs hauts responsables policiers, des repr&eacute;sentants d&rsquo;organisations internationales ainsi que diff&eacute;rents acteurs engag&eacute;s dans les questions de gouvernance, de s&eacute;curit&eacute; publique et d&rsquo;inclusion.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&Agrave; travers cette initiative, Konekte M, firme charg&eacute;e de la conception et de la mise en &oelig;uvre de la campagne, entend contribuer &agrave; une nouvelle vision de la Police Nationale d&rsquo;Ha&iuml;ti, une institution moderne, inclusive, professionnelle et davantage ouverte aux comp&eacute;tences f&eacute;minines dans les domaines strat&eacute;giques et sp&eacute;cialis&eacute;s.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Lors de la pr&eacute;sentation officielle de la campagne, le porte-parole de Konekte M, Frigain Marechal, a rappel&eacute; que le projet vise particuli&egrave;rement &agrave; encourager les jeunes femmes professionnelles, universitaires et techniciennes &agrave; int&eacute;grer les diff&eacute;rentes structures sp&eacute;cialis&eacute;es de la PNH. Il a &eacute;galement mis en &eacute;vidence les nombreux d&eacute;fis auxquels l&rsquo;institution fait face aujourd&rsquo;hui, notamment le manque de personnel qualifi&eacute; ainsi que les perceptions n&eacute;gatives v&eacute;hicul&eacute;es autour de la police nationale.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">La campagne ambitionne ainsi de repositionner l&rsquo;image de la PNH en mettant en avant les m&eacute;tiers scientifiques, techniques et strat&eacute;giques qu&rsquo;offre l&rsquo;institution. Juristes, ing&eacute;nieures, m&eacute;decins, psychologues, informaticiennes, techniciennes et autres professionnelles sont d&eacute;sormais appel&eacute;es &agrave; consid&eacute;rer la PNH comme un v&eacute;ritable espace de carri&egrave;re, d&rsquo;engagement citoyen et de leadership.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Dans son intervention, Madame Djenanne F&eacute;lix D&eacute;sir, repr&eacute;sentante du PNUD, a salu&eacute; cette d&eacute;marche en rappelant qu&rsquo;&laquo; une soci&eacute;t&eacute; ne peut se priver de la moiti&eacute; de ses comp&eacute;tences &raquo;. Elle a insist&eacute; sur l&rsquo;importance de cr&eacute;er un environnement institutionnel permettant aux femmes non seulement d&rsquo;int&eacute;grer la police, mais aussi d&rsquo;y &eacute;voluer dignement, d&rsquo;occuper des fonctions strat&eacute;giques et d&rsquo;&ecirc;tre promues &agrave; la hauteur de leurs comp&eacute;tences.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">De son c&ocirc;t&eacute;, le Charg&eacute; d&rsquo;affaires de l&rsquo;Union Europ&eacute;enne, Johan Eidman, a soulign&eacute; qu&rsquo;une plus grande participation des femmes dans les institutions de s&eacute;curit&eacute; constitue un facteur essentiel de confiance publique, de professionnalisme et d&rsquo;efficacit&eacute; institutionnelle.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">L&rsquo;Inspecteur g&eacute;n&eacute;ral Jean Gardy Muscadin, repr&eacute;sentant de la Direction G&eacute;n&eacute;rale de la PNH, a pour sa part r&eacute;affirm&eacute; la volont&eacute; de l&rsquo;institution polici&egrave;re de construire une police moderne, respectueuse des droits humains, attentive aux vuln&eacute;rabilit&eacute;s sociales et capable de restaurer durablement la confiance citoyenne.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Dans le cadre de cette campagne, plusieurs outils de communication innovants ont &eacute;t&eacute; pr&eacute;sent&eacute;s, notamment des affiches, brochures, contenus audiovisuels et supports num&eacute;riques r&eacute;alis&eacute;s avec l&rsquo;appui des nouvelles technologies et de l&rsquo;intelligence artificielle.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Apr&egrave;s cette phase de lancement, Konekte M annonce le d&eacute;ploiement des prochaines activit&eacute;s dans l&rsquo;Ouest, le Grand Nord puis le Grand Sud, &agrave; travers des interventions dans les &eacute;coles, universit&eacute;s, &eacute;glises et centres de formation, afin de rapprocher davantage les jeunes professionnels de la PNH et de promouvoir une nouvelle culture de service public.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">R&eacute;daction ✍️: Ronalson Blanfort </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">#konektem </span></p>\r\n<p class=\"p1\"><span class=\"s1\">#ToutKoteNenp&ograve;tKil&egrave;</span></p>', 0, 0, 0, NULL, 326, '𝗟𝗮 𝗣𝗼𝗹𝗶𝗰𝗲 𝗡𝗮𝘁𝗶𝗼𝗻𝗮𝗹𝗲 𝗱’𝗛𝗮𝗶̈𝘁𝗶 𝗹𝗮𝗻𝗰𝗲 𝗼𝗳𝗳𝗶𝗰𝗶𝗲𝗹𝗹𝗲𝗺𝗲𝗻𝘁 𝘂𝗻𝗲 𝗰𝗮𝗺𝗽𝗮𝗴𝗻𝗲 𝗻𝗮𝘁𝗶𝗼𝗻𝗮𝗹𝗲 𝗱𝗲 𝘀𝗲𝗻𝘀𝗶𝗯𝗶𝗹𝗶𝘀𝗮𝘁𝗶𝗼𝗻 𝗽𝗼𝘂𝗿 𝗹𝗲 𝗿𝗲𝗰𝗿𝘂𝘁𝗲𝗺𝗲𝗻𝘁 𝗾𝘂𝗮𝗹𝗶𝘁𝗮𝘁𝗶𝗳 𝗱𝗲𝘀 𝗳𝗲𝗺𝗺𝗲𝘀.', 'security', 'La Police Nationale d’Haïti (PNH), en partenariat avec le Programme des Nations Unies pour le Développement (PNUD), l’Union Européenne et la firme Konekte M, a procédé au lancement officiel d’une vaste campagne de sensibilisation visant à promouvoir le recrutement qualitatif des femmes au sein de la PNH ainsi qu’à renforcer l’image institutionnelle de l’institution policière.', '<p class=\"p1\"><span class=\"s1\">La Police Nationale d&rsquo;Ha&iuml;ti (PNH), en partenariat avec le Programme des Nations Unies pour le D&eacute;veloppement (PNUD), l&rsquo;Union Europ&eacute;enne et la firme Konekte M, a proc&eacute;d&eacute; au lancement officiel d&rsquo;une vaste campagne de sensibilisation visant &agrave; promouvoir le recrutement qualitatif des femmes au sein de la PNH ainsi qu&rsquo;&agrave; renforcer l&rsquo;image institutionnelle de l&rsquo;institution polici&egrave;re.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Organis&eacute;e dans la salle de conf&eacute;rence du C3I, &agrave; la Direction G&eacute;n&eacute;rale de la PNH, cette activit&eacute; a r&eacute;uni plusieurs hauts responsables policiers, des repr&eacute;sentants d&rsquo;organisations internationales ainsi que diff&eacute;rents acteurs engag&eacute;s dans les questions de gouvernance, de s&eacute;curit&eacute; publique et d&rsquo;inclusion.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&Agrave; travers cette initiative, Konekte M, firme charg&eacute;e de la conception et de la mise en &oelig;uvre de la campagne, entend contribuer &agrave; une nouvelle vision de la Police Nationale d&rsquo;Ha&iuml;ti, une institution moderne, inclusive, professionnelle et davantage ouverte aux comp&eacute;tences f&eacute;minines dans les domaines strat&eacute;giques et sp&eacute;cialis&eacute;s.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Lors de la pr&eacute;sentation officielle de la campagne, le porte-parole de Konekte M, Frigain Marechal, a rappel&eacute; que le projet vise particuli&egrave;rement &agrave; encourager les jeunes femmes professionnelles, universitaires et techniciennes &agrave; int&eacute;grer les diff&eacute;rentes structures sp&eacute;cialis&eacute;es de la PNH. Il a &eacute;galement mis en &eacute;vidence les nombreux d&eacute;fis auxquels l&rsquo;institution fait face aujourd&rsquo;hui, notamment le manque de personnel qualifi&eacute; ainsi que les perceptions n&eacute;gatives v&eacute;hicul&eacute;es autour de la police nationale.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">La campagne ambitionne ainsi de repositionner l&rsquo;image de la PNH en mettant en avant les m&eacute;tiers scientifiques, techniques et strat&eacute;giques qu&rsquo;offre l&rsquo;institution. Juristes, ing&eacute;nieures, m&eacute;decins, psychologues, informaticiennes, techniciennes et autres professionnelles sont d&eacute;sormais appel&eacute;es &agrave; consid&eacute;rer la PNH comme un v&eacute;ritable espace de carri&egrave;re, d&rsquo;engagement citoyen et de leadership.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Dans son intervention, Madame Djenanne F&eacute;lix D&eacute;sir, repr&eacute;sentante du PNUD, a salu&eacute; cette d&eacute;marche en rappelant qu&rsquo;&laquo; une soci&eacute;t&eacute; ne peut se priver de la moiti&eacute; de ses comp&eacute;tences &raquo;. Elle a insist&eacute; sur l&rsquo;importance de cr&eacute;er un environnement institutionnel permettant aux femmes non seulement d&rsquo;int&eacute;grer la police, mais aussi d&rsquo;y &eacute;voluer dignement, d&rsquo;occuper des fonctions strat&eacute;giques et d&rsquo;&ecirc;tre promues &agrave; la hauteur de leurs comp&eacute;tences.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">De son c&ocirc;t&eacute;, le Charg&eacute; d&rsquo;affaires de l&rsquo;Union Europ&eacute;enne, Johan Eidman, a soulign&eacute; qu&rsquo;une plus grande participation des femmes dans les institutions de s&eacute;curit&eacute; constitue un facteur essentiel de confiance publique, de professionnalisme et d&rsquo;efficacit&eacute; institutionnelle.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">L&rsquo;Inspecteur g&eacute;n&eacute;ral Jean Gardy Muscadin, repr&eacute;sentant de la Direction G&eacute;n&eacute;rale de la PNH, a pour sa part r&eacute;affirm&eacute; la volont&eacute; de l&rsquo;institution polici&egrave;re de construire une police moderne, respectueuse des droits humains, attentive aux vuln&eacute;rabilit&eacute;s sociales et capable de restaurer durablement la confiance citoyenne.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Dans le cadre de cette campagne, plusieurs outils de communication innovants ont &eacute;t&eacute; pr&eacute;sent&eacute;s, notamment des affiches, brochures, contenus audiovisuels et supports num&eacute;riques r&eacute;alis&eacute;s avec l&rsquo;appui des nouvelles technologies et de l&rsquo;intelligence artificielle.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Apr&egrave;s cette phase de lancement, Konekte M annonce le d&eacute;ploiement des prochaines activit&eacute;s dans l&rsquo;Ouest, le Grand Nord puis le Grand Sud, &agrave; travers des interventions dans les &eacute;coles, universit&eacute;s, &eacute;glises et centres de formation, afin de rapprocher davantage les jeunes professionnels de la PNH et de promouvoir une nouvelle culture de service public.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">R&eacute;daction ✍️: Ronalson Blanfort </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">#konektem </span></p>\r\n<p class=\"p1\"><span class=\"s1\">#ToutKoteNenp&ograve;tKil&egrave;</span></p>', '2026-05-22 07:00:00', '2026-06-08 11:25:24', NULL, NULL),
(64, 327, 'BBS-2026 : les noms sont enfin révélés.', '2026-05-26', 'education', 'Après plusieurs jours de suspense, d’attente et de nombreuses spéculations…', '<p>Apr&egrave;s plusieurs jours de suspense, d&rsquo;attente et de nombreuses sp&eacute;culations, l&rsquo;organisation de la conf&eacute;rence BBS-2026 a officiellement lev&eacute; le voile sur les deux intervenants qui prendront la parole lors de cette grande rencontre d&eacute;di&eacute;e &agrave; l&rsquo;entrepreneuriat et au leadership.</p>\r\n<p>🎙️ Cette ann&eacute;e, les projecteurs seront tourn&eacute;s vers :<br>▪️ Frinel Joseph<br>▪️ Johnson Napol&eacute;on</p>\r\n<p>Deux profils, Deux exp&eacute;riences, Une m&ecirc;me ambition : inspirer une g&eacute;n&eacute;ration d&eacute;termin&eacute;e &agrave; entreprendre, investir et avoir un impact durable dans la soci&eacute;t&eacute;.</p>\r\n<p>Selon les organisateurs, BBS-2026 promet une exp&eacute;rience immersive.</p>\r\n<p>L&rsquo;&eacute;v&eacute;nement entend cr&eacute;er un v&eacute;ritable d&eacute;clic chez les participants &agrave; travers des &eacute;changes, des t&eacute;moignages et des strat&eacute;gies concr&egrave;tes pour b&acirc;tir l&rsquo;avenir.</p>\r\n<p>📍Les inscriptions sont d&eacute;j&agrave; ouvertes :<br>👉🏽https://form.jotform.com/261105418362046</p>\r\n<p>#BBS2026&nbsp;<br>#Entrepreneuriat&nbsp;<br>#Leadership&nbsp;<br>#Investissement&nbsp;<br>#EgliseBaptisteBethel</p>\r\n<p>#konektem<br>#toutkotenenpotkil&egrave;</p>', 0, 1, 1, NULL, 327, 'BBS-2026 : les noms sont enfin révélés.', 'education', 'Après plusieurs jours de suspense, d’attente et de nombreuses spéculations…', '<p>Apr&egrave;s plusieurs jours de suspense, d&rsquo;attente et de nombreuses sp&eacute;culations, l&rsquo;organisation de la conf&eacute;rence BBS-2026 a officiellement lev&eacute; le voile sur les deux intervenants qui prendront la parole lors de cette grande rencontre d&eacute;di&eacute;e &agrave; l&rsquo;entrepreneuriat et au leadership.</p>\r\n<p>🎙️ Cette ann&eacute;e, les projecteurs seront tourn&eacute;s vers :<br>▪️ Frinel Joseph<br>▪️ Johnson Napol&eacute;on</p>\r\n<p>Deux profils, Deux exp&eacute;riences, Une m&ecirc;me ambition : inspirer une g&eacute;n&eacute;ration d&eacute;termin&eacute;e &agrave; entreprendre, investir et avoir un impact durable dans la soci&eacute;t&eacute;.</p>\r\n<p>Selon les organisateurs, BBS-2026 promet une exp&eacute;rience immersive.</p>\r\n<p>L&rsquo;&eacute;v&eacute;nement entend cr&eacute;er un v&eacute;ritable d&eacute;clic chez les participants &agrave; travers des &eacute;changes, des t&eacute;moignages et des strat&eacute;gies concr&egrave;tes pour b&acirc;tir l&rsquo;avenir.</p>\r\n<p>📍Les inscriptions sont d&eacute;j&agrave; ouvertes :<br>👉🏽https://form.jotform.com/261105418362046</p>\r\n<p>#BBS2026&nbsp;<br>#Entrepreneuriat&nbsp;<br>#Leadership&nbsp;<br>#Investissement&nbsp;<br>#EgliseBaptisteBethel</p>\r\n<p>#konektem<br>#toutkotenenpotkil&egrave;</p>', '2026-05-26 07:00:00', '2026-06-08 11:25:24', NULL, NULL);
INSERT INTO `news` (`id`, `newsImg`, `newsTitle`, `newsDate`, `newsCategory`, `newsHeadline`, `fullContent`, `reads`, `likes`, `shares`, `featured_image_ids`, `image_id`, `title`, `category`, `headline`, `content`, `published_at`, `created_at`, `updated_at`, `author_id`) VALUES
(65, 329, 'PALMARÈS MIZIK & VIDEYO EVANJELIK – Me 2026', '2026-06-01', 'music & video', 'Douz pwodiksyon ki make aktyalite gospel la pandan mwa a\r\n\r\nPandan mwa me 2026 la, plizyè atis gospel pwofite lage nouvo pwojè ki pote refleksyon sou lafwa, desten, gras Bondye, rekonesans ak reyalite sosyete a...', '<p class=\"p1\"><span class=\"s1\">Douz pwodiksyon ki make aktyalite gospel la pandan mwa a</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pandan mwa me 2026 la, plizy&egrave; atis gospel pwofite lage nouvo pwoj&egrave; ki pote refleksyon sou lafwa, desten, gras Bondye, rekonesans ak reyalite sosyete a. Nan yon kont&egrave;ks kote mizik evanjelik la kontinye pran plas li sou diferan platf&ograve;m dijital, nouvo videyo ak kolaborasyon yo montre yon jenerasyon atis ki ap ch&egrave;che kominike mesaj yo atrav&egrave; eksperyans p&egrave;son&egrave;l, temwayaj ak adorasyon.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Soti nan deklarasyon sou idantite espirity&egrave;l rive nan ap&egrave;l pou chanjman sosyal, pwodiksyon ki make mwa a prezante diferan vizyon sou relasyon moun ak Bondye. Men k&egrave;k nan mizik ki te atire atansyon piblik la pandan mwa me a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Mwen Se Yon Etwal&rdquo; : Apotre Robenson Joachim mete desten ak rezistans nan sant mesaj li</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 1e me 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Videyo ofisy&egrave;l &ldquo;Mwen Se Yon Etwal&rdquo; ki soti premye me 2026 la, prezante yon diskou ki chita sou idantite, ap&egrave;l espirity&egrave;l ak kapasite pou kenbe direksyon malgre opozisyon. Nan mizik la, Apotre Robenson Joachim itilize senb&ograve;l etwal la pou reprezante yon desten Bondye deja make sou lavi yon moun.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">T&egrave;ks la devlope lide ke gen batay ki akonpaye chak moun ki gen yon misyon pou akonpli. Referans ak tanp&egrave;t, tras sakrifis ak sezon difisil yo montre yon chemen ki pa konstwi sou fasilite, men sou andirans ak konviksyon.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pandan tout mizik la, atis la retounen sou kesyon tan Bondye ak pwom&egrave;s li yo. Li raple ke reta pa toujou vle di ech&egrave;k, e ke gen etap lavi ki mande pasyans anvan manifestasyon rezilta yo.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/ZG_jSHmyAuo?si=cqFMerbD66fOlINE</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Lanmou San Limit&rdquo; : Sr Magdala ak Fr Elisme chante sou yon Bondye ki pa janm abandone</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 10 me 2026 </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Av&egrave;k &ldquo;Lanmou San Limit&rdquo;, Sr Magdala ak Fr Elisme livre yon mizik adorasyon ki santre sou fidelite Bondye. Chante a prezante yon temwayaj kote rekonesans ak memwa sou sa Bondye f&egrave; pran premye plas.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan paw&ograve;l yo, Bondye par&egrave;t k&ograve;m sila ki leve moun apre sezon rej&egrave;, ki akonpaye moun ki santi yo poukont yo epi ki kontinye lonje men li menm l&egrave; moun pran distans ak li.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Mizik la mete aksan sou sakrifis Kris la k&ograve;m pi gwo pr&egrave;v lanmou Bondye genyen pou limanite. Se sou baz verite sa a chante a konstwi mesaj li sou restorasyon ak espwa.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/Z37catZB7FM?si=aGBnQM5IGe4eC3_5</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Bondye Deja Pase Av&egrave; m&rdquo; : Palmyre Seraphin raple ke Bondye prepare chemen an avan pitit li yo rive</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 11 me 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan videyo &ldquo;Bondye Deja Pase Av&egrave; m&rdquo;, Palmyre Seraphin devlope yon mesaj ki baze sou konfyans nan aksyon Bondye devan nenp&ograve;t sitiyasyon.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Refren an prezante yon Bondye ki pran chay yo, retire fado yo epi prepare chemen yo avan menm yo rive nan bary&egrave; yo. Mizik la konstwi sou deklarasyon viktwa ak delivrans, kote opozisyon ak konplo pa jwenn d&egrave;nye mo a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pwodiksyon an chwazi mete aksan sou rezilta ent&egrave;vansyon Bondye olye sou difikilte yo. Se sa ki f&egrave; mesaj la rete santre sou espwa ak avansman.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/F0U4cpRQ9io?si=YVJxn5gl367IPsEz</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Nou Ka Chanje Ayiti&rdquo; : Carl Emile ak J Perry lanse yon ap&egrave;l pou refleksyon kolektif</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 14 me 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pami mizik ki soti pandan mwa a, &ldquo;Nou Ka Chanje Ayiti&rdquo; okipe yon plas espesyal paske li ab&ograve;de kesyon sosyal ak nasyonal.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Carl Emile ak J Perry itilize mizik la pou raple eritaj istorik Ayiti pandan yo envite popilasyon an reflechi sou responsablite chak sitwayen nan avni peyi a. T&egrave;ks la f&egrave; referans ak batay zans&egrave;t yo, rich&egrave;s kiltir&egrave;l peyi a ak nesesite pou devlope yon l&ograve;t vizyon pou jenerasyon k ap vini yo.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/GLBDJAoQPK8?si=rqkykkabnfSPFm-Q</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Li Renmen M&rdquo; : Lynda Joseph mete konfyans li nan plan Bondye</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 15 me 2026 </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Av&egrave;k nouvo videyo li a, Lynda Joseph prezante yon mizik ki chita sou asirans yon moun ki konnen lavi li anba direksyon Bondye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Ekri pa Max Felor Jean, chante a raple ke okenn f&ograve;s pa kapab bloke sa Bondye deja deside akonpli. Paw&ograve;l yo mete aksan sou pwoteksyon Bondye, gidans li ak relasyon li ak pitit li yo.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Sou plan teknik, Browns Louis-Charles responsab anrejistreman, editaj ak mixaj la, tandiske Jimmy Jean Felix asire mastering la. Videyo a pote siyati realizat&egrave; Daoud Frejuste.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/dljecSylxeU?si=5JOVrVhWLpVYDbF1</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;M Lage&rsquo;m Nan Menw&rdquo; : Dassise Darilas chwazi chemen abandon total la</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 17 me 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan nouvo ent&egrave;pretasyon li f&egrave; sou mizik &ldquo;Mwen Vle Konnen Ou Plis&rdquo;, Dassise Darilas prezante yon chante ki santre sou desizyon pou rem&egrave;t lavi nou n&egrave;t nan men Bondye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Paw&ograve;l yo montre yon adorat&egrave; ki pa ch&egrave;che s&egrave;lman benediksyon, men ki vle viv yon relasyon ki pi sere ak Bondye. Chante a pran f&ograve;m yon priy&egrave; kote soum&egrave;t devan volonte Bondye vin tounen sant refleksyon an.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/ukwk7EBdTEs?si=UPGXplq2cts8WRmD</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Tapi Wouj Pou Jezi&rdquo; : yon mizik aksyon de gras ki mete Bondye an on&egrave;</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 18 me 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Av&egrave;k &ldquo;Tapi Wouj Pou Jezi&rdquo;, Marc Harry Joseph ansanm ak Pasteur Delly Benson prezante yon selebrasyon ki santre sou rekonesans pou Bondye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Chante a pase an revizyon plizy&egrave; reyalite lavi tankou gerizon, delivrans, restorasyon ak viktwa. Chak pati nan t&egrave;ks la s&egrave;vi k&ograve;m yon lis rem&egrave;siman pou aksyon Bondye f&egrave; nan lavi nou.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Sou plan pwodiksyon, Maestro Beethoven ak Roubens Dessilier siyen aranjman mizikal yo pandan videyo a reyalize pa Petit Sylvio ak Charles Kendy atrav&egrave; Multimedia ESR.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/4UF6rktGtzM?si=jtQnQxVnPzV_i4BG</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;HOSHIA&rdquo; : Alexander Polynice leve yon adorasyon ki santre sou souver&egrave;nte Kris la</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 19 me 2026 </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Soti 19 me 2026, Alexander Polynice prezante &ldquo;HOSHIA&rdquo;, yon mizik ki mete aksan sou otorite Jezi sou tout bagay.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Atrav&egrave; referans ak mo &ldquo;Hosanna&rdquo; ak &ldquo;Hoshia&rdquo;, chante a konstwi yon adorasyon ki raple Bondye k&ograve;m sila ki sove epi ki dirije lavi nou. T&egrave;ks la prezante Kris la k&ograve;m Wa ki gen d&egrave;nye mo sou nenp&ograve;t sitiyasyon.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/wWcltR7UcT8?si=bUhfbCLFewPycCgZ</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Gras Ki Leve&rsquo;m&rdquo; : Roobens Dor rakonte yon istwa restorasyon</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 24 me 2026 </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan videyo ki reyalize an, Roobens Dor prezante yon temwayaj ki mete aksan sou fav&egrave; Bondye k&ograve;m sous rel&egrave;v.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Mizik la trase pasaj yon moun soti nan sezon difisil pou rive nan yon etap kote li kapab temwaye sou aksyon Bondye nan lavi li. T&egrave;ks la mete anpil enp&ograve;tans sou kesyon restorasyon ak nouvo direksyon.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Ekriti Roobens Dor ansanm ak Eudes St Vil bay pwoj&egrave; a yon temwayaj ki rete prezan depi nan k&ograve;mansman rive nan fen mizik la.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/raB8xFLBJA0?si=TPyDQPibpMhCBrwE</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Jezi Renmen&rsquo;m&rdquo; : yon temwayaj sou fidelite Kris la</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 30 me 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Av&egrave;k &ldquo;Jezi Renmen&rsquo;m&rdquo;, Betenson Constant mete lanmou Kris la nan sant mesaj li.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Mizik la rakonte eksperyans yon moun ki w&egrave; lavi li pran yon l&ograve;t direksyon apre rankont li ak Jezi. Paw&ograve;l yo prezante Kris la k&ograve;m yon zanmi fid&egrave;l ki akonpaye moun nan tout sezon lavi yo.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Sou plan teknik, Betenson constan ekri t&egrave;ks lan, Edison Tilus responsab aranjman yo pandan Rich&eacute; Richenn asire mixaj ak mastering la, pandan videyo a reyalize pa Roby Pierre</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/EZWDCBtmZIM?si=CZ_SQs5klr8Fg2S_</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Gras Ki Mete&rsquo;m La&rdquo; : Spencer Brutus mete fav&egrave; Bondye nan sant temwayaj li</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 30 me 2026 </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan nouvo pwodiksyon sa a, Spencer Brutus chwazi pale sou kesyon gras Bondye k&ograve;m sous avansman.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">T&egrave;ks la mete fas a fas pase ak prezan pou montre kijan fav&egrave; Bondye kapab transf&ograve;me lavi yon moun. Mizik la ensiste sou lide ke s&egrave;ten p&ograve;t pa ouvri s&egrave;lman gras ak kapasite imen, men atrav&egrave; ent&egrave;vansyon Bondye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pwodiksyon an benefisye kolaborasyon Pascal Trazil ansanm ak plizy&egrave; mizisyen ki patisipe nan konstriksyon son pwoj&egrave; a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/yMyiPEW7xLo?si=4cLiqXgJ5pcTl-iF</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Enfants de Dieu&rdquo; : Louvena Metellus ak Fre Gabe chante sou inite</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 31 me 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pou f&egrave;men mwa a, Louvena Metellus ak Fre Gabe prezante &ldquo;Enfants de Dieu&rdquo;, yon mizik ki chita sou kesyon idantite espirity&egrave;l ak inite.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Chante a raple ke diferans sosyal, kiltir&egrave;l oswa lengwistik pa efase sa moun genyen an komen k&ograve;m pitit Bondye. Se yon mesaj ki envite moun sonje val&egrave; lanmou, ak resp&egrave;.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pwodiksyon Red Vision an ak videyo ofisy&egrave;l la mete aksan sou vizyon sa a atrav&egrave; yon prezantasyon ki anf&ograve;m ak mesaj mizik la.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/uyM5caNKrIw?si=gmtbJ6qAuIxB3d_j</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Mwa me 2026 la kite d&egrave;y&egrave; yon seri pwodiksyon ki montre plizy&egrave; fas&egrave;t mizik evanjelik la. Gen mizik ki pale sou desten ak perseverans, l&ograve;t ki mete aksan sou gras Bondye, adorasyon, restorasyon oswa kesyon sosyal. Ansanm, yo trase yon panorama ki montre kijan atis gospel yo kontinye s&egrave;vi ak mizik pou kominike eksperyans yo, temwayaj yo ak vizyon yo.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan yon pery&ograve;d kote kontni dijital ap pran plis plas chak jou, pwodiksyon sa yo kontinye alimante aktyalite gospel la pandan yo pote nouvo mesaj pou yon piblik k ap suiv evolisyon mizik krety&egrave;n nan an Ayiti ak nan dyaspora a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s2\">Redaksyon:</span></p>\r\n<p class=\"p1\"><span class=\"s2\">Vanauscheca Bouzy</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s2\">Konsepsyon Grafik:</span></p>\r\n<p class=\"p1\"><span class=\"s2\">Jo-Flung Bouzy &amp; Abdullah Mode</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">#palmar&egrave;smizikvideyo</span></p>\r\n<p class=\"p1\"><span class=\"s1\">#evanjelik</span></p>\r\n<p class=\"p1\"><span class=\"s1\">#me2026</span></p>\r\n<p class=\"p1\"><span class=\"s1\"><a href=\"https://www.konektem.net/blog/hashtags/konektem\">#konekte</a>m</span></p>\r\n<p class=\"p1\"><span class=\"s1\">#toutkotenenpotkil&egrave;</span></p>', 0, 0, 0, NULL, 329, 'PALMARÈS MIZIK & VIDEYO EVANJELIK – Me 2026', 'music & video', 'Douz pwodiksyon ki make aktyalite gospel la pandan mwa a\r\n\r\nPandan mwa me 2026 la, plizyè atis gospel pwofite lage nouvo pwojè ki pote refleksyon sou lafwa, desten, gras Bondye, rekonesans ak reyalite sosyete a...', '<p class=\"p1\"><span class=\"s1\">Douz pwodiksyon ki make aktyalite gospel la pandan mwa a</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pandan mwa me 2026 la, plizy&egrave; atis gospel pwofite lage nouvo pwoj&egrave; ki pote refleksyon sou lafwa, desten, gras Bondye, rekonesans ak reyalite sosyete a. Nan yon kont&egrave;ks kote mizik evanjelik la kontinye pran plas li sou diferan platf&ograve;m dijital, nouvo videyo ak kolaborasyon yo montre yon jenerasyon atis ki ap ch&egrave;che kominike mesaj yo atrav&egrave; eksperyans p&egrave;son&egrave;l, temwayaj ak adorasyon.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Soti nan deklarasyon sou idantite espirity&egrave;l rive nan ap&egrave;l pou chanjman sosyal, pwodiksyon ki make mwa a prezante diferan vizyon sou relasyon moun ak Bondye. Men k&egrave;k nan mizik ki te atire atansyon piblik la pandan mwa me a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Mwen Se Yon Etwal&rdquo; : Apotre Robenson Joachim mete desten ak rezistans nan sant mesaj li</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 1e me 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Videyo ofisy&egrave;l &ldquo;Mwen Se Yon Etwal&rdquo; ki soti premye me 2026 la, prezante yon diskou ki chita sou idantite, ap&egrave;l espirity&egrave;l ak kapasite pou kenbe direksyon malgre opozisyon. Nan mizik la, Apotre Robenson Joachim itilize senb&ograve;l etwal la pou reprezante yon desten Bondye deja make sou lavi yon moun.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">T&egrave;ks la devlope lide ke gen batay ki akonpaye chak moun ki gen yon misyon pou akonpli. Referans ak tanp&egrave;t, tras sakrifis ak sezon difisil yo montre yon chemen ki pa konstwi sou fasilite, men sou andirans ak konviksyon.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pandan tout mizik la, atis la retounen sou kesyon tan Bondye ak pwom&egrave;s li yo. Li raple ke reta pa toujou vle di ech&egrave;k, e ke gen etap lavi ki mande pasyans anvan manifestasyon rezilta yo.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/ZG_jSHmyAuo?si=cqFMerbD66fOlINE</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Lanmou San Limit&rdquo; : Sr Magdala ak Fr Elisme chante sou yon Bondye ki pa janm abandone</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 10 me 2026 </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Av&egrave;k &ldquo;Lanmou San Limit&rdquo;, Sr Magdala ak Fr Elisme livre yon mizik adorasyon ki santre sou fidelite Bondye. Chante a prezante yon temwayaj kote rekonesans ak memwa sou sa Bondye f&egrave; pran premye plas.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan paw&ograve;l yo, Bondye par&egrave;t k&ograve;m sila ki leve moun apre sezon rej&egrave;, ki akonpaye moun ki santi yo poukont yo epi ki kontinye lonje men li menm l&egrave; moun pran distans ak li.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Mizik la mete aksan sou sakrifis Kris la k&ograve;m pi gwo pr&egrave;v lanmou Bondye genyen pou limanite. Se sou baz verite sa a chante a konstwi mesaj li sou restorasyon ak espwa.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/Z37catZB7FM?si=aGBnQM5IGe4eC3_5</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Bondye Deja Pase Av&egrave; m&rdquo; : Palmyre Seraphin raple ke Bondye prepare chemen an avan pitit li yo rive</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 11 me 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan videyo &ldquo;Bondye Deja Pase Av&egrave; m&rdquo;, Palmyre Seraphin devlope yon mesaj ki baze sou konfyans nan aksyon Bondye devan nenp&ograve;t sitiyasyon.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Refren an prezante yon Bondye ki pran chay yo, retire fado yo epi prepare chemen yo avan menm yo rive nan bary&egrave; yo. Mizik la konstwi sou deklarasyon viktwa ak delivrans, kote opozisyon ak konplo pa jwenn d&egrave;nye mo a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pwodiksyon an chwazi mete aksan sou rezilta ent&egrave;vansyon Bondye olye sou difikilte yo. Se sa ki f&egrave; mesaj la rete santre sou espwa ak avansman.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/F0U4cpRQ9io?si=YVJxn5gl367IPsEz</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Nou Ka Chanje Ayiti&rdquo; : Carl Emile ak J Perry lanse yon ap&egrave;l pou refleksyon kolektif</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 14 me 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pami mizik ki soti pandan mwa a, &ldquo;Nou Ka Chanje Ayiti&rdquo; okipe yon plas espesyal paske li ab&ograve;de kesyon sosyal ak nasyonal.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Carl Emile ak J Perry itilize mizik la pou raple eritaj istorik Ayiti pandan yo envite popilasyon an reflechi sou responsablite chak sitwayen nan avni peyi a. T&egrave;ks la f&egrave; referans ak batay zans&egrave;t yo, rich&egrave;s kiltir&egrave;l peyi a ak nesesite pou devlope yon l&ograve;t vizyon pou jenerasyon k ap vini yo.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/GLBDJAoQPK8?si=rqkykkabnfSPFm-Q</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Li Renmen M&rdquo; : Lynda Joseph mete konfyans li nan plan Bondye</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 15 me 2026 </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Av&egrave;k nouvo videyo li a, Lynda Joseph prezante yon mizik ki chita sou asirans yon moun ki konnen lavi li anba direksyon Bondye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Ekri pa Max Felor Jean, chante a raple ke okenn f&ograve;s pa kapab bloke sa Bondye deja deside akonpli. Paw&ograve;l yo mete aksan sou pwoteksyon Bondye, gidans li ak relasyon li ak pitit li yo.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Sou plan teknik, Browns Louis-Charles responsab anrejistreman, editaj ak mixaj la, tandiske Jimmy Jean Felix asire mastering la. Videyo a pote siyati realizat&egrave; Daoud Frejuste.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/dljecSylxeU?si=5JOVrVhWLpVYDbF1</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;M Lage&rsquo;m Nan Menw&rdquo; : Dassise Darilas chwazi chemen abandon total la</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 17 me 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan nouvo ent&egrave;pretasyon li f&egrave; sou mizik &ldquo;Mwen Vle Konnen Ou Plis&rdquo;, Dassise Darilas prezante yon chante ki santre sou desizyon pou rem&egrave;t lavi nou n&egrave;t nan men Bondye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Paw&ograve;l yo montre yon adorat&egrave; ki pa ch&egrave;che s&egrave;lman benediksyon, men ki vle viv yon relasyon ki pi sere ak Bondye. Chante a pran f&ograve;m yon priy&egrave; kote soum&egrave;t devan volonte Bondye vin tounen sant refleksyon an.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/ukwk7EBdTEs?si=UPGXplq2cts8WRmD</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Tapi Wouj Pou Jezi&rdquo; : yon mizik aksyon de gras ki mete Bondye an on&egrave;</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 18 me 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Av&egrave;k &ldquo;Tapi Wouj Pou Jezi&rdquo;, Marc Harry Joseph ansanm ak Pasteur Delly Benson prezante yon selebrasyon ki santre sou rekonesans pou Bondye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Chante a pase an revizyon plizy&egrave; reyalite lavi tankou gerizon, delivrans, restorasyon ak viktwa. Chak pati nan t&egrave;ks la s&egrave;vi k&ograve;m yon lis rem&egrave;siman pou aksyon Bondye f&egrave; nan lavi nou.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Sou plan pwodiksyon, Maestro Beethoven ak Roubens Dessilier siyen aranjman mizikal yo pandan videyo a reyalize pa Petit Sylvio ak Charles Kendy atrav&egrave; Multimedia ESR.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/4UF6rktGtzM?si=jtQnQxVnPzV_i4BG</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;HOSHIA&rdquo; : Alexander Polynice leve yon adorasyon ki santre sou souver&egrave;nte Kris la</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 19 me 2026 </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Soti 19 me 2026, Alexander Polynice prezante &ldquo;HOSHIA&rdquo;, yon mizik ki mete aksan sou otorite Jezi sou tout bagay.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Atrav&egrave; referans ak mo &ldquo;Hosanna&rdquo; ak &ldquo;Hoshia&rdquo;, chante a konstwi yon adorasyon ki raple Bondye k&ograve;m sila ki sove epi ki dirije lavi nou. T&egrave;ks la prezante Kris la k&ograve;m Wa ki gen d&egrave;nye mo sou nenp&ograve;t sitiyasyon.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/wWcltR7UcT8?si=bUhfbCLFewPycCgZ</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Gras Ki Leve&rsquo;m&rdquo; : Roobens Dor rakonte yon istwa restorasyon</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 24 me 2026 </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan videyo ki reyalize an, Roobens Dor prezante yon temwayaj ki mete aksan sou fav&egrave; Bondye k&ograve;m sous rel&egrave;v.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Mizik la trase pasaj yon moun soti nan sezon difisil pou rive nan yon etap kote li kapab temwaye sou aksyon Bondye nan lavi li. T&egrave;ks la mete anpil enp&ograve;tans sou kesyon restorasyon ak nouvo direksyon.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Ekriti Roobens Dor ansanm ak Eudes St Vil bay pwoj&egrave; a yon temwayaj ki rete prezan depi nan k&ograve;mansman rive nan fen mizik la.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/raB8xFLBJA0?si=TPyDQPibpMhCBrwE</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Jezi Renmen&rsquo;m&rdquo; : yon temwayaj sou fidelite Kris la</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 30 me 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Av&egrave;k &ldquo;Jezi Renmen&rsquo;m&rdquo;, Betenson Constant mete lanmou Kris la nan sant mesaj li.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Mizik la rakonte eksperyans yon moun ki w&egrave; lavi li pran yon l&ograve;t direksyon apre rankont li ak Jezi. Paw&ograve;l yo prezante Kris la k&ograve;m yon zanmi fid&egrave;l ki akonpaye moun nan tout sezon lavi yo.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Sou plan teknik, Betenson constan ekri t&egrave;ks lan, Edison Tilus responsab aranjman yo pandan Rich&eacute; Richenn asire mixaj ak mastering la, pandan videyo a reyalize pa Roby Pierre</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/EZWDCBtmZIM?si=CZ_SQs5klr8Fg2S_</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Gras Ki Mete&rsquo;m La&rdquo; : Spencer Brutus mete fav&egrave; Bondye nan sant temwayaj li</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 30 me 2026 </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan nouvo pwodiksyon sa a, Spencer Brutus chwazi pale sou kesyon gras Bondye k&ograve;m sous avansman.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">T&egrave;ks la mete fas a fas pase ak prezan pou montre kijan fav&egrave; Bondye kapab transf&ograve;me lavi yon moun. Mizik la ensiste sou lide ke s&egrave;ten p&ograve;t pa ouvri s&egrave;lman gras ak kapasite imen, men atrav&egrave; ent&egrave;vansyon Bondye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pwodiksyon an benefisye kolaborasyon Pascal Trazil ansanm ak plizy&egrave; mizisyen ki patisipe nan konstriksyon son pwoj&egrave; a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/yMyiPEW7xLo?si=4cLiqXgJ5pcTl-iF</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&ldquo;Enfants de Dieu&rdquo; : Louvena Metellus ak Fre Gabe chante sou inite</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🗓️ 31 me 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pou f&egrave;men mwa a, Louvena Metellus ak Fre Gabe prezante &ldquo;Enfants de Dieu&rdquo;, yon mizik ki chita sou kesyon idantite espirity&egrave;l ak inite.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Chante a raple ke diferans sosyal, kiltir&egrave;l oswa lengwistik pa efase sa moun genyen an komen k&ograve;m pitit Bondye. Se yon mesaj ki envite moun sonje val&egrave; lanmou, ak resp&egrave;.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pwodiksyon Red Vision an ak videyo ofisy&egrave;l la mete aksan sou vizyon sa a atrav&egrave; yon prezantasyon ki anf&ograve;m ak mesaj mizik la.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 https://youtu.be/uyM5caNKrIw?si=gmtbJ6qAuIxB3d_j</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Mwa me 2026 la kite d&egrave;y&egrave; yon seri pwodiksyon ki montre plizy&egrave; fas&egrave;t mizik evanjelik la. Gen mizik ki pale sou desten ak perseverans, l&ograve;t ki mete aksan sou gras Bondye, adorasyon, restorasyon oswa kesyon sosyal. Ansanm, yo trase yon panorama ki montre kijan atis gospel yo kontinye s&egrave;vi ak mizik pou kominike eksperyans yo, temwayaj yo ak vizyon yo.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan yon pery&ograve;d kote kontni dijital ap pran plis plas chak jou, pwodiksyon sa yo kontinye alimante aktyalite gospel la pandan yo pote nouvo mesaj pou yon piblik k ap suiv evolisyon mizik krety&egrave;n nan an Ayiti ak nan dyaspora a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s2\">Redaksyon:</span></p>\r\n<p class=\"p1\"><span class=\"s2\">Vanauscheca Bouzy</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s2\">Konsepsyon Grafik:</span></p>\r\n<p class=\"p1\"><span class=\"s2\">Jo-Flung Bouzy &amp; Abdullah Mode</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">#palmar&egrave;smizikvideyo</span></p>\r\n<p class=\"p1\"><span class=\"s1\">#evanjelik</span></p>\r\n<p class=\"p1\"><span class=\"s1\">#me2026</span></p>\r\n<p class=\"p1\"><span class=\"s1\"><a href=\"https://www.konektem.net/blog/hashtags/konektem\">#konekte</a>m</span></p>\r\n<p class=\"p1\"><span class=\"s1\">#toutkotenenpotkil&egrave;</span></p>', '2026-06-01 07:00:00', '2026-06-08 11:25:24', NULL, NULL);
INSERT INTO `news` (`id`, `newsImg`, `newsTitle`, `newsDate`, `newsCategory`, `newsHeadline`, `fullContent`, `reads`, `likes`, `shares`, `featured_image_ids`, `image_id`, `title`, `category`, `headline`, `content`, `published_at`, `created_at`, `updated_at`, `author_id`) VALUES
(66, 330, '4e édition de \"Parlons Femmes\" du 30 mai 2026, les femmes au centre des débats sur l\'engagement et la participation citoyenne.', '2026-06-04', 'society', 'La quatrième édition de « Parlons femmes », tenue le 30 mai 2026, s’est déroulée autour du thème Femme pour un temps comme celui-ci (Esther 4:14), avec un accent mis sur la place des femmes dans la société et leur participation aux espaces de décision...', '<p class=\"p1\"><span class=\"s1\">La quatri&egrave;me &eacute;dition de &laquo; Parlons femmes &raquo;, tenue le 30 mai 2026, s&rsquo;est d&eacute;roul&eacute;e autour du th&egrave;me Femme pour un temps comme celui-ci (Esther 4:14), avec un accent mis sur la place des femmes dans la soci&eacute;t&eacute; et leur participation aux espaces de d&eacute;cision.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">L&rsquo;activit&eacute; s&rsquo;est tenue &agrave; l&rsquo;&Eacute;glise de la Bonne Nouvelle, 9, Linz Harry Village, Avenue Mais-G&acirc;t&eacute; 8, Delmas. Elle a &eacute;t&eacute; coordonn&eacute;e par Mlle Genevi&egrave;ve Georges et Marie-Danielle Jeanty et ouverte par une introduction, avant une pause.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&Agrave; la reprise, la ministre &agrave; la Condition f&eacute;minine et aux Droits des femmes, Mme Pedrica Saint Jean, a pris part aux &eacute;changes aux c&ocirc;t&eacute;s du Dr Nicole Muller C&eacute;sar, Blondine Ganem, Genevi&egrave;ve Georges et de Marie-Danielle Jeanty. Les interventions ont abord&eacute; les d&eacute;fis li&eacute;s &agrave; l&rsquo;engagement des femmes chr&eacute;tiennes dans la vie publique et politique, ainsi que les repr&eacute;sentations sociales qui continuent d&rsquo;influencer leur participation.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Mme Pedrica Saint Jean a encourag&eacute; les participantes &agrave; s&rsquo;impliquer davantage dans la vie citoyenne, estimant que la foi ne constitue pas un frein &agrave; l&rsquo;exercice de responsabilit&eacute;s publiques. Elle a rappel&eacute; que les femmes chr&eacute;tiennes ont leur place dans les instances de d&eacute;cision et a lanc&eacute; : &laquo; Osez agir, osez devenir la femme que vous r&ecirc;vez d&rsquo;&ecirc;tre &raquo;.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Les &eacute;changes avec le public ont permis de poursuivre la r&eacute;flexion &agrave; travers questions et t&eacute;moignages.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">La rencontre s&rsquo;est cl&ocirc;tur&eacute;e avec une prestation musicale de Mifa Band et un moment de partage entre participantes.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">R&eacute;daction ✍️: Vanauscheca Bouzy </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">#konektem </span></p>\r\n<p class=\"p1\"><span class=\"s1\">#ToutKoteNenp&ograve;tKil&egrave;</span></p>\r\n<p class=\"p2\">&nbsp;</p>', 0, 0, 0, NULL, 330, '4e édition de \"Parlons Femmes\" du 30 mai 2026, les femmes au centre des débats sur l\'engagement et la participation citoyenne.', 'society', 'La quatrième édition de « Parlons femmes », tenue le 30 mai 2026, s’est déroulée autour du thème Femme pour un temps comme celui-ci (Esther 4:14), avec un accent mis sur la place des femmes dans la société et leur participation aux espaces de décision...', '<p class=\"p1\"><span class=\"s1\">La quatri&egrave;me &eacute;dition de &laquo; Parlons femmes &raquo;, tenue le 30 mai 2026, s&rsquo;est d&eacute;roul&eacute;e autour du th&egrave;me Femme pour un temps comme celui-ci (Esther 4:14), avec un accent mis sur la place des femmes dans la soci&eacute;t&eacute; et leur participation aux espaces de d&eacute;cision.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">L&rsquo;activit&eacute; s&rsquo;est tenue &agrave; l&rsquo;&Eacute;glise de la Bonne Nouvelle, 9, Linz Harry Village, Avenue Mais-G&acirc;t&eacute; 8, Delmas. Elle a &eacute;t&eacute; coordonn&eacute;e par Mlle Genevi&egrave;ve Georges et Marie-Danielle Jeanty et ouverte par une introduction, avant une pause.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&Agrave; la reprise, la ministre &agrave; la Condition f&eacute;minine et aux Droits des femmes, Mme Pedrica Saint Jean, a pris part aux &eacute;changes aux c&ocirc;t&eacute;s du Dr Nicole Muller C&eacute;sar, Blondine Ganem, Genevi&egrave;ve Georges et de Marie-Danielle Jeanty. Les interventions ont abord&eacute; les d&eacute;fis li&eacute;s &agrave; l&rsquo;engagement des femmes chr&eacute;tiennes dans la vie publique et politique, ainsi que les repr&eacute;sentations sociales qui continuent d&rsquo;influencer leur participation.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Mme Pedrica Saint Jean a encourag&eacute; les participantes &agrave; s&rsquo;impliquer davantage dans la vie citoyenne, estimant que la foi ne constitue pas un frein &agrave; l&rsquo;exercice de responsabilit&eacute;s publiques. Elle a rappel&eacute; que les femmes chr&eacute;tiennes ont leur place dans les instances de d&eacute;cision et a lanc&eacute; : &laquo; Osez agir, osez devenir la femme que vous r&ecirc;vez d&rsquo;&ecirc;tre &raquo;.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Les &eacute;changes avec le public ont permis de poursuivre la r&eacute;flexion &agrave; travers questions et t&eacute;moignages.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">La rencontre s&rsquo;est cl&ocirc;tur&eacute;e avec une prestation musicale de Mifa Band et un moment de partage entre participantes.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">R&eacute;daction ✍️: Vanauscheca Bouzy </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">#konektem </span></p>\r\n<p class=\"p1\"><span class=\"s1\">#ToutKoteNenp&ograve;tKil&egrave;</span></p>\r\n<p class=\"p2\">&nbsp;</p>', '2026-06-04 07:00:00', '2026-06-08 11:25:24', NULL, NULL),
(73, 333, 'Le parti politique VAR inaugure son siège social à Delmas 73, le 22 Juillet 2026.', '2026-07-23', 'politics', 'Le parti politique Vision, Action et Réalisation (VAR) a franchi une nouvelle étape dans son développement institutionnel avec l’inauguration, de son siège social, situé à Delmas 73, ce mercredi 22 juillet 2026,  La cérémonie s’est déroulée en présence des membres fondateurs de la formation politique ainsi que de plusieurs milliers de sympathisants venus témoigner leur soutien à cette nouvelle structure qui ambitionne de participer à la transformation du pays.', '<p>Le parti politique Vision, Action et R&eacute;alisation (VAR) a franchi une nouvelle &eacute;tape dans son d&eacute;veloppement institutionnel avec l&rsquo;inauguration, de son si&egrave;ge social, situ&eacute; &agrave; Delmas 73, ce mercredi 22 juillet 2026, &nbsp;La c&eacute;r&eacute;monie s&rsquo;est d&eacute;roul&eacute;e en pr&eacute;sence des membres fondateurs de la formation politique ainsi que de plusieurs milliers de sympathisants venus t&eacute;moigner leur soutien &agrave; cette nouvelle structure qui ambitionne de participer &agrave; la transformation du pays.</p>\r\n<p>Dans un contexte marqu&eacute; par une crise profonde touchant les secteurs politique, &eacute;conomique et social, le VAR entend se positionner comme un acteur engag&eacute; dans la recherche de solutions durables pour Ha&iuml;ti. Le parti affirme vouloir &oelig;uvrer au renforcement des institutions, &agrave; la coh&eacute;sion nationale et &agrave; la relance du d&eacute;veloppement &agrave; travers une approche fond&eacute;e sur l&rsquo;action et la responsabilit&eacute;.</p>\r\n<p>&Agrave; l&rsquo;occasion de cette inauguration, les responsables du parti ont pr&eacute;sent&eacute; les grandes lignes de leur projet politique. Celui-ci repose notamment sur la souverainet&eacute; nationale, la protection de l&rsquo;int&eacute;grit&eacute; territoriale, la m&eacute;ritocratie et la justice sociale. Le VAR dit &eacute;galement vouloir d&eacute;fendre les int&eacute;r&ecirc;ts de la nation, renforcer le sentiment d&rsquo;appartenance patriotique et valoriser le travail productif. Sa doctrine, qualifi&eacute;e de &laquo; progressisme humaniste r&eacute;publicain &raquo;, place l&rsquo;&ecirc;tre humain au c&oelig;ur de l&rsquo;action politique.</p>\r\n<p>Prenant part &agrave; l&rsquo;&eacute;v&eacute;nement, Wilson Jeudy, pr&eacute;sident du Conseil strat&eacute;gique du VAR, a pr&eacute;sent&eacute; le parti comme une force politique moderne tourn&eacute;e vers l&rsquo;avenir d&rsquo;Ha&iuml;ti. Il a reconnu les nombreux d&eacute;fis auxquels la formation devra faire face, tout en soulignant l&rsquo;importance de privil&eacute;gier des actions concr&egrave;tes capables de produire des r&eacute;sultats durables pour la population.</p>\r\n<p>Dans son intervention, Wilson Jeudy a &eacute;galement appel&eacute; &agrave; un dialogue constructif entre les diff&eacute;rents acteurs politiques partageant les principes d&eacute;mocratiques, en vue de b&acirc;tir une alliance plus large pour r&eacute;pondre aux urgences nationales. Il a invit&eacute; la jeunesse et les citoyens &agrave; s&rsquo;impliquer davantage dans la vie politique afin de contribuer &agrave; la reconstruction du pays.</p>\r\n<p>Avec l&rsquo;ouverture de ce si&egrave;ge, le VAR souhaite disposer d&rsquo;un espace permanent d&eacute;di&eacute; &agrave; la r&eacute;flexion strat&eacute;gique, &agrave; la formation politique, au dialogue citoyen et &agrave; la mobilisation autour des enjeux de d&eacute;veloppement national. Cette initiative marque, selon les dirigeants du parti, une volont&eacute; d&rsquo;&eacute;tendre leur pr&eacute;sence sur le territoire et de renforcer leur engagement dans la vie publique ha&iuml;tienne.</p>\r\n<p>&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Redaction:</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Ronalson Bryan Blanfort </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s2\">#konektem</span></p>\r\n<p class=\"p1\"><span class=\"s2\">#toutkotenenpotkil&egrave; </span></p>', 0, 0, 0, NULL, 333, 'Le parti politique VAR inaugure son siège social à Delmas 73, le 22 Juillet 2026.', 'new', 'Le parti politique Vision, Action et Réalisation (VAR) a franchi une nouvelle étape dans son développement institutionnel avec l’inauguration, de son siège social, situé à Delmas 73, ce mercredi 22 juillet 2026,  La cérémonie s’est déroulée en présence des membres fondateurs de la formation politique ainsi que de plusieurs milliers de sympathisants venus témoigner leur soutien à cette nouvelle structure qui ambitionne de participer à la transformation du pays.', '<p>Le parti politique Vision, Action et R&eacute;alisation (VAR) a franchi une nouvelle &eacute;tape dans son d&eacute;veloppement institutionnel avec l&rsquo;inauguration, de son si&egrave;ge social, situ&eacute; &agrave; Delmas 73, ce mercredi 22 juillet 2026, &nbsp;La c&eacute;r&eacute;monie s&rsquo;est d&eacute;roul&eacute;e en pr&eacute;sence des membres fondateurs de la formation politique ainsi que de plusieurs milliers de sympathisants venus t&eacute;moigner leur soutien &agrave; cette nouvelle structure qui ambitionne de participer &agrave; la transformation du pays.</p>\r\n<p>Dans un contexte marqu&eacute; par une crise profonde touchant les secteurs politique, &eacute;conomique et social, le VAR entend se positionner comme un acteur engag&eacute; dans la recherche de solutions durables pour Ha&iuml;ti. Le parti affirme vouloir &oelig;uvrer au renforcement des institutions, &agrave; la coh&eacute;sion nationale et &agrave; la relance du d&eacute;veloppement &agrave; travers une approche fond&eacute;e sur l&rsquo;action et la responsabilit&eacute;.</p>\r\n<p>&Agrave; l&rsquo;occasion de cette inauguration, les responsables du parti ont pr&eacute;sent&eacute; les grandes lignes de leur projet politique. Celui-ci repose notamment sur la souverainet&eacute; nationale, la protection de l&rsquo;int&eacute;grit&eacute; territoriale, la m&eacute;ritocratie et la justice sociale. Le VAR dit &eacute;galement vouloir d&eacute;fendre les int&eacute;r&ecirc;ts de la nation, renforcer le sentiment d&rsquo;appartenance patriotique et valoriser le travail productif. Sa doctrine, qualifi&eacute;e de &laquo; progressisme humaniste r&eacute;publicain &raquo;, place l&rsquo;&ecirc;tre humain au c&oelig;ur de l&rsquo;action politique.</p>\r\n<p>Prenant part &agrave; l&rsquo;&eacute;v&eacute;nement, Wilson Jeudy, pr&eacute;sident du Conseil strat&eacute;gique du VAR, a pr&eacute;sent&eacute; le parti comme une force politique moderne tourn&eacute;e vers l&rsquo;avenir d&rsquo;Ha&iuml;ti. Il a reconnu les nombreux d&eacute;fis auxquels la formation devra faire face, tout en soulignant l&rsquo;importance de privil&eacute;gier des actions concr&egrave;tes capables de produire des r&eacute;sultats durables pour la population.</p>\r\n<p>Dans son intervention, Wilson Jeudy a &eacute;galement appel&eacute; &agrave; un dialogue constructif entre les diff&eacute;rents acteurs politiques partageant les principes d&eacute;mocratiques, en vue de b&acirc;tir une alliance plus large pour r&eacute;pondre aux urgences nationales. Il a invit&eacute; la jeunesse et les citoyens &agrave; s&rsquo;impliquer davantage dans la vie politique afin de contribuer &agrave; la reconstruction du pays.</p>\r\n<p>Avec l&rsquo;ouverture de ce si&egrave;ge, le VAR souhaite disposer d&rsquo;un espace permanent d&eacute;di&eacute; &agrave; la r&eacute;flexion strat&eacute;gique, &agrave; la formation politique, au dialogue citoyen et &agrave; la mobilisation autour des enjeux de d&eacute;veloppement national. Cette initiative marque, selon les dirigeants du parti, une volont&eacute; d&rsquo;&eacute;tendre leur pr&eacute;sence sur le territoire et de renforcer leur engagement dans la vie publique ha&iuml;tienne.</p>\r\n<p>&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Redaction:</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Ronalson Bryan Blanfort </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s2\">#konektem</span></p>\r\n<p class=\"p1\"><span class=\"s2\">#toutkotenenpotkil&egrave; </span></p>', '2026-08-10 00:27:47', '2026-07-23 14:55:05', '2026-08-10 00:27:47', NULL);
INSERT INTO `news` (`id`, `newsImg`, `newsTitle`, `newsDate`, `newsCategory`, `newsHeadline`, `fullContent`, `reads`, `likes`, `shares`, `featured_image_ids`, `image_id`, `title`, `category`, `headline`, `content`, `published_at`, `created_at`, `updated_at`, `author_id`) VALUES
(78, NULL, NULL, NULL, NULL, '', NULL, 0, 0, 2, NULL, 357, 'PALMARÈS MIZIK & VIDEYO EVANJELIK – Jiyè 2026', 'new', 'Palmarès Mizik/Videyo Evanjelik – Jiyè 2026 : nouvo vwa, temwayaj ak mesaj lafwa sou sèn kretyen an…', '<p>Mwa jiy&egrave; 2026 la pote yon nouvo seri pwodiksyon ki montre vitalite mizik evanjelik ayisyen an. Pandan atis ak minist&egrave; yo kontinye eksplore diferan fason pou pataje mesaj espirity&egrave;l yo, adorasyon, rekonesans, konsakrasyon ak espwa rete pami gwo t&egrave;m ki make piblikasyon yo. Pou edisyon sa a, Palmar&egrave;s Mizik/Videyo Evanjelik mete an limy&egrave; plizy&egrave; mizik ak videyo ki soti pandan mwa a, soti nan adaptasyon mizik ent&egrave;nasyonal rive nan nouvo kreyasyon lokal. Chak pwodiksyon pote yon apw&ograve;ch diferan, men yo tout rankontre sou yon menm liy: s&egrave;vi ak mizik k&ograve;m yon zouti pou pataje lafwa ak eksperyans espirity&egrave;l. &ldquo;Plis Ke Kapab&rdquo; : Audner Martin ak Dahne Michel adapte yon mesaj lafwa pou piblik kreyolof&ograve;n nan 📅 1 jiy&egrave; 2026 Se ak &ldquo;Plis Ke Kapab&rdquo; Audner Martin ak Dahne Michel louvri seleksyon jiy&egrave; a.</p>\r\n<p>&nbsp;</p>\r\n<p>De atis yo pwopoze yon adaptasyon an krey&ograve;l mizik &ldquo;More Than Able&rdquo; pa Elevation Worship, yon travay ki chwazi mete yon mesaj adorasyon ent&egrave;nasyonal nan lang piblik ayisyen an. Adaptasyon an kons&egrave;ve sans prensipal chante a: konfyans nan kapasite Bondye pou reyalize sa l&egrave;z&ograve;m konsidere k&ograve;m enposib. Atrav&egrave; v&egrave;syon sa a, atis yo rann mesaj la pi aksesib pou kominote kreyolof&ograve;n nan pandan yo ajoute yon l&ograve;t pwodiksyon nan rep&egrave;twa adorasyon an krey&ograve;l. Pwoj&egrave; sa a antre nan yon mouvman k ap pran plis plas kote plizy&egrave; atis ayisyen ap ch&egrave;che adapte k&egrave;k gwo chante kretyen ent&egrave;nasyonal pou reponn ak reyalite ak langaj lokal la. 🔗 https://youtu.be/YZ_ulOod-oM?si=zdpYIJGwMi5riLB- &ldquo;&Egrave;ske Se Mwen Ki La&rdquo; : Past&egrave; Jean Claude Derisier mete aksan sou tras gras Bondye 📅 4 jiy&egrave; 2026 Nan &ldquo;&Egrave;ske Se Mwen Ki La&rdquo;, Past&egrave; Jean Claude Derisier pote yon mizik ki chita sou rekonesans ak temwayaj. Chante a retounen sou chemen yon moun, sou moman difisil li trav&egrave;se ak fason Bondye akonpaye l rive nan yon l&ograve;t etap. Travay sa a mete fidelite Bondye k&ograve;m pwen santral li. Li envite moun reflechi sou distans ki genyen ant pase yo ak chanjman Bondye kapab pote nan lavi yo.</p>\r\n<p>&nbsp;</p>\r\n<p>Sou plan pwodiksyon, Jean Claude Derisier siyen konpozisyon ak aranjman an. Li jwenn sip&ograve; Genoldens Desulma, Wood Berton Toussaint, Ernst Junior Marcelin ak Zoom Band ki kontribye nan estrikti mizikal la. 🔗 https://youtu.be/aV6AHnnXW9o?si=MippH5yfbQDKAeOP &ldquo;Ou se Bondye Vivan&rdquo; : Maiguy mete konfyans nan Bondye k&ograve;m poto mitan mesaj li 📅 10 jiy&egrave; 2026 Av&egrave;k &ldquo;Ou se Bondye Vivan&rdquo;, Maiguy prezante yon mizik adorasyon ki chita sou yon deklarasyon lafwa: Bondye rete prezan malgre chanjman ak difikilte lavi pote. Chante a pote yon mesaj ankourajman pou moun k ap ch&egrave;che kenbe espwa yo, pandan li mete aksan sou fidelite Bondye ak enp&ograve;tans pou rete f&egrave;m nan konfyans. Nan asp&egrave; teknik la, pwodiksyon an pote siyati Junior Paul, ak mixaj Chardley Glosy. Videyo ofisy&egrave;l la reyalize pa Gasen Pierre, ki mete yon vizy&egrave;l sou mesaj espirity&egrave;l chante a. 🔗 https://youtu.be/sl6HsJ5iNSU?si=ValATUYjwxOsf3j2 &ldquo;Seny&egrave; Tout Vim Se Pou Ou&rdquo; : St&eacute;phie Pierre prezante yon chante sou konsakrasyon ak abandon 📅 13 jiy&egrave; 2026 Av&egrave;k &ldquo;Seny&egrave; Tout Vim Se Pou Ou&rdquo;, St&eacute;phie Pierre mete yon mesaj sou konsakrasyon devan Bondye nan sant nouvo pwodiksyon vizy&egrave;l li. Chante sa a, ki f&egrave; pati alb&ograve;m &ldquo;Mwen Konfyan&rdquo;, jwenn yon nouvo souf atrav&egrave; videyo ofisy&egrave;l li pibliye an jiy&egrave; a. Nan mesaj li a, atis la prezante vwa yon moun ki rekon&egrave;t limit li epi ki chwazi rem&egrave;t direksyon lavi li bay Bondye. Travay la pote siyati plizy&egrave; kolaborat&egrave; nan dom&egrave;n mizikal ak vizy&egrave;l.</p>\r\n<p>&nbsp;</p>\r\n<p>Delly Benson siyen t&egrave;ks ak melodi a, Genoldens Desulma asire sekans lan, David Morinvil pran chaj mixaj ak mastering, pandan Carl Jules reyalize visualizer la. Av&egrave;k pwodiksyon sa a, St&eacute;phie Pierre ajoute yon l&ograve;t py&egrave;s nan rep&egrave;twa adorasyon li, pandan li kontinye eksplore t&egrave;m sou lafwa ak angajman espirity&egrave;l. 🔗 https://youtu.be/O0qdyoVXBak?si=g61E-nMzXmwdyf6w &ldquo;Ou Son Papa Tout Bon Vre&rdquo; : Tahisha Solages f&egrave; premye antre li nan mizik ofisy&egrave;l la 📅 17 jiy&egrave; 2026 Pou premye pwodiksyon ofisy&egrave;l li, Tahisha Solages chwazi antre nan espas mizik evanjelik la ak &ldquo;Ou Son Papa Tout Bon Vre&rdquo;, yon chante ki mete aksan sou lanmou ak fidelite Bondye. Nan premye travay sa a, atis la prezante Bondye k&ograve;m yon Papa ki rete prezan b&ograve; kote pitit Li yo. Mesaj la chita sou rekonesans, konfyans ak espwa, pandan li raple sip&ograve; espirity&egrave;l anpil moun jwenn nan lafwa yo. Premye s&ograve;ti sa a make yon etap enp&ograve;tan nan pakou Tahisha Solages, ki k&ograve;manse pataje idantite mizikal li atrav&egrave; yon pwodiksyon ki baze sou adorasyon ak temwayaj. 🔗 https://youtu.be/T5McBxk6XEo?si=G7yt-TzObLN-GM2V &ldquo;Yaweh M&egrave;si&rdquo; : James Jean Baptiste pote yon mesaj rekonesans ak temwayaj 📅 24 jiy&egrave; 2026 Av&egrave;k &ldquo;Yaweh M&egrave;si&rdquo;, James Jean Baptiste prezante yon mizik adorasyon ki chita sou rekonesans ak temwayaj sou fidelite Bondye.&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Chante a retounen sou chemen yon moun ki pran tan pou sonje gras li resevwa ak fason Bondye akonpaye l atrav&egrave; diferan etap lavi. Paw&ograve;l mizik la mete aksan sou padon, delivrans ak nouvo chans Bondye bay. Li pote yon mesaj imilite kote tout glwa retounen bay Bondye pou sa Li f&egrave; ak sa Li kontinye ap f&egrave;. Av&egrave;k pwodiksyon sa a, James Jean Baptiste ajoute yon nouvo vwa nan aktyalite mizik evanjelik la, kote temwayaj ak rekonesans rete pami gwo sous enspirasyon yo. 🔗 https://youtu.be/fNT7GteyKvQ?si=V62u3z_XXFwrsV0b &ldquo;Kounyea&rdquo; : Aquela Dorvil prezante yon ap&egrave;l pou renouv&egrave;lman espirity&egrave;l 📅 25 jiy&egrave; 2026 Nan &ldquo;Kounyea&rdquo;, Aquela Dorvil eksprime dezi yon moun k ap ch&egrave;che yon eksperyans pi pwofon ak Bondye atrav&egrave; lapriy&egrave; ak abandon. Mizik la ab&ograve;de t&egrave;m tankou transf&ograve;masyon, gerizon ak bezwen yon ent&egrave;vansyon divin nan lavi moun. Paw&ograve;l yo tradui yon k&egrave; ki rekon&egrave;t limit li epi ki rete ouv&egrave; ak chanjman Bondye kapab pote. Videyo ofisy&egrave;l la reyalize pa Roby Pierre, ki mete an imaj mesaj espirity&egrave;l chante a. 🔗 https://youtu.be/FqaFgxO2ouo?si=GTIZWHbQj-poSluD &ldquo;Map Louwe w&rdquo; : Rechanka Doristil ak Stanley Georges mete ansanm yon mesaj adorasyon 📅 25 jiy&egrave; 2026 &ldquo;Map Louwe w&rdquo;, yon kolaborasyon ant Rechanka Doristil ak Stanley Georges, pote yon mesaj ki chita sou lwanj ak rekonesans pou Bondye. Ekri pa Stanley Georges, mizik la prezante adorasyon k&ograve;m yon repons devan fidelite Bondye. De vwa yo reyini pou pataje yon mesaj sou enp&ograve;tans pou rete nan rekonesans malgre sikonstans lavi yo.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;Pwodiksyon sa a antre nan seri kolaborasyon k ap kontinye grandi nan mizik evanjelik ayisyen an. 🔗 https://youtu.be/geVsvo8zexk?si=zy8ekqNdI1tEI7ny &ldquo;Map Temwanye&rdquo; : Delly Benson rakonte fidelite Bondye atrav&egrave; yon mesaj rekonesans 📅 31 jiy&egrave; 2026 Av&egrave;k &ldquo;Map Temwanye&rdquo;, Delly Benson prezante yon mizik adorasyon ki chita sou temwayaj ak rekonesans. Tit la pote prensipal lide chante a: pataje sa Bondye f&egrave; nan lavi yon moun ak fason Li akonpaye li nan chak etap. Atrav&egrave; paw&ograve;l li yo, mizik la mete aksan sou delivrans, pwoteksyon ak lanmou Bondye ki soutni. Ekspresyon &ldquo;Map temwanye&rdquo; tounen yon deklarasyon lafwa ki ankouraje moun rekon&egrave;t gras Bondye devan l&ograve;t moun. Av&egrave;k d&egrave;nye pwodiksyon sa a, Delly Benson pote yon mesaj ki f&egrave;men seleksyon jiy&egrave; a sou yon n&ograve;t rekonesans ak adorasyon. 🔗 https://youtu.be/BQcvGNBXEYk?si=gqTLg7DbWJy4jcsV Edisyon Jiy&egrave; 2026 Palmar&egrave;s Mizik/Videyo Evanjelik la montre div&egrave;site mesaj ki kontinye anime mizik evanjelik ayisyen an. Soti nan adaptasyon mizik ent&egrave;nasyonal rive nan nouvo konpozisyon, seleksyon an mete an limy&egrave; plizy&egrave; fason pou eksprime lafwa, espwa ak rekonesans.</p>\r\n<p>&nbsp;</p>\r\n<p>Atrav&egrave; pwodiksyon sa yo, Palmar&egrave;s la kontinye suiv evolisyon yon sekt&egrave; ki ap grandi, pandan li bay plis vizibilite ak travay ki kontribye nan rich&egrave;s mizik evanjelik ayisyen an. Redaksyon: Vanauscheca Bouzy Konsepsyon Grafik: Jo-Flung Bouzy &amp; Abdullah Mode #palmar&egrave;smizikvideyo #evanjelik #jen2026 #konektem #toutkotenenpotkil&egrave;</p>', '2026-09-03 18:14:09', '2026-08-03 18:25:32', '2026-09-03 18:14:09', 1),
(79, NULL, NULL, NULL, NULL, '', NULL, 0, 0, 0, NULL, 375, 'Life should be exiting', 'Politics', 'Our testing', '<p>In a life full of adventures. It is important to know how to manage one\'s time and explore all the good things that will be on the way. Life can be exiting, at the same , it can be full of surprise.&nbsp;</p>', '2026-08-11 12:50:57', '2026-08-11 12:48:46', '2026-08-11 12:50:57', 1),
(81, NULL, NULL, NULL, NULL, '', NULL, 0, 0, 0, NULL, 384, 'RENAEH  soumèt ofisyèlman bay Ministè Jenès, Espò ak Aksyon Sivik (MJSAC) rapò konsiltasyon li sou aktyalizasyon Politik Nasyonal Jenès.', 'Politik', 'ESANSYEL', '<p>➡️ Regroupement National des &Eacute;tudiants Ha&iuml;tiens (RENAEH) se yon &ograve;ganizasyon ki travay pou amelyore kondisyon edikasyon an Ayiti, nan objektif pou bati yon kominote etidyan ki konpetan, angaje epi kapab patisipe aktivman nan devlopman peyi a. Pandan plizy&egrave; ane, &ograve;ganizasyon an reyalize plizy&egrave; aktivite tankou &ograve;ganizasyon konferans ak f&ograve;masyon, konkou ent&egrave;nasyonal pou ankouraje lekti, kanpay donasyon san, pwomosyon dwa moun, elatriye. Pou pi byen reponn ak misyon li, RENAEH &ograve;ganize travay li atrav&egrave; s&egrave;t (7) selil tematik: Dwa Moun, Syans ak Teknoloji, Sante ak Byenn&egrave;t, Ekonomi ak Finans, Edikasyon, Esp&ograve; ak Atizay, Politik, Kilti ak Sosyete, epi Anviw&ograve;nman ak Agrikilti.</p>\r\n<p>Nan kad Jounen Ent&egrave;nasyonal Jen&egrave;s la, RENAEH te soum&egrave;t ofisy&egrave;lman bay Minist&egrave; Jen&egrave;s, Esp&ograve; ak Aksyon Sivik (MJSAC) rap&ograve; konsiltasyon li sou aktyalizasyon Politik Nasyonal Jen&egrave;s (PNJ) la.</p>\r\n<p>Rap&ograve; sila se rezilta yon pwosesis konsiltasyon ki te reyini etidyan, j&egrave;n gradye ak j&egrave;n pwofesyon&egrave;l ki soti nan dis (10) depatman peyi a, av&egrave;k sip&ograve; teknik Observatoire Citoyen de l\'Action des Pouvoirs Publics en Ha&iuml;ti (OCAPH).&nbsp;</p>\r\n<p>Apre analiz sa yo, RENAEH pwopoze n&egrave;f (9) rek&ograve;mandasyon pou ranf&ograve;se politik piblik sou lajen&egrave;s. Pami yo genyen : Mete sou pye yon plan nasyonal pou aplikasyon politik la, yon mekanis k&ograve;dinasyon ant minist&egrave; yo, yon rejis nasyonal &ograve;ganizasyon j&egrave;n yo, yon Kons&egrave;y Nasyonal Jen&egrave;s ki reprezantatif, desantralizasyon politik yo, yon sist&egrave;m estaj ak premye dj&ograve;b pou j&egrave;n yo, yon plan nasyonal lajen&egrave;s, Lap&egrave; ak Sekirite, yon fon nasyonal pou lajen&egrave;s ak plizy&egrave; l&ograve;t ank&ograve;.</p>\r\n<p>Dapre RENAEH, tout pwopozisyon sa yo chita sou konviksyon ki f&egrave; kw&egrave; &nbsp;j&egrave;n yo dwe konsidere k&ograve;m patn&egrave; rey&egrave;l nan devlopman peyi a, olye yo w&egrave; yo s&egrave;lman k&ograve;m benefisy&egrave; politik piblik yo.</p>\r\n<p>Boutofen, RENAEH reyafime angajman li pou kontinye pote vwa jen&egrave;s ayisy&egrave;n nan epi defann enter&egrave; li nan tout espas desizyon&egrave;l yo.</p>\r\n<p>#esansy&egrave;l<br>#aktyalite&nbsp;<br>#konektem<br>#toutkotenenpotkil&egrave;</p>', '2026-08-18 18:56:33', '2026-08-18 18:56:33', NULL, 1);
INSERT INTO `news` (`id`, `newsImg`, `newsTitle`, `newsDate`, `newsCategory`, `newsHeadline`, `fullContent`, `reads`, `likes`, `shares`, `featured_image_ids`, `image_id`, `title`, `category`, `headline`, `content`, `published_at`, `created_at`, `updated_at`, `author_id`) VALUES
(82, NULL, NULL, NULL, NULL, '', NULL, 0, 0, 0, NULL, 390, 'Palmarès Mizik/Videyo Evanjelik — Dawout 2026', 'new', 'Mwa dawout 2026 la pote yon seri nouvo pwodiksyon nan mizik evanjelik ayisyen an. Adorasyon, temwayaj, lapriyè, rekonesans ak konfyans nan Bondye se pami tèm ki travèse diferan sòti yo. Chak atis chwazi pwòp fason pa li pou rakonte yon eksperyans, eksprime yon konviksyon oswa pote yon mesaj bay piblik la. Men kèk nan pwodiksyon ki make aktyalite mizik evanjelik la pandan mwa a.', '<p class=\"p1\"><strong>Se Pou Ou &raquo; &mdash; Tom Karencini Jecrois</strong></p>\r\n<p class=\"p1\"><span class=\"s1\">Premye Dawout 2026</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Tom Karencini Jecrois ouvri mwa a ak &laquo; Se Pou Ou &raquo;, yon pwodiksyon ki melanje sonorite zouk ak konpa ak yon mesaj rekonesans. Nan mizik la, Tom Karencini f&egrave; yon evalyasyon sou chemen li epi li atribye sa li rive akonpli yo ak gras Bondye.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Paw&ograve;l yo mennen progresivman nan yon deklarasyon konsekrasyon, kote lavi, k&egrave; ak tout sa li posede retounen bay Bondye. Mizik la siyen pa Tom Karencini Jecrois ansanm ak Deborah Henristal ak Patrice J. Denize. Asan ki asire enstrimental la, Milot Joseph responsab miksaj ak mastering, pandan Fr Gabe, Pierre Alan Gabriel, asire pwodiksyon videyo a.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 Gade Se Pou Ou:<span class=\"Apple-converted-space\">&nbsp; </span><a href=\"https://youtu.be/W98LB9wcEBs?si=pKAKyYS85clEb5zl\">https://youtu.be/W98LB9wcEBs?si=pKAKyYS85clEb5zl</a></span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">Si Se Pat Ou Bondye &raquo; &mdash; Celigny Dathus</span></strong></p>\r\n<p class=\"p1\"><span class=\"s1\">2 dawout 2026</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Kisa ki t ap rive si Bondye pa t ent&egrave;vni? Se kesyon sa a ki s&egrave;vi k&ograve;m pwen depa pou &laquo; Si Se Pat Ou Bondye &raquo;, yon mizik kote Celigny Dathus mete rekonesans nan sant refleksyon li.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Atis la rekon&egrave;t difikilte pou jwenn ase mo pou esplike kantite byenf&egrave; li resevwa. Mizik la pran f&ograve;m yon temwayaj p&egrave;son&egrave;l sou yon lavi ki konsidere prezans Bondye k&ograve;m yon eleman esansy&egrave;l nan chemen li.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Celigny Dathus se chant&egrave; ak konpozit&egrave; pwodiksyon an. Li responsab tou miksaj ak mastering, pandan Thermot Dieuverson f&egrave; beat la. Group Rescue pote backup vokal yo epi DAT Studios siyen pwodiksyon videyo a.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">🔗 Gade Si Se Pat Ou Bondye: <a href=\"https://youtu.be/_v0pfjfX9YM?si=Sqx_P-itj0_Uk7B2\">https://youtu.be/_v0pfjfX9YM?si=Sqx_P-itj0_Uk7B2</a></span></p>\r\n<p class=\"p1\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">Yon Priy&egrave; &mdash; Kerlyne Liberus</span></strong></p>\r\n<p class=\"p1\"><span class=\"s1\">7 dawout 2026</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Av&egrave;k Yon Priy&egrave;, Kerlyne Liberus antre nan yon l&ograve;t dimansyon: sa yon moun f&egrave; l&egrave; pwobl&egrave;m yo vin tw&ograve; lou pou pote pou kont li. Mizik la bay vwa ak moman desepsyon, dlo nan je ak sitiyasyon ki sanble depase kapasite imen.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Nan mitan reyalite sa yo, lapriy&egrave; par&egrave;t k&ograve;m s&egrave;l chemen. Kerlyne Liberus prezante Bondye k&ograve;m sila ki kapab pote jistis, chanje sitiyasyon epi bay liberasyon.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Mizik sila adrese ak moun ki rive nan yon pwen kote yo pa jwenn l&ograve;t repons pase leve je yo nan direksyon Bondye.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">🔗Gade Yon Priy&egrave;: <a href=\"https://youtu.be/PFweHkWYYBM?si=wB6uXHpgPVGtj_oY\">https://youtu.be/PFweHkWYYBM?si=wB6uXHpgPVGtj_oY</a></span></p>\r\n<p class=\"p1\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">Pandan M ap Priye &mdash; Wisbens Derice</span></strong></p>\r\n<p class=\"p1\"><span class=\"s1\">7 dawout 2026</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Nan &laquo; Pandan M ap Priye &raquo;, Wisbens Derice mete aksan sou fason lapriy&egrave; ka akonpaye yon moun fas ak moman enkyetid ak ens&egrave;titid yo. Pwodiksyon an f&egrave; yon pasaj soti nan preyokipasyon pou rive nan espwa, pandan li raple enp&ograve;tans pou kontinye ch&egrave;che Bondye.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Ekri pa Wisbens Derice, pwodiksyon mizikal la pote siyati ClayBeats OneTouch, pandan Mr RezO asire miksaj ak mastering. Videyo ofisy&egrave;l la reyalize pa Emmanuel Pyram.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">🔗Gade pandan m ap Priye: <a href=\"https://youtu.be/Vz7dBT9ewD0?si=XN4z9fmRG10BYm0i\">https://youtu.be/Vz7dBT9ewD0?si=XN4z9fmRG10BYm0i</a></span></p>\r\n<p class=\"p1\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">Lavi&rsquo;m nan men Bondye &mdash; Auralie Antoine</span></strong></p>\r\n<p class=\"p1\"><span class=\"s1\">8 dawout 2026</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Nan yon lavi kote nouv&egrave;l, maladi ak diferan ens&egrave;titid ka chanje direksyon yon jounen, Auralie Antoine chwazi mete yon deklarasyon konfyans devan tout sa ki pa s&egrave;ten nan &laquo; Lavi&rsquo;m nan men Bondye &raquo;.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Mizik la pa inyore laper&egrave;z ki kapab akonpaye lavi nou chak jou, men li mete yon l&ograve;t konviksyon anfas li: gen yon Bondye ki toujou gen kontw&ograve;l.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Atrav&egrave; refren an, atis la repete k&egrave;lkeswa sa demen pote, lavi li rete nan men Bondye. Se yon pozisyon lafwa ki ch&egrave;che bay f&ograve;s pou kontinye mache san kite ens&egrave;titid pran tout plas la.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">🔗Gade Lavi&rsquo;m nan men Bondye: <a href=\"https://youtu.be/PY9NDFWZXBI?si=2GcDSCDFFFbVoYhy\">https://youtu.be/PY9NDFWZXBI?si=2GcDSCDFFFbVoYhy</a></span></p>\r\n<p class=\"p1\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">&laquo; Face to Face &raquo; &mdash; Rolande Louis</span></strong></p>\r\n<p class=\"p1\"><span class=\"s1\">16 dawout 2026</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Rolande Louis kontinye prezante diferan fas&egrave;t alb&ograve;m &laquo; Map Triyonfe &raquo; li an atrav&egrave; &nbsp;&laquo; Face to Face &raquo;, uity&egrave;m mizik sou pwoj&egrave; a.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Pwodiksyon an deplase sou teren adorasyon an, kote dezi prensipal la se rete pre Bondye epi ch&egrave;che yon relasyon ki pi pwofon av&egrave;k Li. T&egrave;ks la trav&egrave;se krey&ograve;l, frans&egrave; ak angl&egrave;, bay mizik la yon konstriksyon lengwistik ki diferan.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Videyo ofisy&egrave;l la jwenn direksyon Alexis Ecclesiaste. Av&egrave;k nouvo s&ograve;ti sa a, Rolande Louis kontinye devlope liy adorasyon ki prezan nan alb&ograve;m li a.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">🔗Gade Face to Face: <a href=\"https://youtu.be/Gg8LvFx5efc?si=J8nwfqzgtWdroq-d\">https://youtu.be/Gg8LvFx5efc?si=J8nwfqzgtWdroq-d</a></span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">Tanpri Bondye &mdash; Joe &amp; Ster</span></strong></p>\r\n<p class=\"p1\"><span class=\"s1\">16 dawout 2026</span></p>\r\n<p class=\"p1\"><span class=\"s1\">D&egrave;y&egrave; Tanpri Bondye gen yon istwa ki k&ograve;manse lontan anvan s&ograve;ti videyo a. Jones ak Esther te ekri mizik la depi 2014, sa ki bay pwodiksyon an yon plas espesyal nan chemen duo Joe &amp; Ster.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Mizik la pran f&ograve;m lapriy&egrave;, kote yo mande Bondye f&ograve;s, kouraj, espwa, lanmou ak lajwa. Li mete aksan sou sa moun nan bezwen l&egrave; li rive nan moman kote li santi li pa kapab kontinye pou kont li.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Shegger Studio asire pwodiksyon, miksaj ak mastering. Junior jwe gita, Ariel asire bas, pandan Life in Pictures Entertainment responsab pwodiksyon videyo a, ki te filme an avril 2025 nan &Eacute;glise de Dieu des Premiers Chr&eacute;tiens d&rsquo;Ha&iuml;ti.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">🔗Gade Tanpri Bondye: <a href=\"https://youtu.be/4xj4baYHfOo?si=U3OfmrieIuH-Ga79\">https://youtu.be/4xj4baYHfOo?si=U3OfmrieIuH-Ga79</a></span></p>\r\n<p class=\"p1\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">L ap Aji &mdash; Fr&egrave; Mendy feat. Fr&egrave; Vio</span></strong></p>\r\n<p class=\"p1\"><span class=\"s1\">18 dawout 2026</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Gen moman kote pasyans&nbsp; vin pi difisil pase pwobl&egrave;m nan menm. Se nan reyalite sa a L ap Aji jwenn f&ograve;s li. Fr&egrave; Mendy, ansanm ak Fr&egrave; Vio, adrese moun ki poko w&egrave; repons yo ap tann nan.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">&laquo; Pa dekouraje, pa dezespere, kontinye kenbe &raquo;: mesaj la ale dwat nan direksyon moun ki sou wout pou dekouraje. Mizik la chita sou konviksyon&nbsp; Bondye kapab ap travay menm l&egrave; okenn siy poko vizib.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Av&egrave;k yon mesaj<span class=\"Apple-converted-space\">&nbsp; </span>dir&egrave;k, &laquo; L ap Aji &raquo; mete aksan sou pasyans ak kapasite pou kontinye kw&egrave; pandan pery&ograve;d tann nan.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">🔗Gade<span class=\"Apple-converted-space\">&nbsp; </span>L ap Aji: <a href=\"https://youtu.be/mAQxeHjGCts?si=EV_8Q-Weu_G3alDb\">https://youtu.be/mAQxeHjGCts?si=EV_8Q-Weu_G3alDb</a></span></p>\r\n<p class=\"p1\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">Ou pa gen rival &mdash; Sherline Dalberis</span></strong></p>\r\n<p class=\"p1\"><span class=\"s1\">30 dawout 2026</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Kat&ograve;z lane apre premye piblikasyon li, Sherline Dalberis remete Ou Pa Gen Rival<span class=\"Apple-converted-space\">&nbsp; </span>nan aktyalite a ak yon nouvo v&egrave;syon. Chante a, ki deja trav&egrave;se plizy&egrave; jenerasyon ak diferan estil mizikal, jwenn yon l&ograve;t ent&egrave;pretasyon nan travay sa a.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Tit la deja reprann plizy&egrave; fwa nan konpa, reggae, worship ak blues. Nouvo v&egrave;syon an vini konsa k&ograve;m yon fason pou relouvri chapit yon mizik ki kontinye jwenn plas li nan rep&egrave;twa Sherline Dalberis.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">🔗Gade Ou pa gen rival: <a href=\"https://youtu.be/lBuh6Um35Qo?si=KSITtq1p5SttkX4V\">https://youtu.be/lBuh6Um35Qo?si=KSITtq1p5SttkX4V</a></span></p>\r\n<p class=\"p1\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">Anmwey Leta &mdash; Mike-Lee Elminis</span></strong></p>\r\n<p class=\"p1\"><span class=\"s1\">31 dawout 2026</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Av&egrave;k &laquo; Anmwey Leta &raquo;, Papillon Stevenson ak Mike-Lee Elminis mete an mizik doul&egrave; yon peyi ki kontinye sibi vyolans ak ensekirite. Paw&ograve;l yo denonse san k ap koule, kadav k ap miltipliye ak absans yon repons efikas devan kriz la.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Ekri ak konpoze pa de atis yo, mizik la pote vwa prensipal Mike-Lee Elminis. Aranjman an se D&amp;D Record&rsquo;s, pandan Horby Producer asire mixaj ak mastering la.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Av&egrave;k pwodiksyon Sylvio Petit, &laquo; Anmwey Leta &raquo; sonnen tankou yon kri pou mande plis responsablite devan sitiyasyon peyi a.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">🔗Gade Anmwey Leta: <a href=\"https://youtu.be/nsmVEyhq62A?si=7i-OokiH8I-9wL77\">https://youtu.be/nsmVEyhq62A?si=7i-OokiH8I-9wL77</a></span></p>\r\n<p class=\"p1\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pwodiksyon ki s&ograve;ti pandan mwa dawout 2026 la montre div&egrave;site mesaj ki kontinye trav&egrave;se mizik evanjelik ayisyen an. Gen moun ki chante sou chemen Bondye f&egrave; av&egrave;k yo, l&ograve;t ki vire b&ograve; lapriy&egrave; l&egrave; lavi vin difisil, pandan k&egrave;k chwazi pale de tann, konfyans ak relasyon p&egrave;son&egrave;l ak Bondye.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Soti nan adorasyon rive nan temwayaj, mizik sa yo pote diferan istwa ak diferan apw&ograve;ch, men yo tout jwenn yon pwenn rankont nan lafwa ki kontinye s&egrave;vi k&ograve;m sous ekspresyon pou atis yo.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s2\">Redaksyon:</span></strong></p>\r\n<p class=\"p1\"><strong><span class=\"s2\">Vanauscheca Bouzy</span></strong></p>\r\n<p class=\"p1\"><strong><span class=\"s2\">Konsepsyon Grafik:</span></strong></p>\r\n<p class=\"p1\"><strong><span class=\"s2\">Jo-Flung Bouzy &amp; Abdullah Mode</span></strong></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><strong><span class=\"s1\">#palmar&egrave;smizikvideyo</span></strong></p>\r\n<p class=\"p1\"><strong><span class=\"s1\">#evanjelik</span></strong></p>\r\n<p class=\"p1\"><strong><span class=\"s1\">#out2026 </span></strong></p>\r\n<p class=\"p1\"><strong><span class=\"s1\"><a href=\"https://www.konektem.net/blog/hashtags/konektem\">#konekte</a>m</span></strong></p>\r\n<p class=\"p1\"><strong><span class=\"s1\">#toutkotenenpotkil&egrave;</span></strong></p>', '2026-09-03 18:20:58', '2026-09-02 00:19:20', '2026-09-03 18:20:58', 1);
INSERT INTO `news` (`id`, `newsImg`, `newsTitle`, `newsDate`, `newsCategory`, `newsHeadline`, `fullContent`, `reads`, `likes`, `shares`, `featured_image_ids`, `image_id`, `title`, `category`, `headline`, `content`, `published_at`, `created_at`, `updated_at`, `author_id`) VALUES
(83, NULL, NULL, NULL, NULL, '', NULL, 0, 0, 0, NULL, 405, 'Palmarès Mizik/Videyo Evanjelik – Septanm 2026', 'Mizik-videyo', 'Septanm 2026 se te yon mwa ki pote anpil mouvman nan mizik evanjelik ayisyen an. Nouvo single, videyo ofisyèl, kolaborasyon, cover, repriz kantik.\r\nAtravè nouvo edisyon Palmarès Mizik/Videyo Evanjelik, redaksyon an retounen sou pwodiksyon ki te parèt oswa ki te jwenn yon nouvo vizibilite pandan mwa a, pandan li mete aksan sou mesaj yo, demach atistik yo ak kolaborasyon ki kontinye pote mouvman nan gospel ayisyen an.', '<p class=\"p1\"><span class=\"s1\">Septanm 2026 se te yon mwa ki pote anpil mouvman nan mizik evanjelik ayisyen an. Nouvo single, videyo ofisy&egrave;l, kolaborasyon, cover, repriz kantik.</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Atrav&egrave; nouvo edisyon Palmar&egrave;s Mizik/Videyo Evanjelik, redaksyon an retounen sou pwodiksyon ki te par&egrave;t oswa ki te jwenn yon nouvo vizibilite pandan mwa a, pandan li mete aksan sou mesaj yo, demach atistik yo ak kolaborasyon ki kontinye pote mouvman nan gospel ayisyen an.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Plizy&egrave; tandans par&egrave;t kl&egrave; nan seleksyon an: konfyans nan Bondye nan mitan difikilte, abandon ak volonte li, rekonesans, pwoteksyon, temwayaj, retou sou bon chemen an, ansanm ak yon volonte pou f&egrave; k&egrave;k ansyen chante ak kantik jwenn nouvo lavi atrav&egrave; nouvo ent&egrave;pretasyon.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">MWA A AN CHIF</span></p>\r\n<p class=\"p1\"><span class=\"s1\">22 pwodiksyon jwenn plas yo nan edisyon Palmar&egrave;s Mizik/Videyo Evanjelik sa a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pami yo genyen nouvo single, videyo ofisy&egrave;l pou mizik ki te deja egziste, kolaborasyon, cover ak nouvo ent&egrave;pretasyon mizik ki deja make rep&egrave;twa evanjelik la.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Seleksyon an montre tou div&egrave;site estil yo: rap gospel, adorasyon, mizik tradisyon&egrave;l, kantik, nouvo aranjman ak kolaborasyon.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Yon premye single byen idantifye: &ldquo; Louvri Je M &rdquo; Sameldith, ki soti 25 septanm 2026.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">5 TIT POU DEKOUVRI</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Yon seleksyon editoryal ki mete aksan sou div&egrave;site demach ki prezan nan edisyon an.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Barbara Cassamajor &mdash; &ldquo; Konfyans &ldquo;</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan &laquo; Konfyans &raquo;, Barbara Cassamajor pa prezante lafwa tankou absans pwobl&egrave;m. Li pale pito de desizyon pou kontinye kw&egrave; menm l&egrave; moun nan ap trav&egrave;se moman ki pi f&egrave;nwa.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Paw&ograve;l &ldquo;F&egrave; sa ou vle&hellip; Sa ou vle se li m&rsquo;a vle tou &rdquo; mennen chante a sou yon l&ograve;t nivo: mete lavi ak direksyon p&egrave;son&egrave;l nan men Bondye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Sameldith Jean Baptiste &mdash; &ldquo; Louvri Je M &rdquo;</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pou premye single li, Sameldith Jean-Baptiste chwazi antre nan mizik la ak yon refleksyon ki soti nan konsyans espirity&egrave;l.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo; Louvri Je M &rdquo; pale de nesesite pou moun nan rekon&egrave;t kote li ye, konprann enfliyans ki kapab f&egrave; l p&egrave;di direksyon epi deside pa rete nan f&egrave;nwa.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Rachelle Geffrard &mdash; &laquo; Si M Ap Viv Kounya &rdquo;</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Rachelle Geffrard mete lavi li nan mitan yon temwayaj rekonesans.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan &ldquo;Si M Ap Viv Kounya &rdquo;, egzistans jodi a prezante tankou yon rezilta gras, fidelite ak sip&ograve; Bondye nan diferan etap lavi a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Fr&egrave; Vio l&rsquo;&Eacute;vang&eacute;liste &mdash; &ldquo; Konviksyon &rdquo;</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Av&egrave;k &ldquo;Konviksyon &rdquo;, Fr&egrave; Vio l&rsquo;&Eacute;vang&eacute;liste mete misyon li k&ograve;m atis devan.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pou li, mizik la pa s&egrave;lman dwe rive jwenn anpil moun, li dwe pote yon mesaj, bay Bondye glwa epi kapab beni yon lavi.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Yahawachi Gospel Choir feat. Loutchina D&eacute;cius &amp; Joy Clerf Derisier &mdash; &ldquo; Nothing Is Too Big &rdquo;</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo; Nothing Is Too Big &rdquo; pote yon l&ograve;t koul&egrave; nan seleksyon an.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Chante a pale de bay Bondye, men li ale pi lwen pase kestyon kantite. Mesaj la rekon&egrave;t moun nan kapab bay tout sa li genyen, men sa li bay la pap janm mezire ak grand&egrave; Bondye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">REVELASYON MWA A</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Sameldith Jean-Baptiste &mdash; &ldquo; Louvri Je M &rdquo;</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pou premye single li, Sameldith Jean-Baptiste chwazi yon antre ki pa limite ak prezante vwa li s&egrave;lman.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Li pale de pw&ograve;p eksperyans li, de konsyans espirity&egrave;l ak de nesesite pou moun nan w&egrave; kote li ye nan relasyon li ak Bondye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo; Louvri je m pou m ka w&egrave; kote m ye a &rdquo; se demann ki soutni tout chante a. T&egrave;ks la itilize tou referans nan 2 Korentyen 4:3-6 ak Matye 6:22-23 pou ranf&ograve;se mesaj limy&egrave;, vizyon ak direksyon espirity&egrave;l la.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Premye pwodiksyon sa a deja mete devan yon demach ki chita sou refleksyon, lafwa ak transf&ograve;masyon p&egrave;son&egrave;l.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">YON KOLABORASYON POU RETNI</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Yahawachi Gospel Choir feat. Loutchina D&eacute;cius &amp; Joy Clerf Derisier &mdash; &ldquo; Nothing Is Too Big &rdquo;</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Plizy&egrave; kolaborasyon prezan nan edisyon septanm nan, men &ldquo; Nothing Is Too Big &rdquo; pote ansanm yon koral ak de vwa ki deja prezan nan aktyalite gospel la.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Mizik la mete aksan sou don, dispozisyon pou bay ak avansman Way&ograve;m Bondye a, pandan li raple moun nan ke okenn ofrann pa ka s&egrave;vi k&ograve;m mezi pou grand&egrave; Bondye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">MEMWA AK ERITAJ</span></p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Nouvo ent&egrave;pretasyon bay ansyen chante yo yon l&ograve;t lavi&rdquo;</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Youn nan eleman ki par&egrave;t f&ograve; nan edisyon septanm nan se plas ansyen chante ak kantik yo kontinye genyen.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Past&egrave; Jean Claude D&eacute;risier retounen sou &ldquo;Seny&egrave; Kondwi Mwen Jan Ou Vle &rdquo;, yon chante ki deja abitye nan rep&egrave;twa adorasyon an.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Paulande L&eacute;onard Neus reprann &ldquo;Ala yon Zanmi se Jezi &rdquo;, men li chante l ak yon l&ograve;t konpreyansyon ki soti nan eksperyans li f&egrave; nan lavi ak relasyon li ak moun.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Bethsa&iuml;da Lexis, ansanm ak N&eacute;&iuml;ssa Fran&ccedil;ois, retounen sou &ldquo; Sa Ou Ye Pou Mwen &rdquo;, yon mizik orijinal Les Gilbert, nan dezy&egrave;m epiz&ograve;d &laquo; Retro Session &raquo;.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Sterlande Etienne ak Mike-Lee Elminis bay &ldquo;Je veux aussi chanter le soir &rdquo; yon nouvo ent&egrave;pretasyon, pandan Frantz Joseph reprann &ldquo;Sakrifis mwen &rdquo; Sterlande Etienne te pibliye k&egrave;k mwa anvan. </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Tout demach sa yo montre yon reyalite enp&ograve;tan: mizik evanjelik ayisyen an pa s&egrave;lman ap kreye nouvo chante, li ap tou kons&egrave;ve, transm&egrave;t ak reent&egrave;prete eritaj li.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;PWODIKSYON KI NAN PALMAR&Egrave;S LA&rdquo;</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">1. &ldquo;Deklare&rdquo; &mdash; Peterson Pierre</span></p>\r\n<p class=\"p1\"><span class=\"s1\">1ye septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Apre plizy&egrave; ane kote li konstwi yon rep&egrave;twa ki chita anpil sou lafwa, delivrans ak konfyans nan Bondye, Peterson Pierre retounen ak &ldquo; Deklare &rdquo;, yon single ki mete paw&ograve;l lafwa a fas ak reyalite lavi a. Atis la pa evite nonmen sa ki ka kraze moral yon moun: maladi, povrete, doul&egrave;, move moman ak pwobl&egrave;m. Men olye li kite sitiyasyon sa yo domine chante a, li s&egrave;vi ak mizik la pou chanje pozisyon moun k ap koute a devan yo.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Ekspresyon &ldquo;deklare manda l fini &rdquo;<span class=\"Apple-converted-space\">&nbsp; </span>tounen youn nan prensipal zouti t&egrave;ks la. Li bay chante a yon f&ograve;m deklarasyon kote paw&ograve;l la s&egrave;vi k&ograve;m repons devan sa moun nan ap trav&egrave;se. Peterson Pierre pa prezante lafwa tankou yon lavi san pwobl&egrave;m, li mete l pito tankou yon fason pou moun nan pa kite pwobl&egrave;m nan jwenn d&egrave;nye mo a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Deklare &rdquo; antre nan yon katal&ograve;g kote Peterson Pierre deja gen album &ldquo;Nan Prezans Ou&rdquo;, ki soti an 2017, ansanm ak tit tankou &ldquo;Lakwa &rdquo;, &ldquo; Yon S&egrave;l Mo Sifi &rdquo; ak &ldquo;S&egrave;l Jezi &rdquo;.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/t9FuBKFrZLA?si=Zmm5CVctsV7EAsJS</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">2. &ldquo;Seny&egrave; Kondwi Mwen Jan Ou Vle &rdquo;&mdash; Past&egrave; Jean Claude Derisier</span></p>\r\n<p class=\"p1\"><span class=\"s1\"> 4 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Gen chante ki jwenn f&ograve;s yo pa s&egrave;lman nan nouvo son yo pote, men nan kapasite yon nouvo ent&egrave;pr&egrave;t genyen pou f&egrave; yon mesaj ki deja konnen jwenn yon l&ograve;t prezans. Se nan lojik sa a Past&egrave; Jean Claude Derisier retounen sou &ldquo;Seny&egrave; Kondwi Mwen Jan Ou Vle &rdquo;, yon chante ki deja genyen plas li nan rep&egrave;twa adorasyon an.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Mennen mwen kote ou vle, menm l&egrave; mwen pa ta vle / Wa f&egrave; m jan ou vle, menm l&egrave; m pa vle &rdquo; mete yon kontradiksyon ki enp&ograve;tan nan lavi espirity&egrave;l la devan moun k ap koute a: moun nan gen volonte pa li, plan pa li ak preferans pa li, men li mande Bondye pou kontinye dirije l menm l&egrave; direksyon sa pa konf&ograve;tab pou li. Se pa s&egrave;lman yon demann pou Bondye akonpaye l, se yon demann pou Bondye pran direksyon an.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nouvo ent&egrave;pretasyon Past&egrave; Jean Claude D&eacute;risier la mete konsa abandon, obeyisans ak soumisyon ak volonte Bondye nan fon chante a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/muT-DCp4SGs?si=WeagrKHJl_8edqJN</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">3. &ldquo; J&rsquo;ai confiance en toi &rdquo; &mdash; Caleb Emmanuel Pierre</span></p>\r\n<p class=\"p1\"><span class=\"s1\">6 septanm 2026**</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Av&egrave;k &ldquo;J&rsquo;ai confiance en toi &rdquo;, Caleb Emmanuel Pierre chwazi youn nan t&egrave;m ki pi prezan nan mizik kretyen an, men li trete l sou baz kapasite Bondye pou aji. Konfyans li chante a pa s&egrave;lman emosyon&egrave;l, li relye ak yon seri aksyon li atribye ak Bondye, delivre, restore, konsole epi ent&egrave;vni nan lavi moun.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Referans ak S&ograve;m 33:9 la pote yon fondasyon biblik nan demach la: Bondye pale, epi sa Li di a rive. Sa f&egrave; chante a pase soti nan yon deklarasyon &ldquo;mwen f&egrave; Bondye konfyans &rdquo; pou rive nan yon l&ograve;t kestyon: &ldquo;sou kisa konfyans sa a chita?&rdquo; Pou Caleb, li chita sou Paw&ograve;l Bondye ak kapasite Li pou akonpli sa Li di.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/VaTdq4EKyn4?si=fLzrfIyLtOye93td</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">4. &ldquo; Konviksyon &rdquo; &mdash; Fr&egrave; Vio l&rsquo;Evang&eacute;liste</span></p>\r\n<p class=\"p1\"><span class=\"s1\">7 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan yon endistri kote kantite views, streams ak vizibilite sou rezo sosyal yo souvan s&egrave;vi k&ograve;m mezi siks&egrave;, Fr&egrave; Vio l&rsquo;&Eacute;vang&eacute;liste chwazi yon l&ograve;t mezi nan &ldquo;Konviksyon &rdquo;. Li mete kestyon misyon an devan kestyon popilarite a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Depi Bondye jwenn glwa li, depi yon nanm ka beni, pou lesy&egrave;l misyon mwen akonpli &rdquo; rezime pozisyon atis la. Nan fason sa a, &ldquo;Konviksyon &rdquo; pa s&egrave;lman yon chante sou sa li kw&egrave;, li sanble ak yon deklarasyon sou fason li konprann travay li k&ograve;m rap&egrave; kretyen.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Gospel rap la s&egrave;vi isit la k&ograve;m yon mwayen pou mete mesaj la nan yon langaj dir&egrave;k, mod&egrave;n epi pw&ograve;ch yon piblik ki abitye ak rap. Tit la antre nan kontinite pwoj&egrave; &ldquo;Flow de Gloire&rdquo;, kote Fr&egrave; Vio te deja prezante &ldquo;Rem&egrave;t Mwen Legliz Mwen &rdquo; ak &ldquo;Dejenerasyon &rdquo;.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan &ldquo;Konviksyon &rdquo;, misyon an vin krit&egrave; prensipal la: si mesaj la rive touche yon lavi epi Bondye jwenn glwa, atis la konsidere travay la k&ograve;m yon travay ki jwenn sans li.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/SVn_C6XLXz8?si=KW_f_096FiZO9f4k</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">5. &ldquo;Konfyans &rdquo; &mdash; Barbara Cassamajor</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Videyo ofisy&egrave;l: 10 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Konfyans &rdquo; pa yon mizik ki f&egrave;t dey&ograve; yon pwoj&egrave; izole. Li se 10y&egrave;m tit sou &ldquo;Renouveau&rdquo;, yon album 12 chante Barbara Cassamajor mete dey&ograve; nan k&ograve;mansman 2026. Album lan gen l&ograve;t tit tankou &ldquo;Pwom&egrave;s Pa M &rdquo;, &ldquo;Yon Temwanyaj Tou N&egrave;f &rdquo;, &ldquo; M Ap Briye &rdquo; ak &ldquo; C&rsquo;est Dieu &rdquo;.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan chante a, Barbara pa defini konfyans k&ograve;m absans epr&egrave;v. Li f&egrave; egzakteman kontr&egrave; a. Li rekon&egrave;t moman f&egrave;nwa yo epi li chwazi mete konfyans nan Bondye andedan moman sa yo. &ldquo;M&rsquo;ap kw&egrave; nan ou menm nan moman&rsquo;m pi f&egrave;nwa / M&rsquo; konte sou ou &rdquo; bay chante a yon ton p&egrave;son&egrave;l ki f&egrave; konfyans lan sanble plis ak yon desizyon pase ak yon emosyon.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Men pati ki pote mesaj la pi lwen toujou se abandon an: &ldquo;F&egrave; sa ou vle&hellip; Sa ou vle se li m&rsquo;a vle tou &rdquo;. La a, konfyans lan pa s&egrave;lman vle di kw&egrave; Bondye kapab chanje sikonstans yo, li vle di aksepte direksyon Li menm si direksyon sa a pa menm ak plan moun nan.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Genoldens Desulma siyen konpozisyon ak pwodiksyon an, Woodberton Toussaint, Ernst Junior Marcelin, Jerry Meradieu, Alexis Fortune, Bertrand Cornely ak Shelda Massillon patisipe nan pwodiksyon mizikal la. Richenn Riche reyalize videyo ofisy&egrave;l la.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/ZrRQaYt76Xo?si=5uUpypKGLv6bqUNi</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">6. &ldquo;Jezi Pi Bon &rdquo;&mdash; Maxon Dautruche &amp; Sancia Supre</span></p>\r\n<p class=\"p1\"><span class=\"s1\">11 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">D&egrave;y&egrave; &ldquo;Jezi Pi Bon &rdquo; genyen yon istwa fanmi ki bay chante a yon val&egrave; diferan. Se Pasteur Maxo Dautruche, papa Maxon Dautruche ak Sancia Supre, ki te ekri t&egrave;ks la pandan li te j&egrave;n. Plizy&egrave; ane apre, de pitit li yo deside pote t&egrave;ks sa a nan yon pwodiksyon mizikal pou onore papa yo epi transm&egrave;t mesaj li bay yon l&ograve;t jenerasyon.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Chante a k&ograve;manse ak istwa yon lavi ki rankontre Jezi. Apre sa, li s&egrave;vi ak yon konparezon senp men dir&egrave;k ant rich&egrave;s matery&egrave;l ak val&egrave; relasyon ak Kris la. L&ograve;, dyaman ak pozisyon ekonomik par&egrave;t tankou bagay ki gen val&egrave;, men t&egrave;ks la mete Jezi pi wo pase yo.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Jezi Pi Bon &rdquo; s&egrave;vi konsa ak mizik k&ograve;m yon pon ant twa bagay: &ldquo;eritaj fanmi, transmisyon lafwa ak nouvo jenerasyon&rdquo;.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/hmj39P8oyZw?si=Plt2ut9MTriY5mrU</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">7. &ldquo;Ou Se Tout Pou Mwen &rdquo;&mdash; Impact Worship Team&rdquo;</span></p>\r\n<p class=\"p1\"><span class=\"s1\">13 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Impact Worship Team antre nan yon espas ki sansib anpil nan &ldquo;Ou Se Tout Pou Mwen &rdquo;: moman kote moun nan santi solitid, febl&egrave;s, dekourajman oswa enkapasite pou kontinye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Olye chante a eseye minimize reyalite sa yo, li rekon&egrave;t yo epi li mete yon deklarasyon repetitif devan yo: &ldquo;Jezi ou se tout pou mwen &rdquo;. Repete fraz sa a bay mizik la yon karakteristik adorasyon, men li s&egrave;vi tou k&ograve;m yon repons emosyon&egrave;l ak espirity&egrave;l devan sa moun nan ap viv.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Dezy&egrave;m pati a antre nan soufrans, dlo nan je ak bezwen pou yon moun leve moun nan. Nan sans sa a, chante a pa s&egrave;lman yon deklarasyon afeksyon pou Jezi li prezante Li tankou yon sous estabilite nan moman kote l&ograve;t soutyen yo sanble pa sifi.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Wendelson Pierre-Louis siyen konpozisyon an, Dens Music/Studios pote pwodiksyon an, Jean Johanson Dye asire mixaj ak mastering, pandan Guima Aristide reyalize videyo ofisy&egrave;l la.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/UWN_qDN7qMI?si=288Xl3BIc_5nklbd</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">8. &ldquo;Si M Ap Viv Kounya &rdquo;&mdash; Rachelle Geffrard</span></p>\r\n<p class=\"p1\"><span class=\"s1\">13 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Si M Ap Viv Kounya &rdquo; Rachelle prezante chante a k&ograve;m yon temwayaj ki konekte dir&egrave;kteman ak pw&ograve;p lavi li.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Tit la deja bay kle mesaj la: si li toujou viv jodi a, se pa yon bagay li konsidere k&ograve;m otomatik. Li gade sou sa li trav&egrave;se epi li w&egrave; lavi li k&ograve;m yon temwayaj sou gras ak sip&ograve; Bondye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Maestro Jean Daniel Valentin siyen t&egrave;ks la. Dapre Rachelle, t&egrave;ks sa a te rive nan yon moman kote li te bezwen yon priy&egrave;, sa ki ede eksplike poukisa ent&egrave;pretasyon an gen yon dimansyon p&egrave;son&egrave;l konsa. Li dekri t&egrave;t li jodi a k&ograve;m yon moun ki gen plis konviksyon, plis det&egrave;minasyon ak plis imilite apre eksperyans li yo.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Shegger pote pwodiksyon, mixaj ak mastering, av&egrave;k Oberdson Augustin k&ograve;m ko-pwodikt&egrave; ak responsab sekans. Videyo a reyalize pa Nike Neton Joseph.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&laquo; Si M Ap Viv Kounya &raquo; pa s&egrave;lman make yon nouvo s&ograve;ti; li s&egrave;vi k&ograve;m yon rek&ograve;mansman mizikal ki chita sou eksperyans lavi.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/9cft7QVd720?si=Jf0w94cFDrubQeNB</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">9. &ldquo;Ala yon Zanmi se Jezi &rdquo;&mdash; Paulande L&eacute;onard Neus</span></p>\r\n<p class=\"p1\"><span class=\"s1\">13 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Paulande L&eacute;onard Neus te konnen &ldquo;Ala yon Zanmi se Jezi &rdquo; depi lontan. Li konn chante l depi li te timoun. Men nouvo cover sa a soti nan yon reyalite ki enteresan: pafwa yon moun ka konnen tout paw&ograve;l yon chante san li poko viv ase pou l konprann tout sa paw&ograve;l sa yo vle di.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Paulande esplike se eksperyans lavi ak relasyon ak l&ograve;t moun ki f&egrave; kantik la pran yon nouvo sans pou li. Sous ki te dokimante piblikasyon an f&egrave; konnen li te chwazi mete cover la dey&ograve; nan okazyon aniv&egrave;s&egrave; li, k&ograve;m yon retou sou yon chante ki te akonpaye l depi anfans.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">L&egrave; kantik la pale de lapenn, febl&egrave;s, tantasyon ak zanmi ki ka bliye moun nan, paw&ograve;l sa yo pa rete ank&ograve; s&egrave;lman yon seri fraz relijye, yo konekte ak eksperyans rey&egrave;l.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Se konsa cover Paulande lan jwenn enter&egrave; li: chante a pa chanje, men moun k ap chante l la chanje. Eksperyans li bay menm paw&ograve;l yo yon l&ograve;t pwa.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Manson Talleyrand, aka Doc Kompa, responsab pwodiksyon, klavye, mixaj ak mastering; Chuinidor Paul jwe bass epi Luterson Cid reyalize videyo a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/FKggw0WXX9o?si=_b_HmW4epNjjdcJq</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">10. &ldquo;Praise Him &rdquo;&mdash; Stevens Vilus feat. Loutchina Decius</span></p>\r\n<p class=\"p1\"><span class=\"s1\">15 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Praise Him &rdquo; mete de liniv&egrave; vokal ansanm: apw&ograve;ch rap-gospel Stevens Vilus la ak vwa gospel Loutchina Decius.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Tit la f&egrave; pati GENESIS, premye album Stevens Vilus, kote li plase k&ograve;m 11y&egrave;m chante nan yon pwoj&egrave; 14 tracks. Sous ki dokimante atis la prezante Stevens k&ograve;m yon atis, ot&egrave;-konpozit&egrave; ak pwodikt&egrave; ayisyen-ameriken ki itilize rap, drill ak amapiano pou pote mesaj kretyen nan yon langaj mizikal kontanporen.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Se la kolaborasyon an jwenn enter&egrave; li. Loutchina pote yon vokal ki byen idantifye ak gospel tradisyon&egrave;l/kontanporen, pandan Stevens pote k&ograve;d mizik iben yo. &ldquo;Praise Him &rdquo; vin konsa yon rankont ant louwanj ak yon fason mod&egrave;n pou prezante li, sitou pou yon piblik ki pi pre rap ak mizik urban.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Videyo ofisy&egrave;l la soti 15 septanm, av&egrave;k RICHE k&ograve;m reyalizat&egrave; ak Carl Jules k&ograve;m ko-direkt&egrave;.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/Fp85gVefcdc?si=XTBFJQCL6zie7-Bf</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">11. &ldquo;Kris A La P&ograve;t &rdquo;&mdash; Maestro Williams feat. Psal Petit Frandy</span></p>\r\n<p class=\"p1\"><span class=\"s1\">15 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Maestro Williams ak Psal Petit Frandy itilize &ldquo;Kris A La Pot &rdquo; pou retounen sou youn nan mesaj fondamantal lafwa kretyen an: lanmou Bondye pou limanite ak lavi et&egrave;n&egrave;l atrav&egrave; Jezi Kris.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Referans ak Jan 3:16 la enp&ograve;tan paske li bay tout chante a yon pwen doktrinal kl&egrave;. Men tit &ldquo;Kris A La Pot &rdquo; la ajoute yon l&ograve;t imaj ki byen konnen nan predikasyon ak mizik kretyen: Kris ki kanpe devan p&ograve;t la epi k ap tann moun nan ouvri.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Premye a se sa Bondye deja f&egrave;: Li bay Pitit Li. Dezy&egrave;m nan se repons moun nan: &egrave;ske li dispoze ouvri epi kw&egrave;?</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Kris A La Pot &rdquo; pran yon dimansyon evanjelizasyon. Mesaj la kl&egrave;, dir&egrave;k epi santre sou desizyon p&egrave;son&egrave;l devan ap&egrave;l Kris la. Videyo ofisy&egrave;l la te pibliye 15 septanm 2026. </span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/fYZsMgRTydk?si=8Sj0vvh8Eakt4aL6</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">12. &ldquo;Sa Ou Ye Pou Mwen &rdquo; &mdash; Bethsa&iuml;da Lexis feat. N&eacute;&iuml;ssa Fran&ccedil;ois</span></p>\r\n<p class=\"p1\"><span class=\"s1\">19 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Av&egrave;k &ldquo;Retro Session &rdquo;, Bethsa&iuml;da Lexis ap f&egrave; yon travay ki depase senp cover. Pwoj&egrave; a s&egrave;vi pou retounen sou chante ki te deja jwenn plas yo nan memwa piblik evanjelik la epi mete yo devan yon l&ograve;t jenerasyon ak yon nouvo tretman mizikal.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pou dezy&egrave;m epiz&ograve;d la, li chwazi &ldquo;Sa Ou Ye Pou Mwen (Ou Se Referans Mwen) &rdquo;, yon mizik orijinal Les Gilbert, epi li envite N&eacute;&iuml;ssa Fran&ccedil;ois pou pataje nouvo ent&egrave;pretasyon an.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Enter&egrave; demach la chita nan balans ki neses&egrave; l&egrave; y ap reprann yon klasik: &ldquo;f&ograve;k nouvo v&egrave;syon an gen pw&ograve;p p&egrave;sonalite li san li pa efase idantite chante orijinal la.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Adlai J. Alexis pran an chaj realizasyon, montaj, pwodiksyon ak aranjman, pandan Jonathan J. Alexis asire mixaj ak mastering anba pwodiksyon NCloudStudio.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Sa Ou Ye Pou Mwen &rdquo; konsa antre nan mouvman ki ap f&egrave;t nan gospel ayisyen an kote nouvo pwodiksyon yo ap viv b&ograve; kote travay memwa sou mizik ki te make l&ograve;t ep&ograve;k.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/gVWF9lfk0Xk?si=LBjjDQYiHSrx8cIN</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">13. &ldquo;Alyans Saaa &rdquo;&mdash; Pastor Omri Massena</span></p>\r\n<p class=\"p1\"><span class=\"s1\">19 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan &ldquo;Alyans Saaa &rdquo;, Pastor Omri Massena pa mete sikonstans moun nan nan sant sekirite li, li mete alyans lan.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo; Lavi m kache nan Bondye / M paka fini mal &rdquo; s&egrave;vi k&ograve;m youn nan deklarasyon ki pi f&ograve; nan chante a. Li montre fason t&egrave;ks la ap konstwi yon diferans ant sa moun nan ap trav&egrave;se ak sa li kw&egrave; sou pozisyon li devan Bondye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Se sa ki bay &laquo; Alyans Saaa &raquo; karakteristik li. Li pa s&egrave;lman di Bondye pral ede, li chita sou lide ke relasyon ant Bondye ak moun nan gen yon fondasyon ki pi solid pase sikonstans akty&egrave;l yo.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/mvl8vpkdj3o?si=1vPJDTjbwYkUfscs</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">14. &ldquo;M Abandone M &rdquo;&mdash; Joy Clerf Derisier feat. Loutchina Decius &amp; Genoldens Desulma</span></p>\r\n<p class=\"p1\"><span class=\"s1\">Official Visualizer: 20 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;M Abandone M &rdquo; te deja soti nan mwa avril k&ograve;m dezy&egrave;m tit sou Pa Pale, album 14 chante Joy Clerf Derisier la. Piblikasyon yon Official Visualizer nan mwa septanm nan bay mizik la yon nouvo sik vizibilite.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan t&egrave;ks la, Joy Clerf k&ograve;manse ak yon konsta: pw&ograve;p volonte li te mennen l nan yon seri eksperyans li pa vle repete. Imaj &ldquo;yon bato san vwal &rdquo;la espesyalman f&ograve; paske li reprezante mouvman san direksyon. Bato a pa kanpe, men li pa metrize kote li prale.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Chanjman chante a f&egrave;t l&egrave; atis la konprann diferans ant mache selon pw&ograve;p volonte li ak mache nan volonte Bondye. Se la &ldquo;M Abandone M &rdquo; pran sans li: abandone pa vle di bay lavi a legen li vle di depoze kontw&ograve;l la.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Joy Clerf Derisier ak Genoldens Desulma kredite k&ograve;m ot&egrave;, pandan Genoldens responsab pwodiksyon an.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/lXlyvt5KbEE?si=aFG738Cd2TBNyFjK</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">15. &ldquo;Brebi Egare &rdquo; &mdash; Job &amp; Ti Past&egrave;</span></p>\r\n<p class=\"p1\"><span class=\"s1\">22 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Brebi Egare &rdquo;pran yon imaj biblik ki deja gen anpil pwa nan tradisyon kretyen an: yon brebi ki kite chemen an epi ki p&egrave;di direksyon li.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Job ak Ti Past&egrave; itilize imaj sa a pou pale sou chwa, distans ak konsekans. Moun ki nan chante a pa p&egrave;di paske li pa t janm gen yon chemen, li p&egrave;di paske li pran distans ak yon chemen li te deja konnen.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Gabriel Alexis Fr&egrave; Alexis, siyen t&egrave;ks la ak beat la epi li asire mixaj ak mastering.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/XL73X3MMwNI?si=dTNeEw5tCpiyKi3B</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">16. &ldquo;Bondye m nan gran &rdquo;&mdash; Psalmiste Peterson Jaboin</span></p>\r\n<p class=\"p1\"><span class=\"s1\">22 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Peterson Jaboin pa chwazi prezante grand&egrave; Bondye s&egrave;lman atrav&egrave; yon seri adjektif. Nan &ldquo;Bondye m nan gran &rdquo;, li s&egrave;vi ak pw&ograve;p chemen li k&ograve;m pr&egrave;v mesaj li vle pote.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Kote m soti a av&egrave;k kote m rive / Bondye ap mache av&egrave; m, li pap lage &rdquo;mete de pwen nan lavi a fas ak fas: pwen depa a ak kote moun nan rive. Distans ant de pwen sa yo vin tounen yon temwayaj.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Chante a antre tou nan kestyon pwom&egrave;s. L&egrave; atis la di sa Bondye pwom&egrave;t Li f&egrave; li, li opoze fidelite Bondye ak sitiyasyon kote eksperyans lavi te ka f&egrave; li kw&egrave; li pa t gen avni. Se konsa, &ldquo;Bondye m nan gran &rdquo; pa s&egrave;lman yon chante sou pouvwa Bondye, se yon chante sou memwa: gade d&egrave;y&egrave; pou konprann poukisa moun nan kontinye f&egrave; konfyans pou sa ki devan.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Peterson Jaboin siyen t&egrave;ks ak melodi a, pandan Maestro TKO responsab pwodiksyon, sekans, mixaj ak mastering.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/79tTXxa8BgM?si=lRX72lYeKMBITF_v</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">17. &ldquo;Louvri Je M &rdquo;&mdash; Sameldith Jean-Baptiste</span></p>\r\n<p class=\"p1\"><span class=\"s1\">25 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pou yon premye single, Sameldith Jean-Baptiste chwazi yon sij&egrave; ki mande plis pase kapasite vokal: konsyans espirity&egrave;l.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Louvri Je M &rdquo; soti nan lide ke yon moun kapab ap viv, ap avanse, menm ap fonksyone n&ograve;malman, pandan li pa vr&egrave;man w&egrave; kote li ye. Se la demann &ldquo;Louvri je m pou m ka w&egrave; kote m ye a &rdquo; pran tout f&ograve;s li.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">T&egrave;ks la antre tou nan kestyon enfliyans. L&egrave; Sameldith pale de moun ki gen je men ki pa w&egrave; ak z&ograve;r&egrave;y men ki pa tande, li f&egrave; diferans ant prezans fizik ak konsyans espirity&egrave;l. Referans ak 2 Korentyen 4:3-6 ak Matye 6:22-23 ranf&ograve;se imaj limy&egrave;, f&egrave;nwa ak vizyon an.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Louvri Je M &rdquo; dire anviwon 4 minit 33, av&egrave;k Sameldith Jean-Baptiste k&ograve;m ot&egrave;, konpozit&egrave; ak vwa prensipal; DanyBeat k&ograve;m pwodikt&egrave;, epi Shalomson Lamy nan saxophone.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pou yon premye pwodiksyon, se yon antre ki deja bay k&egrave;k endis sou idantite Sameldith: yon mizik ki pa s&egrave;lman vle sonnen byen, men ki vle pouse moun reflechi.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/aKtupFQbOYc?si=CyXfizgFNBta6p-F</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">18. &ldquo;Nothing Is Too Big &rdquo;&mdash; Yahawachi Gospel Choir feat. Loutchina D&eacute;cius &amp; Joy Clerf Derisier</span></p>\r\n<p class=\"p1\"><span class=\"s1\">26 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Nothing Is Too Big &rdquo; pran sij&egrave; bay la epi li evite limite l ak kestyon kantite.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Depi nan k&ograve;mansman, chante a mete yon moun ki dispoze bay Bondye tout sa li genyen. Men mesaj la chanje rapidman l&egrave; li rekon&egrave;t menm pi gwo ofrann lan pa kapab s&egrave;vi k&ograve;m mezi pou grand&egrave; Bondye. Se la tit la jwenn pwofond&egrave; li: pa gen anyen ki tw&ograve; gwo pou bay Bondye, men pa gen okenn bagay ou bay ki ka f&egrave; Bondye vin d&egrave;t ou.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pati krey&ograve;l la : Bay pou avansman way&ograve;m nan, mete chante a nan yon dimansyon kominot&egrave;. Bay la pa prezante s&egrave;lman k&ograve;m yon aksyon p&egrave;son&egrave;l, li konekte ak travay Way&ograve;m Bondye a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pwodiksyon an pote anpil kredi: Loutchina D&eacute;cius ak Joy Clerf Derisier nan lead vocals; Maestro Adrien Peterson nan t&egrave;ks, konpozisyon ak aranjman; Handy Baubrun k&ograve;m s&eacute;quenceur; Johnny Joseph Lion Records ak Louis Mardoch&eacute; Claudin k&ograve;m pwodikt&egrave;. EPG C&eacute;sar ak Jack Disign reyalize videyo a sou yon senaryo Adrien Peterson.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Li se youn nan pwodiksyon mwa a kote dimansyon koral, kolaborasyon ak mesaj sosyal/espirity&egrave;l rankontre nan menm pwoj&egrave; a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/VqEvy0m8NSM?si=NCNrRh6aJ2yXxbHH</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">19. &ldquo;Lanmou Bon Dye &rdquo;&mdash; Josu&eacute; Elisme &amp; Mardoch&eacute;e Azard</span></p>\r\n<p class=\"p1\"><span class=\"s1\">27 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan &ldquo;Lanmou Bon Dye &rdquo;, Josu&eacute; Elisme ak Mardoch&eacute;e Azard chwazi yon t&egrave;m ki par&egrave;t senp an premye, men ki gen anpil dimansyon nan mizik kretyen an.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Chante a pa prezante renmen sa a s&egrave;lman tankou yon santiman ki bay moun k&egrave; kontan. Li mete l tankou yon prezans ki soutni, oryante epi bay espwa atrav&egrave; diferan etap lavi.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">L&egrave; sikonstans yo chanje, l&egrave; gen fatig oswa kestyon san repons, Lanmou Bondye prezante tankou yon pwen kote moun nan kapab retounen.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Kolaborasyon Josu&eacute; Elisme ak Mardoch&eacute;e Azard la chwazi konsa yon mesaj aksesib, men fondamantal: anvan moun nan pale sou sa li ka f&egrave; pou Bondye, chante a raple sa relasyon ak lanmou Bondye reprezante pou li.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/dkp0M2Oy2_w?si=Cx3Bxjs8musYNFPt</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">20. &ldquo;Bondye Pap Livrem &rdquo;&mdash; Apotre Robenson Joachim</span></p>\r\n<p class=\"p1\"><span class=\"s1\">27 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Apre &ldquo;M&rsquo; Paka Echwe &rdquo; ak &ldquo; Mwen Se Yon Etwal &rdquo;, Apotre Robenson Joachim kontinye yon liy mizikal kote lafwa s&egrave;vi k&ograve;m repons devan opozisyon.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan &ldquo;Bondye Pap Livrem &rdquo;, opozisyon sa a pran plizy&egrave; f&ograve;m: konplo, mechanste, move entansyon ak maji. Men chante a pa bati sou p&egrave; moun nan genyen devan sa yo. Okontr&egrave;, li bati sou yon konviksyon: l&ograve;t moun kapab prepare yon bagay, men yo pa gen kontw&ograve;l absoli sou rezilta final la.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Se diferans sa a ki f&egrave; tit la fonksyone. &ldquo;Bondye Pap Livrem &rdquo; pa vle di atis la pa rekon&egrave;t menas oswa opozisyon,<span class=\"Apple-converted-space\">&nbsp; </span>li vle di li refize konsidere yo k&ograve;m d&egrave;nye otorite sou lavi li.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan yon anviw&ograve;nman kote diskou sou pwoteksyon espirity&egrave;l gen yon plas enp&ograve;tan nan anpil kominote kretyen ayisyen, mizik la antre dir&egrave;kteman nan yon langaj piblik la deja konprann. Li pran enkyetid la epi li reoryante l sou konfyans.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/F9gaT01p2rM?si=tnzLuOrMc8E93Ty3</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">21. &ldquo;Je veux aussi chanter le soir &rdquo;&mdash; Sterlande Etienne &amp; Mike-Lee Elminis</span></p>\r\n<p class=\"p1\"><span class=\"s1\">27 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Je veux aussi chanter le soir &rdquo; s&egrave;vi ak yon imaj ki senp anpil maten ak swa pou pale de yon kestyon ki pi fon: &egrave;ske adorasyon an chanje l&egrave; sikonstans lavi yo chanje?</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Maten an reprezante moman kote limy&egrave; a la, bagay yo par&egrave;t kl&egrave; epi moun nan gen rezon fasil pou chante. Swa a, sitou l&egrave; la nuit vient et tout est noir, reprezante l&ograve;t fas lavi a: konfizyon, doul&egrave;, ens&egrave;titid ak moman kote moun nan pa konnen kisa k ap vini.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Se la desizyon chante a pran tout sans li: mwen vle chante nan maten, men mwen vle chante nan swa tou. Se yon deklarasyon kote adorasyon an pa depann s&egrave;lman de sa moun nan resevwa oswa santi nan moman an.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Sterlande Etienne ak Mike-Lee Elminis pote ansyen kantik sa a nan yon nouvo ent&egrave;pretasyon ki asosye ak Les Bleus d&rsquo;Ha&iuml;ti &amp; Les &Eacute;lus ak Ephata Production.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Pwoj&egrave; sa a ajoute yon l&ograve;t egzanp nan mouvman mwa septanm nan kote ansyen rep&egrave;twa a kontinye jwenn lavi atrav&egrave; nouvo vwa.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/Tuo3kn_K2hI?si=67NWXDXOYnWxkE4M</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">22. &ldquo;Sakrifis &rdquo;&mdash; Frantz Joseph</span></p>\r\n<p class=\"p1\"><span class=\"s1\">27 septanm 2026</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">&ldquo;Sakrifis &rdquo; Frantz Joseph la antre dir&egrave;kteman nan lojik transmisyon ki make yon pati nan Palmar&egrave;s septanm nan.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Sterlande Etienne te pibliye &ldquo;Sakrifis mwen &rdquo;k&ograve;m yon single 11 mas 2026 anba Ephata Production.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Sis mwa apre, Frantz Joseph chwazi retounen sou travay la ak pw&ograve;p ent&egrave;pretasyon li. Sa vle di enter&egrave; cover la pa s&egrave;lman nan paw&ograve;l yo, men nan kestyon sa a: &ldquo;kisa yon l&ograve;t vwa kapab pote nan yon chante piblik la deja konnen?</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">T&egrave;m sakrifis la li menm gen yon plas enp&ograve;tan nan langaj kretyen an. Li pale de renonsman, s&egrave;vis, obeyisans ak kapasite pou mete yon bagay ki pi gran pase pw&ograve;p enter&egrave; p&egrave;son&egrave;l devan.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Frantz Joseph pa ch&egrave;che prezante travay la k&ograve;m yon nouvo konpozisyon. Li antre nan yon mizik ki deja egziste, li rekon&egrave;t Sterlande Etienne k&ograve;m sous travay la epi li ba li yon l&ograve;t koul&egrave; atrav&egrave; pw&ograve;p vwa pa li.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Nan sans sa a, &ldquo;Sakrifis &rdquo; f&egrave;men seleksyon septanm nan sou youn nan tandans ki te pi vizib pandan mwa a: yon mizik gospel ayisyen ki ap kreye nouvo bagay pandan li kontinye retounen sou pw&ograve;p eritaj li.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">https://youtu.be/PLBUY8DH12o?si=xZ6432l5GaZKUqsX</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Palmar&egrave;s Septanm 2026 la montre yon s&egrave;n mizik evanjelik ayisyen ki kontinye evolye sou plizy&egrave; liy ansanm.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Gen nouvo kreyasyon. Gen premye pwodiksyon. Gen kolaborasyon. Gen cover. Gen ansyen kantik ki retounen ak nouvo aranjman. E gen tou t&egrave;ks ki soti nan yon l&ograve;t jenerasyon men ki jwenn nouvo vwa jodi a.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Se rankont ant kreyasyon ak eritaj sa a ki bay mwa septanm nan youn nan karakteristik li.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">T&egrave;m ki retounen yo montre tou ki direksyon anpil nan pwodiksyon yo pran: konfyans, abandon, rekonesans, pwoteksyon, fidelite, renmen, p&egrave;severans ak retou jwenn Bondye.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Men yon palmar&egrave;s pa s&egrave;lman dwe s&egrave;vi pou mete yon lis mizik youn d&egrave;y&egrave; l&ograve;t.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Li kapab s&egrave;vi tou k&ograve;m yon zouti pou dokimante aktyalite mizik evanjelik la, kons&egrave;ve non moun ki patisipe nan pwodiksyon yo, mete nouvo vwa an val&egrave; epi konstwi memwa yon endistri ki kontinye ap evolye mwa apre mwa.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Se nan demach sa a Palmar&egrave;s Mizik/Videyo Evanjelik kontinye suiv, dokimante ak mete an limy&egrave; travay atis, mizisyen, pwodikt&egrave;, reyalizat&egrave; ak l&ograve;t akt&egrave; ki kontribye nan devlopman mizik evanjelik ayisyen an.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">Randevou pou Palmar&egrave;s Okt&ograve;b 2026 la.</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s2\">Redaksyon:</span></p>\r\n<p class=\"p1\"><span class=\"s2\">Vanauscheca Bouzy</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s2\">Konsepsyon Grafik:</span></p>\r\n<p class=\"p1\"><span class=\"s2\">Jo-Flung Bouzy &amp; Abdullah Mode</span></p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p2\">&nbsp;</p>\r\n<p class=\"p1\"><span class=\"s1\">#palmar&egrave;smizikvideyo</span></p>\r\n<p class=\"p1\"><span class=\"s1\">#evanjelik</span></p>\r\n<p class=\"p1\"><span class=\"s1\">#sept2026</span></p>\r\n<p class=\"p1\"><span class=\"s1\"><a href=\"https://www.konektem.net/blog/hashtags/konektem\">#konekte</a>m</span></p>\r\n<p class=\"p1\"><span class=\"s1\">#toutkotenenpotkil&egrave;</span></p>', '2026-10-02 01:37:00', '2026-10-02 01:37:00', NULL, 1);
