INSERT INTO `products` (`id`, `product_type`, `name`, `description`, `price`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'stream', 'Stream test', 'livestream', '0.00', 1, '2026-07-08 07:03:34', NULL),
(2, 'event', 'ASTHARMONIE lève le suspense en invitant le public à la vente signature de son album « ENKONPARAB »', '<p>ASTHARMONIE l&egrave;ve le suspense en invitant le public &agrave; la vente signature de son album &laquo; ENKONPARAB &raquo;, pr&eacute;vue pour le 25 octobre 2026, &agrave; 3h PM, au Karibe Convention Center, au prix de 25 $ US.</p>\r\n<p>Apr&egrave;s plusieurs semaines d&rsquo;attente, le moment tant attendu approche. Astharmonie invite le public &agrave; venir vivre une exp&eacute;rience unique &agrave; l&rsquo;occasion de la vente signature de son premier album.</p>\r\n<p>Rendez-vous donc le 25 octobre 2026, &agrave; 3h PM, au Karibe Convention Center, pour cette grande rencontre. Ne vous contentez pas d&rsquo;en entendre parler, venez vivre ENKONPARAB !</p>', '25.00', 1, '2026-08-11 15:27:11', NULL),
(3, 'event', 'LIAJECH, CJFPH et KONEKTE M vous donnent rendez-vous à la Journée Internationale de la Jeunesse 2026, Samedi 15 août 2026 à l\'Hôtel Ritz Kinam II.', '<p>LIAJECH, CJFPH et KONEKTE M vous donnent rendez-vous &agrave; la Journ&eacute;e Internationale de la Jeunesse 2026, Samedi 15 ao&ucirc;t 2026 &agrave; l\'H&ocirc;tel Ritz Kinam II.</p>\r\n<p><br>&Agrave; l\'occasion de la Journ&eacute;e Internationale de la Jeunesse, la Ligue des Associations de Jeunesse Chr&eacute;tienne d\'Ha&iuml;ti (LIAJECH), en partenariat avec la CJFPH et le m&eacute;dia KONEKTE M, convie toute la jeunesse ha&iuml;tienne &agrave; une journ&eacute;e exceptionnelle de r&eacute;flexion, de formation et de c&eacute;l&eacute;bration autour du th&egrave;me : &laquo; La jeunesse : une g&eacute;n&eacute;ration qui s\'engage. &raquo;</p>\r\n<p>Pr&eacute;vu pour le samedi 15 ao&ucirc;t 2026, &agrave; partir de 9h AM, &agrave; l\'H&ocirc;tel Ritz Kinam II, cet &eacute;v&eacute;nement r&eacute;unira des jeunes issus de diff&eacute;rents horizons afin de promouvoir le leadership, l\'engagement citoyen et la participation active des jeunes dans le d&eacute;veloppement d\'Ha&iuml;ti.</p>\r\n<p>Les participants auront droit &agrave; un programme vari&eacute;, alliant conf&eacute;rences, &eacute;changes, comp&eacute;titions et activit&eacute;s culturelles, dans une ambiance propice &agrave; l\'apprentissage, au r&eacute;seautage et &agrave; l\'inspiration.</p>\r\n<p>Que vous soyez &eacute;tudiant, membre d\'une association, jeune professionnel ou simplement engag&eacute; pour l\'avenir de la jeunesse, cette journ&eacute;e est une occasion unique de vous former, de partager vos exp&eacute;riences et de contribuer &agrave; b&acirc;tir une g&eacute;n&eacute;ration consciente, responsable et d&eacute;termin&eacute;e &agrave; faire la diff&eacute;rence.</p>\r\n<p>Le 15 ao&ucirc;t, prenez part au mouvement. La jeunesse s\'engage, et votre place est parmi nous !</p>', '0.00', 1, '2026-08-11 15:30:08', NULL),
(4, 'event', 'Eglise Roc Solide de Tabarre vous convie à une semaine de consécration, d\'adoration et d\'enseignements bibliques à l\'occasion de la Kadosh Conférence 2026', '<p>L\' Eglise Roc Solide de Tabarre vous convie &agrave; une semaine de cons&eacute;cration, d\'adoration et d\'enseignements bibliques &agrave; l\'occasion de la Kadosh Conf&eacute;rence 2026.</p>\r\n<p>Du 9 au 16 ao&ucirc;t 2026, de 4 h &agrave; 7 h PM, venez vivre des moments intenses dans la pr&eacute;sence de Dieu &agrave; travers des pr&eacute;dications, des moments de pri&egrave;re et des instants de communion fraternelle, anim&eacute;s par plusieurs serviteurs et servantes de Dieu.</p>\r\n<p>Que vous soyez en qu&ecirc;te d\'un renouveau spirituel, d\'encouragement ou d\'une communion plus profonde avec le Seigneur, cette conf&eacute;rence est un rendez-vous &agrave; ne pas manquer.</p>\r\n<p>Rendez-vous &agrave; l\'&Eacute;glise Roc Solide de Tabarre, 1, Impasse Roc Solide, Tabarre 27. Venez nombreux et invitez vos proches &agrave; partager cette exp&eacute;rience de foi exceptionnelle.</p>\r\n<p>#kadosh<br>#konektem<br>#toutkotenenp&ograve;tkil&egrave;</p>', '0.00', 1, '2026-08-11 20:26:18', NULL),
(5, 'event', 'Ishama Gospel a l’honneur de convier la presse, les médias, ainsi que l’ensemble de ses partenaires et artistes collaborateurs à une conférence de presse qui se tiendra le samedi 15 août 2026 à 11h AM, au CDFTL (Centre Diplomatique Famille Tabernacle de L', '<p>Dans le cadre du lancement officiel du grand &eacute;v&eacute;nement \"911\", Ishama Gospel a l&rsquo;honneur de convier la presse, les m&eacute;dias, ainsi que l&rsquo;ensemble de ses partenaires et artistes collaborateurs &agrave; une conf&eacute;rence de presse qui se tiendra le samedi 15 ao&ucirc;t 2026 &agrave; 11h AM, au CDFTL (Centre Diplomatique Famille Tabernacle de Louange), Waney 93, Carrefour.</p>\r\n<p>Cette rencontre permettra de d&eacute;voiler les d&eacute;tails du programme pr&eacute;vu, de pr&eacute;senter les moments forts de \"911\" et de partager les grandes lignes de cette initiative.</p>\r\n<p>La pr&eacute;sence des journalistes, m&eacute;dias, partenaires et artistes collaborateurs est vivement souhait&eacute;e pour marquer ensemble le coup d&rsquo;envoi officiel de ce grand &eacute;v&eacute;nement.</p>\r\n<p>NB : Les accr&eacute;ditations pour la couverture m&eacute;diatique officielle du concert seront d&eacute;livr&eacute;es exclusivement aux journalistes et m&eacute;dias pr&eacute;sents lors de cette conf&eacute;rence de presse.</p>\r\n<p>#konektem<br>#toutkotenenp&ograve;tkil&egrave;</p>', '0.00', 1, '2026-08-11 20:28:48', NULL),
(6, 'event', 'Rolande Louis en Concert', '', '1500.00', 1, '2026-08-17 01:52:20', NULL),
(7, 'event', 'L\'Église Sur Le Rocher vous invite à une semaine de célébration et d\'action de grâce à l\'occasion de son 37e anniversaire, du 23 au 30 août 2026', '<p>&nbsp;&Agrave; l\'occasion de son 37e anniversaire, L\'Eglise Sur Le Rocher Ha&iuml;ti a la joie de vous inviter &agrave; prendre part &agrave; une semaine de c&eacute;l&eacute;bration et d\'action de gr&acirc;ce, qui se d&eacute;roulera du 23 au 30 ao&ucirc;t 2026, sous le th&egrave;me &laquo; &Eacute;b&eacute;n&eacute;zer &raquo;, inspir&eacute; de 1 Samuel 7:12 : &laquo; Jusqu\'ici, l\'&Eacute;ternel nous a secourus. &raquo;</p>\r\n<p>Cette semaine sera marqu&eacute;e par des moments intenses de louange, d\'adoration, de pri&egrave;re, de pr&eacute;dication et de reconnaissance envers Dieu pour Sa fid&eacute;lit&eacute; durant ces 37 ann&eacute;es de minist&egrave;re. Le point culminant de cette c&eacute;l&eacute;bration sera la Grande C&eacute;l&eacute;bration, pr&eacute;vue le dimanche 30 ao&ucirc;t 2026, de 7h30 &agrave; 11h AM.</p>\r\n<p>Votre pr&eacute;sence sera pour nous un v&eacute;ritable honneur et une immense joie !</p>\r\n<p>#konektem<br>#toutkotenenpotkile</p>', '0.00', 1, '2026-08-18 19:08:08', NULL),
(8, 'event', 'WILIADEL DENERVIL : UNE DÉCENNIE DE CARRIÈRE, ET L’AVENTURE CONTINUE', '<p>WILIADEL DENERVIL : UNE D&Eacute;CENNIE DE CARRI&Egrave;RE, ET L&rsquo;AVENTURE CONTINUE.&nbsp;</p>\r\n<p>Apr&egrave;s le Canada, une r&eacute;cente &eacute;tape en France et un concert m&eacute;morable en R&eacute;publique dominicaine, Wiliadel Denervil poursuit son parcours et continue de multiplier les rendez-vous.</p>\r\n<p>Le 27 septembre 2026, c&rsquo;est au tour de Port-au-Prince de c&eacute;l&eacute;brer ses 10 ans de carri&egrave;re, lors d&rsquo;un grand rendez-vous au Palais Municipal de Delmas, pr&eacute;sent&eacute; par Lophane\'s Project.</p>\r\n<p>📍 Palais Municipal de Delmas<br>📅 27 septembre 2026</p>\r\n<p>10 ANS, UNE VOIX, UNE HISTOIRE&hellip;<br>ET L&rsquo;AVENTURE CONTINUE.</p>\r\n<p>#konektem<br>#toutkotenenp&ograve;tkil&egrave;</p>', '1000.00', 1, '2026-08-18 19:26:03', NULL),
(9, 'event', 'CAJEBD en pique-nique 2026 : Rendez-vous, le samedi 29 Aout 2026', '<p>Le quotidien nous laisse rarement le temps de souffler. Entre les &eacute;tudes, le travail et les pr&eacute;occupations de la vie, les occasions de se retrouver et de partager des moments authentiques deviennent de plus en plus rares. Et si vous vous accordiez une journ&eacute;e pour tout oublier ?</p>\r\n<p>CAJEBD vous donne rendez-vous le samedi 29 ao&ucirc;t 2026, &agrave; la Quisqueya Christian School (Delmas 75), pour la deuxi&egrave;me &eacute;dition de &laquo; CAJEBD en Pique-Nique &raquo;. &nbsp;Au fil de la journ&eacute;e, les participants auront l\'occasion de prendre part &agrave; une programmation vari&eacute;e, jeux et animations, musique, karaok&eacute;, conf&eacute;rence-d&eacute;bat, s&eacute;ance photo, d&eacute;gustation, d&eacute;fis et plusieurs autres activit&eacute;s.&nbsp;</p>\r\n<p>Les places sont tr&egrave;s limit&eacute;es. Afin de garantir le bon d&eacute;roulement de l\'activit&eacute;, seul un effectif restreint sera accueilli. &nbsp;R&eacute;servez votre place d&egrave;s maintenant en contactant le (+509) 39 99 3281 ou le (+509) 35 26 8581. Ne laissez pas passer cette occasion de vivre une journ&eacute;e diff&eacute;rente avec la famille CAJEBD-B&eacute;thel !</p>\r\n<p>#konektem<br>#toutkotenenp&ograve;tkil&egrave;</p>', '0.00', 1, '2026-08-18 19:37:42', NULL),
(10, 'event', 'Be united', '<p>Be united is the best way to grow and to succeed.</p>', '2.00', 1, '2026-09-02 21:29:13', NULL),
(11, 'event', 'DETANT KRETYEN', 'Randevou chak vandredi nan Dèlma 75 pou w koze ak atis prefere w yo, tande istwa la vi yo, motivasyon ak pasyon yo.', '0.00', 1, '2026-09-03 09:45:40', NULL),
(12, 'event', 'STAND UP FOR LYNDA JOSEPH', 'Dans un élan de solidarité qui dépasse les murs du sanctuaire, l’Église Rendez-Vous Christ, en collaboration avec Media Levanjil, Konektem, À l’Unisson et Lophane Project, convie le public à un concert exceptionnel le 14 décembre 2025. Proposé au prix symbolique de 1 000 gourdes, cet événement vise à soutenir Lynda Joseph à travers une soirée où musique, foi et compassion s’uniront pour porter un message d’espérance.\r\nLes participants seront également invités à renforcer cet acte de générosité par des dons additionnels, afin de contribuer encore davantage à cette noble cause.', '2.00', 1, '2026-09-03 09:45:40', NULL),
(13, 'event', 'JEZI OOO - NESLIN DESTILHOMME GONAIVES', '<p>Nan vil Gonayiv, yon gwo randevou adorasyon tanmen pare pou make fen ane a. Jou k ap samdi 6 desanm 2025 lan, a 4ï¿½ nan lapremidi, nan Pak Vincent. @neslindestilhomme ap tann nou tout nan yon bouyon adorasyon, ki se Konsï¿½ ï¿½ï¿½Jezi Ohï¿½ï¿½ a. Yon Aktivite ki rasanble plizyï¿½ atis ak gwoup kretyen, tankou Rod Ume Dieujuste, @joyclerfderisier, @loutchina_music, Zï¿½n Pa Fï¿½ Moun Band ak Wency Le Slameur. Caribbean Worshippers envite piblik la, jï¿½n kou granmoun, fanmi kou zanmi, pou pa rate randevou sa a. Si w ap chï¿½che yon kote pou w rekonekte ak Bondye, renouvle lafwa w epi amize w nan prezans Bondye, Konsï¿½ ï¿½ï¿½Jezi Ohï¿½ï¿½, nan Gonayiv se kote w dwe ye a</p>', '0.00', 1, '2026-09-03 09:45:40', NULL),
(14, 'event', 'SIMIANE RUACH TOUR', 'SIMIANE Ruach Tour. live performance: Jean Jean, Esther Desi, Transfomasyon Band.\r\n\r\n \r\nRéservez Vos billets maintenant sur eventbrite 👇👇\r\nhttps://www.eventbrite.com/e/1966354383895?aff=oddtdtcreator', '0.00', 1, '2026-09-03 09:45:40', NULL),
(15, 'event', '6e edition Caribbean Worshippers', '<div class=\"xdj266r x14z9mp xat24cr x1lziwak x1vvkbs x126k92a\">\r\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t1f/2/16/27a1.png\" alt=\"&acirc;ž&iexcl;&iuml;&cedil;\" width=\"16\" height=\"16\"></span> Ce grand rendez-vous spirituel, organis&eacute; par le psalmiste Neslin Destilhomme, connu pour mobiliser des milliers de fid&egrave;les &agrave; chacune de ses initiatives, r&eacute;unira cette ann&eacute;e des adorateurs et des leaders chr&eacute;tiens venus d&rsquo;Ha&iuml;ti, des &Eacute;tats-Unis et du Canada.<br><br></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\">Cette rencontre spirituelle vise &agrave; cr&eacute;er un espace de louange et de pri&egrave;re favorisant une connexion profonde &agrave; la pr&eacute;sence de Dieu et la croissance spirituelle des participants. La 6e &eacute;dition, organis&eacute;e autour du th&egrave;me &laquo; BENI BENI N&Egrave;T &raquo;, annonce une programmation de haut niveau, selon les pr&eacute;cisions de <span class=\"html-span xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs\"><a class=\"x1i10hfl xjbqb8w x1ejq31n x18oe1m7 x1sy0etr xstzfhl x972fbf x10w94by x1qhh985 x14e42zd x9f619 x1ypdohk xt0psk2 x3ct3a4 xdj266r x14z9mp xat24cr x1lziwak xexx8yu xyri2b x18d9i69 x1c1uobl x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz xkrqix3 x1sur9pj x1fey0fg x1s688f\" tabindex=\"0\" role=\"link\" href=\"https://web.facebook.com/profile.php?id=100063886113458&amp;__cft__[0]=AZZ9Mi5EY7jV6JhwKdvRWBCP7k2OfAsaKoJMZcqwH5LmR8zYphbZSwYw3yXYdRNrxPxDrQt3-dSNdrUfYKjnASY-XamECrDNSh6UH7EHGW4MooM1fsHkqRyHSbZhQTEOTSKqiKClzeD8QfwO6oVpcVikCRbwuptfY6s5XI932MDEQcTLB_-wgMGaI2GEfWE885A&amp;__tn__=-]K-R\"><span class=\"xt0psk2\"><span class=\"xjp7ctv\">Neslin Destilhomme</span></span></a></span></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\">L&rsquo;&eacute;v&eacute;nement rassemblera un panel d&rsquo;adorateurs et de leaders spirituels engag&eacute;s &agrave; conduire le peuple dans un moment intense de communion et d&rsquo;&eacute;dification spirituelle.<br><br></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\">KONEKTEM s&rsquo;engage &agrave; vous informer de chaque &eacute;tape et de tous les d&eacute;tails de ce grand rendez-vous spirituel. Restez connect&eacute;s.<br><br></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t4b/2/16/1f4cc.png\" alt=\"&eth;&Yuml;&ldquo;&OElig;\" width=\"16\" height=\"16\"></span> Informations et dons</div>\r\n<div dir=\"auto\">Zelle : 954 336 9155</div>\r\n<div dir=\"auto\">PayPal : <a href=\"mailto:neslindestilhome87@gmail.com\">neslindestilhome87@gmail.com</a><br><br></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\">\r\n<div dir=\"auto\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\"><img class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t63/2/16/270d.png\" alt=\"&acirc;&oelig;&iuml;&cedil;\" width=\"16\" height=\"16\"></span> R&eacute;daction : Vanauscheca P. Bouzy<br><br></div>\r\n</div>\r\n<div class=\"x14z9mp xat24cr x1lziwak x1vvkbs x